// @ts-nocheck
/* eslint-disable */
/**
 * Opportunities page engine (Board + List). GENERATED by tools/sync-opportunities.mjs from web/pages/lead.xhtml (+ components/access_pop · lead/filter_modal · move_step_modal, css/lead.css) — do not edit; change the script and run `npm run opportunities:sync`.
 *
 * The page script of the Java screen, same behaviour line by line: the product / workflow-group dropdowns, the status summary
 * and the WF-step summary, the sort, the search with its suggestion card, the board (kanban columns, per-column infinite
 * scroll, drag & drop with the move-step modal), the list (infinite scroll), the filter dialog with its master data and saved
 * state, the "ผู้มีสิทธิ์เข้าถึง" popover. The five <script> blocks of lead.xhtml and its includes, in the order the browser ran them.
 *
 * WHY it is imperative DOM code and not Angular components: the Java page is a data-driven DOM application whose HTML is drawn
 * from API data as strings. Porting it 1:1 is what guarantees the screen, texts and states are identical to the production
 * system; the template (opportunities.html) and stylesheet (opportunities.scss) are the Java markup / CSS verbatim and the engine binds to them
 * through the same ids / classes as before.
 * "@ts-nocheck": the source is ES5 written for a browser global scope; typing it would change it, not port it.
 *
 * What changed versus the Java files (all of it lives in tools/sync-opportunities.mjs):
 *   - the environment is injected (OpportunitiesEnv): messages, the permissions the EL asked for, the employee id of the session, the
 *     filter state the server kept in the HttpSession, fetch (every /board/… call goes to the page's backend), navigation —
 *     in Java these were EL expressions, window.fetch, navigator.sendBeacon and window.location;
 *   - the addresses of the images are the ones under assets/images (Java: ../images/…);
 *   - the window.* names the blocks publish, the global "CAN_…" values, the listeners on document, the timers and the board
 *     auto-scroll interval are removed by the function returned from startOpportunities().
 */

export interface OpportunitiesEnv {
  /** commonBean.msg['key'] in the active language */
  t: (key: string) => string;
  /** commonBean.hasFeature('KEY') / SessionRoles.hasRole('KEY') of the signed-in user */
  can: (feature: string) => boolean;
  /** the button registry (core/permissions/access-buttons.ts): may the signed-in user use this button? (the engine asks for PL-OP-LS-06, the drag of a card) */
  access: (code: string) => boolean;
  /** #{commonBean.ssEmployeeId}: the employee id of the session ('' when unknown) */
  employeeId: string;
  /** the BFF contract of the page: /board/leads · /board/master/movement-types · /board/tags … (addresses as the Java page wrote them: '../board/…') */
  fetch: (input: string, init?: RequestInit) => Promise<Response>;
  /** the values LeadBoardView rendered into the page with EL (savedFilterJson: the filter state of the HttpSession, null when none) */
  initial: (name: string) => any;
  /** #{request.contextPath} — the base of the address that odsProspectSuggest builds (…/board/prospect-list) */
  ctx: string;
  /** navigator.sendBeacon(url, json): POST /board/filter-state, fire and forget */
  beacon: (url: string, body: string) => void;
  /** window.location.href = 'lead_detail.face?…' — the host maps the Java address to the route (javaLinkToRoute) */
  navigate: (url: string) => void;
  /** location.reload(): the host starts the page again with fresh initial data */
  reload: () => void;
  /** the address an <img> loads a picture of the backend from (Java: ../docproxy?url=… for http(s):// pictures) */
  docProxy: (url: string) => string;
}

export function startOpportunities(env: OpportunitiesEnv): () => void {
  var destroyed = false;
  var disposers = [];
  var timers = [];
  var observers = [];
  function listen(target, type, fn, opts) {
    target.addEventListener(type, fn, opts);
    disposers.push(function () { target.removeEventListener(type, fn, opts); });
  }
  function tmo(fn, ms) { var h = setTimeout(function () { if (!destroyed) { fn(); } }, ms); timers.push(h); return h; }
  function track(o) { observers.push(o); return o; }
  /* document.readyState / DOMContentLoaded / load of the page the script was written for (see the generator) */
  var readyState = 'loading';
  var readyQueue = [];
  var loadQueue = [];
  function onReady(fn) { if (readyState === 'loading') { readyQueue.push(fn); } else { tmo(fn, 0); } }
  function onLoad(fn) { if (readyState !== 'complete') { loadQueue.push(fn); } else { tmo(fn, 0); } }
  function runQueue(queue, type) {
    queue.splice(0).forEach(function (fn) {
      try { fn.call(type === 'load' ? window : document, new Event(type)); } catch (e) { console.error(e); }
    });
  }

  /* Nothing that is still in flight when the screen is left may repaint it: after destroy() a request never settles. */
  var rawFetch = env.fetch;
  var never = function () { return new Promise(function () {}); };
  var guardResponse = function (r) {
    return {
      ok: r.ok, status: r.status, statusText: r.statusText, headers: r.headers, url: r.url,
      clone: function () { return guardResponse(r.clone()); },
      json: function () { return r.json().then(function (v) { return destroyed ? never() : v; }); },
      text: function () { return r.text().then(function (v) { return destroyed ? never() : v; }); },
      blob: function () { return r.blob().then(function (v) { return destroyed ? never() : v; }); },
      arrayBuffer: function () { return r.arrayBuffer().then(function (v) { return destroyed ? never() : v; }); }
    };
  };
  env = Object.assign({}, env, {
    fetch: function (a, b) {
      if (destroyed) { return never(); }
      return rawFetch(a, b).then(
        function (r) { return destroyed ? never() : guardResponse(r); },
        function (e) { return destroyed ? never() : Promise.reject(e); });
    }
  });
  var __initial = env.initial;
  env.initial = function (name) { return JSON.parse(JSON.stringify(__initial(name))); };
  var __cleanups = [];
  /* the popover is part of the template but the page moves it into .ld-col-body / <body>: remember it, take it away on destroy */
  var __pop = document.getElementById('ldAccessPop');


  /* ════════════════ lead.xhtml · skeleton toggle (runs before the page script; SAVED_FILTER is private to that script, so it never finds it — as in Java) ════════════════ */
(function(){
                        var sf = (typeof SAVED_FILTER !== 'undefined') ? SAVED_FILTER : null;
                        if(sf && sf.tab === 'list'){
                            var b = document.getElementById('ldSkelBoard');
                            var l = document.getElementById('ldSkelList');
                            if(b) b.style.display = 'none';
                            if(l) l.style.display = 'flex';
                        }
                    })();

  /* ════════════════ lead.xhtml · page script ════════════════ */
/* มี role CRM_Lead_View ไหม — gate การคลิกการ์ด/แถวไป lead_detail.face (ไม่มี = กดไม่ได้) */
            var CAN_VIEW_LEAD_DETAIL = env.can('CRM_Lead_View');

            /* มี role CRM_ContactActivity_Create ไหม — gate การลากการ์ดย้ายคอลัมน์ (คือการบันทึก contact activity
               ตัวปลายทางจริงๆ คือ POST ../board/contact-activities — เดิมใช้ CRM_Lead_Edit ไปก่อน ไม่ตรง
               ความหมาย เปลี่ยนให้ตรงกับ key ที่ lead_detail.xhtml ใช้กับ action เดียวกันนี้แล้ว)
               ★ 26/08: เหมือน lead_detail.xhtml — มี role หลักอย่างเดียวไม่พอ ต้องเป็น "ผู้รับผิดชอบ"
               (employeeId) ของ lead ใบนั้นด้วย ยกเว้นมี role ต่อท้าย _Sup (หัวหน้า) ข้ามเงื่อนไขนี้ได้เลย
               ต่างจาก lead_detail ตรงที่หน้านี้เป็น board มีหลาย lead พร้อมกัน (คนละใบ คนละ owner) →
               เช็ค "เจ้าของ" ต้องทำ "ต่อการ์ด" ไม่ใช่ตัวแปร global ตัวเดียวเหมือน lead_detail — ดู
               ldCanMoveLead(employeeId) ด้านล่าง CAN_CONTACT_ACTIVITY_CREATE ตัวนี้เป็นแค่ค่า role+sup
               รวม (ไม่รู้ owner) ใช้เป็น fallback ตอนยังไม่รู้ว่าเป็น lead ใบไหน (เช่น apiCardHtml ตอน build
               การ์ดทั้งบอร์ด) ส่วนจุดที่ลากย้ายจริง (moveLeadKanban/moveLead) ต้องเช็คผ่าน ldCanMoveLead()
               ที่รู้ employeeId ของ lead ใบนั้นแล้วเท่านั้น */
            var CAN_ROLE_CONTACT_ACTIVITY_CREATE = env.can('CRM_ContactActivity_Create');
            var CAN_SUP_CONTACT_ACTIVITY_CREATE = env.can('CRM_ContactActivity_Create_Sup');
            var CAN_CONTACT_ACTIVITY_CREATE = CAN_SUP_CONTACT_ACTIVITY_CREATE || CAN_ROLE_CONTACT_ACTIVITY_CREATE;

            /* id พนักงานของผู้ login ปัจจุบัน (session ss_employee_id — เดียวกับที่ lead_detail.xhtml ใช้) */
            var LEAD_MY_EMPLOYEE_ID = env.employeeId;

            /* true ถ้า employeeId ที่ส่งมา (ของ lead การ์ดนั้นๆ บนบอร์ด) ตรงกับผู้ login — ไม่รู้ id ตัวเอง/
               lead ยังไม่มีผู้รับผิดชอบ → ถือว่าไม่ตรง (fail-closed) */
            function ldBoardOwnerMatches(employeeId) {
                if (!LEAD_MY_EMPLOYEE_ID) return false;
                var eid = (employeeId != null) ? String(employeeId) : '';
                return !!eid && eid === LEAD_MY_EMPLOYEE_ID;
            }

            /* เช็คสิทธิ์ลากย้าย lead ใบที่มี employeeId นี้ — _Sup ข้าม owner-check ได้, role หลักต้องเป็นเจ้าของเอง */
            function ldCanMoveLead(employeeId) {
                return env.access('PL-OP-LS-06') && !!(CAN_SUP_CONTACT_ACTIVITY_CREATE || (CAN_ROLE_CONTACT_ACTIVITY_CREATE && ldBoardOwnerMatches(employeeId)));
            }

            /* lead.css (external, static) ใช้ .ld-col-target::after{content:var(--ld-drop-hint-text,'')}
               เพราะย้าย CSS ออกจาก inline แล้ว EL ในไฟล์ .css จะไม่ถูก evaluate — bridge ข้อความ
               ที่แปลแล้วเข้า CSS custom property ตรงนี้แทน (ต้องมี quote ล้อมในค่าเอง เพราะ content ต้องการ <string>) */
            document.documentElement.style.setProperty('--ld-drop-hint-text', "'" + env.t("label.lead.drag_drop_hint") + "'");

            /* navigate to lead_detail — activityGroupId (group ที่บอร์ดกำลังกรอง/แสดงอยู่ตอนคลิก) แนบไปด้วย
               ให้ lead_detail.xhtml เอาไปต่อ ../board/lead?id= (ดู getActivityGroupIdFromUrl)
               ★ 15/09/2026 — เดิมมีขั้นตอนเซฟ sessionStorage 'ld_selected' (prefill หน้า lead_detail ก่อน API
               มา) ตรงนี้ด้วย แต่ window._ldDATA.leads ว่างเปล่าตลอด (ค้างจากยุค mock ตั้งแต่เปลี่ยนมาใช้ API จริง
               — ดู productBlock/render() ที่ไม่เคยถูกเรียกด้วยข้อมูลจริงอีกแล้ว) จึงไม่เคยเจอ lead แล้วไม่เคยเซฟ
               จริงอยู่แล้ว ตอนนี้ตัดทิ้งทั้งคู่ (ฝั่งอ่านใน lead_detail.xhtml ก็ตัดออกแล้ว) ตามที่ user สั่ง — ไม่มี
               ข้อมูลจริงก็ให้โล่ง/skeleton ไว้ก่อน ไม่ใช้ค่า "เดา" จากหน้าที่กดมา */
            window.ldSelectLead = function(id, activityGroupId){
                if(!CAN_VIEW_LEAD_DETAIL) return;   /* ไม่มี CRM_Lead_View → กดไม่ได้ */
                if(window.ldSaveFilterState) window.ldSaveFilterState();   /* บันทึก filter ก่อนออกจากหน้า */
                var url = 'lead_detail.face?pid=1&page_id=3&act=3&param_lead_id='+id;
                /* ★ 20/10/2026 — 0 = ทุกกลุ่ม ไม่ใช่ id จริง → ไม่แนบ (เหมือน leadDetailUrl ของ dashboard.js) */
                var agid = activityGroupId == null ? '' : String(activityGroupId).trim();
                if(agid && agid !== '0') url += '&activityGroupId='+encodeURIComponent(agid);
                env.navigate(url);
            };

            (function(){

                var DATA = null;
                /* ★ ไม่มี API ตัวไหน inject จาก bean แล้ว — @PostConstruct ที่ยิง API ทำให้ทั้งหน้า
                   (รวมเมนูข้าง/บนที่มาจาก template.xhtml response เดียวกัน) ต้องรอ API ก่อนถึงจะได้
                   HTML สักไบต์ เมนูเลยหายไปทั้งแถบทุกครั้งที่เข้าหน้า ตอนนี้ bean คืนแค่ filter state
                   จาก session (ไม่มี network) หน้าจึง render ทันที แล้วค่อยเติมข้อมูลทีหลัง
                   PRODUCT_TYPES เติมโดย loadProductTypes() (../board/master/movement-types) */
                var PRODUCT_TYPES = [];
                /* true เมื่อ movement-types/LD คืนว่าง (ไม่มีผลิตภัณฑ์) → ไม่มีผลิตภัณฑ์ = ไม่มีกลุ่มขั้นตอนด้วย
                   ใช้บังคับซ่อน ldGroupWrap เสมอ ไม่ว่า leads API (ยิงขนานกัน) จะตอบ usesWorkflowStep มาว่าอะไร */
                var PRODUCTS_EMPTY = false;
                /* movementTypeId ที่ server ตอบกลับมาล่าสุด — ใช้ sync dropdown ย้อนหลังเมื่อ
                   movement-types มาถึงช้ากว่า leads (ยิงขนานกัน ไม่การันตีลำดับ) */
                var LAST_SERVER_MID = null;
                /* filter state ที่บันทึกไว้ใน Java HttpSession — inject ตอน render, restore ทันทีโดยไม่ต้อง fetch */
                var SAVED_FILTER = env.initial("savedFilterJson");
                /* activity-groups: เลิกใช้แล้ว (ลบ loadActivityGroups ฝั่ง bean) — คงตัวแปรว่างไว้กัน ReferenceError */
                var ACTIVITY_GROUPS = {};
                /* Stepper palette — สีของ step แต่ละตำแหน่ง ขึ้นกับ total step count (1–12) */
                var STEPPER_PALETTE = [
                    [],
                    ['#0C8E6A'],
                    ['#0C8E6A','#6043B6'],
                    ['#0C8E6A','#0D61CF','#6043B6'],
                    ['#0C8E6A','#1A8FE3','#0D61CF','#6043B6'],
                    ['#0C8E6A','#0AA77C','#1A8FE3','#0D61CF','#6043B6'],
                    ['#0C8E6A','#0AA77C','#1A8FE3','#0D61CF','#6043B6','#7F63D2'],
                    ['#0C8E6A','#0AA77C','#00C08B','#1A8FE3','#0D61CF','#6043B6','#7F63D2'],
                    ['#0C8E6A','#0AA77C','#00C08B','#009ED0','#1A8FE3','#0D61CF','#6043B6','#7F63D2'],
                    ['#0C8E6A','#0AA77C','#00C08B','#009ED0','#1A8FE3','#0D61CF','#6043B6','#7F63D2','#B7A4EF'],
                    ['#0C8E6A','#0AA77C','#00C08B','#62E1B3','#009ED0','#1A8FE3','#0D61CF','#6043B6','#7F63D2','#B7A4EF'],
                    ['#0C8E6A','#0AA77C','#00C08B','#62E1B3','#80E8FF','#009ED0','#1A8FE3','#0D61CF','#6043B6','#7F63D2','#B7A4EF'],
                    ['#0C8E6A','#0AA77C','#00C08B','#62E1B3','#80E8FF','#1DCBF1','#009ED0','#1A8FE3','#0D61CF','#6043B6','#7F63D2','#B7A4EF']
                ];
                function stepperColor(total, idx){
                    var row = STEPPER_PALETTE[Math.min(total, 12)] || STEPPER_PALETTE[12];
                    return row[Math.min(idx, row.length - 1)] || '#0C8E6A';
                }

                function g(id){ return document.getElementById(id); }
                function esc(s){ return (s==null?'':String(s)).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
                function fmt(n){ return n.toLocaleString(); }
                function ldColTotal(col, items){
                    var sum = col && col.sumAmount != null && col.sumAmount !== '' ? Number(col.sumAmount) : NaN;
                    if (isFinite(sum)) return sum;
                    return (items || []).reduce(function(a,b){ var n = Number(b && b.amount); return a + (isFinite(n) ? n : 0); }, 0);
                }
                /* ── สี pill แท็ก (ทั้ง tab board + tab list) — กฎเดียวกับหน้า lead_detail (TagPillColor.style) ──
                   ที่มาของสี (ลำดับเดียวกับ lead_detail): colorCode ที่มากับ tag ของ lead เอง (ถ้า API list ส่ง tag มาเป็น object) →
                   master /board/tags (name → colorCode, เติมจาก filter modal ผ่าน window.ldSetTagColors) → ไม่มีสี = ไม่ใส่ style
                   ใช้สี default ของ .ld-card-tag เดิม ; ชื่อแท็กเก็บใน data-tag ไว้ให้ recolorTagPills() ทาสีย้อนหลังตอน master มาถึงช้ากว่าแถว */
                var TAG_COLORS = {};   /* name → colorCode (master-data/tags) */
                function tagPillStyle(color){ return (window.TagPillColor && color) ? window.TagPillColor.style(color) : ''; }
                function tagPillHtml(t){
                    var nm = typeof t === 'string' ? t : (t.name || t.label || t.text || '');
                    if(!nm) return '';
                    var color = (t && typeof t === 'object' && t.colorCode) ? t.colorCode : (TAG_COLORS[nm] || '');
                    var st = tagPillStyle(color);
                    return '<span class="ld-card-tag'+(st ? ' ld-card-tag-c' : '')+'" data-tag="'+esc(nm)+'"'+(st ? ' style="'+st+'"' : '')+'>'+esc(nm)+'</span>';
                }
                /* master แท็กมาถึงหลังแถว/การ์ดถูกวาดไปแล้ว → ทาสีให้ pill ที่ยังไม่มีสี */
                function recolorTagPills(){
                    Array.prototype.forEach.call(document.querySelectorAll('.ld-card-tag[data-tag]:not(.ld-card-tag-c)'), function(el){
                        var st = tagPillStyle(TAG_COLORS[el.getAttribute('data-tag')]);
                        if(st){ el.setAttribute('style', st); el.classList.add('ld-card-tag-c'); }
                    });
                }
                /* รูปจาก backend อาจเป็น http:// ตรงๆ → โดน mixed-content บล็อกตอนหน้ารันบน https ต้องผ่าน /docproxy เสมอ (path relative ในระบบ เช่น assets/images/... ไม่แตะ) */
                function proxyImg(u){
                    if(!u) return '';
                    u = ('' + u).trim();
                    if(!u) return '';
                    var l = u.toLowerCase();
                    return (l.indexOf('http://') === 0 || l.indexOf('https://') === 0)
                        ? env.docProxy(u) : u;
                }
                /* เช็คว่า field จาก backend เป็น link url จริงไหม (ไม่ใช่ id/ชื่อไฟล์เปล่าๆ) — ใช้คู่กับ field ที่ backend สัญญาว่าจะส่งเป็น url แต่ยังไม่เสถียร */
                function isLinkUrl(u){
                    if(!u) return false;
                    var l = ('' + u).trim().toLowerCase();
                    return l.indexOf('http://') === 0 || l.indexOf('https://') === 0;
                }

                function statusCls(s){ return s==='SUCCESS'?'ld-success':s==='LOST'?'ld-lost':s==='NEW'?'ld-new':'ld-active'; }

                /* สีของแต่ละสถานะ (รองรับทั้ง workflow step และ pipeline ของผลิตภัณฑ์ D) */
                function statusColor(s){
                    var m = { SUCCESS:'#00C08B', FOLLOW1:'#6366F1', FOLLOW2:'#F59E0B', FOLLOW3:'#3B82F6', FOLLOW4:'#8B5CF6', LOST:'#EF4444',
                              PRESENT:'#00C08B', OFFER:'#6366F1', PAYMENT:'#F59E0B', SHIPPING:'#3B82F6' };
                    return m[s] || '#6B7280';
                }
                /* badge สถานะ: พื้นสีจาง + ตัวอักษรสี + จุดวงกลมสีนำหน้า */
                function statusBadge(s){
                    var c = statusColor(s);
                    return '<span class="ld-status-badge" style="background:'+c+'1A;color:'+c+';">'
                        +'<span class="ld-badge-dot" style="background:'+c+';"></span>'+esc(s)+'</span>';
                }

                /* ความน่าสนใจ (interest) — text = สีเต็ม, bg = สีจาง 20% */
                function interestColor(s){
                    var m = { HOT:'#EB5050', WARM:'#FF8E4E', COLD:'#4B84FF', INACTIVE:'#6043B6',
                              NEW:'#EB4FA0', LOST:'#8A92A6', SUCCESS:'#008B5A', SOLD:'#008B5A' };
                    return m[s] || '#6B7280';
                }
                function interestBadge(s){
                    if(!s) return '';
                    var c = interestColor(s);
                    return '<span class="ld-interest-badge" style="background:'+c+'33;color:'+c+';">'+esc(s)+'</span>';
                }

                /* ค่าที่จะโชว์บน badge ของการ์ด/แถว:
                   - leadStatus ไม่ใช่ ACTIVE → โชว์ leadStatus ตรงๆ (NEW/INACTIVE/LOST/SUCCESS ตามสีของมัน)
                   - leadStatus = ACTIVE → โชว์ activeStatus แทน (HOT/WARM/COLD)
                   - ไม่มี leadStatus → fallback activeStatus (พฤติกรรมเดิม) */
                function leadInterestValue(l){
                    var ls = (l.leadStatus || '').trim().toUpperCase();   /* ไม่สนตัวเล็ก/ใหญ่ + ตัดช่องว่าง */
                    if(!ls) return (l.activeStatus || '').trim().toUpperCase();
                    return (ls === 'ACTIVE') ? (l.activeStatus || '').trim().toUpperCase() : ls;
                }

                /* ── STATS ── */
                function renderStats(s){
                    if(!s){ if(g('ldStatsRow')) g('ldStatsRow').innerHTML = ''; return; }   /* ไม่มีค่า server → เคลียร์ ไม่โชว์ mock */
                    /* รองรับ API statusSummary (active = object {total,hot,warm,cold}) — flat keys ไว้รองรับ mock เดิมเฉยๆ */
                    var act = s.active, isObj = act && typeof act === 'object';
                    var activeTotal = isObj ? (act.total||0) : (act||0);
                    var hot  = isObj ? (act.hot ||0) : (s.active_high  ||0);  /* HOT  → แดง */
                    var warm = isObj ? (act.warm||0) : (s.active_medium||0);  /* WARM → ส้ม */
                    var cold = isObj ? (act.cold||0) : (s.active_low   ||0);  /* COLD → น้ำเงิน */
                    var items=[{l:'Total',v:s.total||0},{l:'New',v:s.new||0},{l:'Success',v:s.success||0},
                               {l:'Lost',v:s.lost||0},{l:'Inactive',v:s.inactive||0},
                               {l:'Active',v:activeTotal,dots:[{c:'#EF4444',v:hot},{c:'#F59E0B',v:warm},{c:'#3B82F6',v:cold}]}];
                    g('ldStatsRow').innerHTML = items.map(function(it){
                        if(it.dots){
                            var dot='<div class="ld-active-dots">'+it.dots.map(function(d){
                                return '<span><span class="ld-dot" style="background:'+d.c+'"></span>'+d.v+'</span>';
                            }).join('')+'</div>';
                            return '<div class="ld-stat-item" style="display:flex;align-items:center;justify-content:space-between;gap:8px;">'
                                +'<div><div class="ld-stat-lbl">'+esc(it.l)+'</div><div class="ld-stat-val">'+it.v+'</div></div>'
                                +dot+'</div>';
                        }
                        return '<div class="ld-stat-item"><div class="ld-stat-lbl">'+esc(it.l)+'</div><div class="ld-stat-val">'+it.v+'</div></div>';
                    }).join('');
                }

                /* ── BOARD ── */
                /* คอลัมน์ default = workflow step (ใช้กับผลิตภัณฑ์ A/B/C) */
                var DEFAULT_COLS = [
                    { key:'SUCCESS', label:'ปิดการขายสำเร็จ',       color:'#00C08B' },
                    { key:'FOLLOW1', label:'ติดตามลูกค้าครั้งที่ 1', color:'#6366F1' },
                    { key:'FOLLOW2', label:'ติดตามลูกค้าครั้งที่ 2', color:'#F59E0B' },
                    { key:'FOLLOW3', label:'ติดตามลูกค้าครั้งที่ 3', color:'#3B82F6' },
                    { key:'FOLLOW4', label:'ติดตามลูกค้าครั้งที่ 4', color:'#8B5CF6' },
                    { key:'LOST',    label:'ปิดการขายไม่สำเร็จ',      color:'#EF4444' }
                ];
                function renderBoard(leads, columns){
                    var defs = (columns && columns.length) ? columns : DEFAULT_COLS;
                    var cols = defs.map(function(c){ return { key:c.key, label:c.label, color:c.color, items:[] }; });
                    leads.forEach(function(l){
                        var col = cols.find(function(c){ return c.key === l.status; });
                        /* leads without matching status → skip (don't dump into first col) */
                        if(col) col.items.push(l);
                    });
                    g('ldBoardContent').innerHTML = cols.map(function(col){
                        var total = col.items.reduce(function(a,b){ return a + b.amount; }, 0);
                        var cards = col.items.map(function(l){
                            var av = isLinkUrl(l.customer_avatar)
                                ? '<div class="ld-card-av"><img src="'+esc(proxyImg(l.customer_avatar))+'" onerror="this.onerror=null;this.src=\'assets/images/default_avatar.svg\';"/></div>'
                                : '<div class="ld-card-av"><img src="assets/images/default_avatar.svg" style="width:100%;height:100%;object-fit:cover;border-radius:50%;" alt=""/></div>';
                            var teamAvs = (l.team_avatars||[]).slice(0,2).map(function(a){
                                return '<div class="ld-team-av">'+(isLinkUrl(a) ? '<img src="'+esc(proxyImg(a))+'" onerror="this.onerror=null;this.src=\'assets/images/default_avatar.svg\';"/>' : '<img src="assets/images/default_avatar.svg" style="width:100%;height:100%;object-fit:cover;border-radius:50%;" alt=""/>')+'</div>';
                            }).join('');
                            var extra = (l.team_avatars||[]).length > 2
                                ? '<div class="ld-team-av ld-team-more">+'+(l.team_avatars.length-2)+'</div>' : '';
                            return '<div class="ld-card ld-card-collapsed" draggable="'+(ldCanMoveLead(l.employeeId)?'true':'false')+'" data-id="'+l.id+'" style="cursor:pointer;" onclick="window.ldSelectLead(\''+String(l.id).replace(/'/g,'')+'\')">'
                                +'<div class="ld-card-head">'+av
                                +'<div class="ld-card-info"><div class="ld-card-name">'+esc(l.customer_name)+'</div>'
                                +'<div class="ld-card-amount">'+fmt(l.amount)+' THB</div></div>'
                                +'<span class="ld-card-expand" onclick="window.ldCardToggle(this,event)">ขยาย <i class="fas fa-chevron-down"></i></span></div>'
                                +'<div class="ld-card-owner-row">'
                                +'<span class="ld-card-owner"><span class="ld-card-owner-ic"></span>'+esc(l.owner_name||l.owner_code||'-')+'</span>'
                                +'<div class="ld-card-team-avs">'+teamAvs+extra+'</div></div>'
                                +'<div class="ld-card-body">'
                                +'<div class="ld-card-note"><span class="ld-mic" style="-webkit-mask-image:url(assets/images/icon/fi_align-left.svg);mask-image:url(assets/images/icon/fi_align-left.svg);"></span><span>'+esc(l.note)+'</span></div>'
                                +'<div class="ld-card-meta">'
                                +'<div class="ld-card-meta-item"><span class="ld-mic" style="-webkit-mask-image:url(assets/images/icon/fi_tag.svg);mask-image:url(assets/images/icon/fi_tag.svg);"></span>'+esc(l.tag)+'</div>'
                                +'<div class="ld-card-meta-item"><span class="ld-mic" style="-webkit-mask-image:url(assets/images/icon/fi_users.svg);mask-image:url(assets/images/icon/fi_users.svg);"></span>'+esc(l.team)+'</div>'
                                +'<div class="ld-card-meta-item"><span class="ld-mic" style="-webkit-mask-image:url(assets/images/icon/fi_phone-call.svg);mask-image:url(assets/images/icon/fi_phone-call.svg);"></span>'+esc(l.phone)+'</div>'
                                +'<div class="ld-card-meta-item"><span class="ld-mic" style="-webkit-mask-image:url(assets/images/icon/fi_clock.svg);mask-image:url(assets/images/icon/fi_clock.svg);"></span>บันทึกล่าสุด '+esc(l.updated)+'</div>'
                                +'</div>'
                                +'</div>'
                                +((l.interest || (l.tags && l.tags.length))
                                    ? '<div class="ld-card-tags">'
                                        +interestBadge(l.interest)
                                        +((l.tags && l.tags.length) ? l.tags.map(tagPillHtml).join('') : '')
                                      +'</div>'
                                    : '')
                                +'</div>';
                        }).join('');
                        return '<div class="ld-col">'
                            +'<div class="ld-col-head">'
                            +'<div class="ld-col-title">'+esc(col.label)+'<span class="ld-col-count" style="background:transparent;color:#7C848D;">'+col.items.length+'</span></div>'
                            +'<div class="ld-col-amount">'+fmt(total)+' THB</div></div>'
                            +'<div class="ld-col-body" data-status="'+col.key+'">'+cards+'</div></div>';
                    }).join('');
                    initBoardDnD();
                }

                /* field ว่าง → ใส่ค่า hardcode ไปก่อน (placeholder content ระหว่าง dev, เฉพาะการ์ด ไม่ดึง mock) */
                function or(v, hc){ return (v == null || v === '') ? hc : v; }

                /* ทีมขาย = saleGroupName + " (" + salePersonName + ")" — ตรง concept เดียวกับ ld.team ใน
                   lead_detail.xhtml (applyApiLead: ทีมขาย = saleGroup.name + " (" + salePerson.name + ")")
                   ใช้ทั้ง board card และ list ให้ตรงกัน */
                function saleTeamLabel(l){
                    var grp = l.saleGroupName || '', per = l.salePersonName || '';
                    if (grp && per) return grp + ' (' + per + ')';
                    return grp || per || '';
                }

                /* ★ 15/09/2026 เบอร์โทร (การ์ด board + คอลัมน์ list) = "+66 81-234-5678" — logic กลางอยู่ที่
                   resources/js/phone_format.js (TsPhone) ใช้ร่วมกับ lead_detail / contracts_master_data ห้าม copy มาเขียนซ้ำ
                   item ของ /board/leads ส่ง phoneCountryCode มาจริง (ยืนยันกับ response 15/09 — null ได้) แต่ยังไม่มี
                   countryCode → ไม่มีรหัสโทรก็ตกไป +66 (THA) ; ถ้า backend ส่ง countryCode มาภายหลังจะใช้ต่อได้เอง
                   master ยังไม่มาตอน render → เลขดิบไปก่อน แล้ว TsPhone.refresh() อัปเดตทุก .ts-tel เองเมื่อโหลดเสร็จ */
                function ldLeadNoHtml(l, curAgid){
                    var no = or(l.txNo,'-');
                    if(!CAN_VIEW_LEAD_DETAIL) return esc(no);
                    return '<a class="ld-code-link" href="javascript:void(0)" onclick="event.stopPropagation();window.ldSelectLead(\''+String(l.id).replace(/'/g,'')+'\','+curAgid+')">'+esc(no)+'</a>';
                }
                function ldPhoneHtml(l){
                    if (!window.TsPhone) return esc(or(l.prospectTel,'-'));   /* ไฟล์กลางโหลดไม่ขึ้น → อย่าให้ทั้ง board พัง */
                    if (l.prospectTel && !/\d/.test(l.prospectTel)) return esc(l.prospectTel);
                    return TsPhone.html(l.prospectTel, l.phoneCountryCode, l.countryCode);
                }
                if (window.TsPhone) TsPhone.load();

                /* (เอา mock ออก 23/07: HC_AVATARS/HC_ASSIGNEES ทีม+รูป demo — ใช้ข้อมูลจริง/default_avatar แทน) */

                /* map เก็บผู้มีสิทธิ์เข้าถึงของแต่ละ lead (keyed by lead id) — popup hover อ่านต่อจากตรงนี้ */
                window.LD_ASSIGNEES_MAP = {};
                /* หัว popup "ผู้มีสิทธิ์เข้าถึง" — components/access_pop.xhtml (ใช้ร่วมกับ lead_detail.xhtml)
                   อ่านค่านี้ตอน show แทนที่จะ hardcode key ไว้ในไฟล์ตัวเอง (คนละ key กับ lead_detail แต่
                   ข้อความไทยเหมือนกัน) */
                window.LD_ACCESS_TITLE = '' + env.t("label.lead.access_title") + '';

                /* accessors ดิบจากการ์ด API → โครงเดียวกับ LD2_ASSIGNEES ของ lead_detail (code/name/id/type/avatar)
                   คู่แฝดของ ldMapAccessors() ใน lead_detail.xhtml — ต้องแก้พร้อมกันถ้า shape เปลี่ยน
                   ★ key รูปของ accessor ทั้งระบบคือ `attachFile` ไม่ใช่ `avatar` (ดู ldMapAccessors) โค้ดเดิมตรงนี้
                     อ่าน l.assignees/a.avatar ซึ่งไม่ตรงกับที่ backend ส่งมา แถว avatar เลยว่างเปล่าตลอด
                   รับทั้ง accessors/assignees + attachFile/avatar ไว้ เผื่อ list API ใช้ชื่อ key คนละตัวกับ /leads/{id}
                   ไม่ใช่ url จริง (id/ชื่อไฟล์เปล่าๆ) → '' ให้ผู้ render ตกไป default_avatar.svg เหมือน lead_detail */
                function ldMapCardAccessors(list){
                    return (list || []).map(function(a){
                        return {
                            code: a.code || '',
                            name: a.name || '',
                            id: a.id,
                            type: a.type || '',
                            avatar: isLinkUrl(a.attachFile) ? a.attachFile : (isLinkUrl(a.avatar) ? a.avatar : '')
                        };
                    });
                }

                /* ★ 20/10/2026 — กลุ่มขั้นตอน "ของ lead ใบนั้นเอง" จาก item ของ /leads (ทั้ง viewMode=list และ kanban items
                   ส่ง activityGroupId มาทุกตัว — ยืนยันจาก API log) ; ไม่มี → procedureGroupId ; 0 = ทุกกลุ่ม ไม่ใช่ id จริง → '' */
                function ldItemGroupId(l){
                    var v = l ? (l.activityGroupId != null ? l.activityGroupId : l.procedureGroupId) : null;
                    return ldPickGroupId(v);
                }
                /* คืน id กลุ่มตัวแรกที่มีค่าจริง (ข้ามค่าว่าง / null / '0') เป็น string ; ไม่มีเลย → '' */
                function ldPickGroupId(){
                    for(var i = 0; i < arguments.length; i++){
                        var v = arguments[i] == null ? '' : String(arguments[i]).trim();
                        if(v && v !== '0') return v;
                    }
                    return '';
                }

                /* การ์ด 1 ใบจาก kanban[].items[] (map field API → โครงการ์ดเดิม) */
                function apiCardHtml(l){
                    var av = isLinkUrl(l.prospectAvatar)
                        ? '<div class="ld-card-av"><img src="'+esc(proxyImg(l.prospectAvatar))+'" onerror="this.onerror=null;this.src=\'assets/images/default_avatar.svg\';"/></div>'
                        : '<div class="ld-card-av"><img src="assets/images/default_avatar.svg" style="width:100%;height:100%;object-fit:cover;border-radius:50%;" alt=""/></div>';
                    /* ผู้มีสิทธิ์เข้าถึงจริงจาก API (ว่าง = ยังไม่มี ไม่โชว์ทีมปลอม) */
                    var assignees = ldMapCardAccessors(l.accessors || l.assignees);
                    window.LD_ASSIGNEES_MAP[l.id] = assignees;
                    var SHOW = 3;
                    var teamAvs = assignees.slice(0,SHOW).map(function(a){
                        return '<div class="ld-team-av">'+(a.avatar ? '<img src="'+esc(proxyImg(a.avatar))+'" onerror="this.onerror=null;this.src=\'assets/images/default_avatar.svg\';"/>' : '<img src="assets/images/default_avatar.svg" style="width:100%;height:100%;object-fit:cover;border-radius:50%;" alt=""/>')+'</div>';
                    }).join('');
                    var extra = assignees.length > SHOW
                        ? '<div class="ld-team-av ld-team-more">'+(assignees.length-SHOW)+'+</div>' : '';
                    /* ไม่มีผู้มีสิทธิ์เข้าถึงเลย → ไม่ต้องวาง wrap เปล่าไว้ให้ hover แล้วเจอ popup "(0)" ลิสต์ว่าง
                       ตัวแถวอยู่ใน .ld-card-owner-row ที่เป็น justify-content:space-between อยู่แล้ว → ชิดขวาสุดเอง */
                    var accessAvs = assignees.length
                        ? '<div class="ld-team-avs-wrap" style="display:inline-flex;cursor:pointer;" onmouseenter="event.stopPropagation();window.ldShowAccessPop(this,(window.LD_ASSIGNEES_MAP&&window.LD_ASSIGNEES_MAP[\''+String(l.id).replace(/'/g,'')+'\'])||[],LEAD_MY_EMPLOYEE_ID)" onmouseleave="window.ldStartCloseAccessPop()">'
                            +'<div class="ld-card-team-avs">'+teamAvs+extra+'</div></div>'
                        : '';
                    var interest = leadInterestValue(l);   /* leadStatus ไม่ใช่ ACTIVE → ใช้เลย ; ACTIVE → ใช้ activeStatus */
                    var amount = fmt(l.amount || 0);   /* null → 0 เสมอ */
                    var updated = (l.lastUpdatedAt || '').split(' ')[0];   /* เอาเฉพาะวันที่ */
                    /* ★ 28/09: ผู้รับผิดชอบ = employeeName อย่างเดียว ไม่โชว์รหัสนำหน้า (concept เดียวกับ dropdown
                       ผู้รับผิดชอบใน modal สร้าง Lead — nameOnly) ; ไม่มีชื่อ → ใช้รหัสแทน, ไม่มีทั้งคู่ = "-" */
                    var owner = esc(l.employeeName || l.employeeCode || '') || '-';
                    /* leadStatus = SUCCESS/LOST → ปิดการขายแล้ว ลากย้ายคอลัมน์ไม่ได้ / ไม่มี role CRM_Lead_Edit → ลากไม่ได้เช่นกัน */
                    var ls = (l.leadStatus || '').trim().toUpperCase();
                    var canMove = (ls !== 'SUCCESS' && ls !== 'LOST') && ldCanMoveLead(l.employeeId);
                    /* group ที่บอร์ดกำลังแสดงอยู่ ณ ตอนคลิก — ห่อ single-quote เอง (ไม่ใช้ JSON.stringify เพราะ
                       ได้ผลลัพธ์เป็น double-quote ซึ่งชนกับ onclick="..." ที่เป็น double-quote HTML attribute อยู่แล้ว
                       ทำให้ attribute ขาดกลางคัน) — ค่าเป็น id ตัวเลขจาก server เสมอ ไม่มี ' ปนอยู่ แต่กัน escape ไว้เผื่อ
                       ★ 20/10/2026 — group ของบอร์ดว่าง/เป็น 0 → fallback ไป activityGroupId ของการ์ดใบนั้นเอง (ldItemGroupId) */
                    var curAgid = "'" + ldPickGroupId(CUR_AGID, CUR_AGID_EFF, ldItemGroupId(l)).replace(/'/g, "\\'") + "'";
                    return '<div class="ld-card ld-card-collapsed" draggable="'+(canMove?'true':'false')+'" data-id="'+l.id+'" style="cursor:pointer;" onclick="window.ldSelectLead(\''+String(l.id).replace(/'/g,'')+'\','+curAgid+')">'
                        +'<div class="ld-card-head">'+av
                        +'<div class="ld-card-info"><div class="ld-card-name">'+esc(or(l.prospectName,'-'))+'</div>'
                        +'<div class="ld-card-pcode">'+esc(or(l.prospectCode,'-'))+'</div>'
                        +'<div class="ld-card-amount">'+amount+' THB</div></div>'
                        +'<span class="ld-card-expand" onclick="window.ldCardToggle(this,event)">' + env.t("label.lead.expand") + ' <i class="fas fa-chevron-down"></i></span></div>'
                        +'<div class="ld-card-owner-row">'
                        +'<span class="ld-card-owner"><span class="ld-card-owner-ic"></span>'+owner+'</span>'
                        +accessAvs+'</div>'
                        +'<div class="ld-card-body">'
                        +'<div class="ld-card-note"><span class="ld-mic" style="-webkit-mask-image:url(assets/images/icon/fi_location2.svg);mask-image:url(assets/images/icon/fi_location2.svg);"></span><span>'+esc(ldAddrDisplay(l))+'</span></div>'
                        +'<div class="ld-card-note"><span class="ld-mic" style="-webkit-mask-image:url(assets/images/icon/fi_align-left.svg);mask-image:url(assets/images/icon/fi_align-left.svg);"></span><span>'+esc(or(l.leadDemand,'-'))+'</span></div>'
                        +'<div class="ld-card-meta">'
                        +'<div class="ld-card-meta-item"><span class="ld-mic" style="-webkit-mask-image:url(assets/images/icon/fi_tag.svg);mask-image:url(assets/images/icon/fi_tag.svg);"></span>'+esc(or(l.txNo,'-'))+'</div>'
                        +'<div class="ld-card-meta-item"><span class="ld-mic" style="-webkit-mask-image:url(assets/images/icon/fi_users.svg);mask-image:url(assets/images/icon/fi_users.svg);"></span>'+esc(or(saleTeamLabel(l),'-'))+'</div>'
                        +'<div class="ld-card-meta-item"><span class="ld-mic" style="-webkit-mask-image:url(assets/images/icon/fi_phone-call.svg);mask-image:url(assets/images/icon/fi_phone-call.svg);"></span>'+ldPhoneHtml(l)+'</div>'
                        +'<div class="ld-card-meta-item"><span class="ld-mic" style="-webkit-mask-image:url(assets/images/icon/fi_clock.svg);mask-image:url(assets/images/icon/fi_clock.svg);"></span>' + env.t("label.lead.last_saved_prefix") + ' '+esc(or(updated,'-'))+'</div>'
                        +'</div>'
                        +'</div>'
                        +((interest || (l.tags && l.tags.length))
                            ? '<div class="ld-card-tags">'+interestBadge(interest)
                                +((l.tags && l.tags.length) ? l.tags.map(tagPillHtml).join('') : '')
                              +'</div>'
                            : '')
                        +'</div>';
                }

                /* ขยาย/ย่อการ์ด — กันคลิกทะลุไปเปิด lead detail */
                window.ldCardToggle = function(el, e){
                    if(e){ e.stopPropagation(); e.preventDefault(); }
                    var card = el.closest('.ld-card');
                    if(!card) return;
                    var collapsed = card.classList.toggle('ld-card-collapsed');
                    el.innerHTML = collapsed
                        ? '' + env.t("label.lead.expand") + ' <i class="fas fa-chevron-down"></i>'
                        : '' + env.t("label.lead.collapse") + ' <i class="fas fa-chevron-up"></i>';
                };

                /* ── BOARD จาก API kanban ──
                   จำนวน column = kanban.length, title = stepName, count = items.length, การ์ด = items[] */
                function renderBoardFromKanban(kanban){
                    if(!Array.isArray(kanban)){ return; }
                    /* กัน field name ไม่ตรง (API อาจส่ง id/procedureId/activityStepId แทน stepId) — normalize เข้า col.stepId
                       เดียว ให้ DnD (data-step / fromCol.stepId / toCol lookup) ใช้ค่าเดียวกันทั้งหมด ไม่งั้นลากการ์ดจะไม่ขยับเลย
                       เพราะ toCol หาไม่เจอ (moveLeadKanban คืนเงียบๆ ที่ if(!toCol) return;) */
                    kanban.forEach(function(col){
                        var sid = (col.stepId != null ? col.stepId
                                 : col.id != null ? col.id
                                 : col.procedureId != null ? col.procedureId
                                 : col.activityStepId != null ? col.activityStepId : null);
                        if(sid == null) console.warn('[lead] kanban column ไม่มี step id field ที่รู้จัก (stepId/id/procedureId/activityStepId):', col);
                        col.stepId = sid;
                    });
                    SERVER_KANBAN = kanban;   /* เก็บไว้ให้ DnD ย้ายการ์ด */
                    /* ไม่มีคอลัมน์เลย (ไม่ใช่แค่การ์ดว่าง) → แสดงข้อความกลางบอร์ด (ไม่ใช้ mock)
                       มีคอลัมน์แต่การ์ดว่าง → ยังต้องโชว์คอลัมน์ตามปกติ (ให้เห็นชื่อขั้นตอนทั้งหมด แม้ยังไม่มีลูกค้า) */
                    if(!kanban.length){
                        g('ldBoardContent').innerHTML =
                            '<div class="ld-board-empty">'
                            +'<i class="far fa-folder-open"></i>'
                            +'<div class="ld-be-title">' + env.t("label.lead.empty_title") + '</div>'
                            +'<div class="ld-be-sub">' + env.t("label.lead.empty_desc") + '</div>'
                            +'</div>';
                        return;
                    }
                    g('ldBoardContent').innerHTML = kanban.map(function(col){
                        var items = col.items || [];
                        var total = ldColTotal(col, items);   /* รวม amount ของทุก item ในคอลัมน์ */
                        var cards = items.map(apiCardHtml).join('');
                        var m = col.meta || {};   /* paging ต่อคอลัมน์: {page,perPage,total,totalPages} */
                        var cpage = m.page || 1, ctp = m.totalPages || 1;
                        var cpp = m.perPage || CUR_PERPAGE, ctot = (m.total != null ? m.total : items.length);
                        return '<div class="ld-col">'
                            +'<div class="ld-col-head">'
                            +'<div class="ld-col-title">'+esc(col.stepName)
                              +'<span class="ld-col-count" style="background:transparent;color:#7C848D;">'+ctot+'</span></div>'
                            +'<div class="ld-col-amount">'+fmt(total)+' THB</div></div>'
                            +'<div class="ld-col-body" data-step="'+esc(col.stepId != null ? col.stepId : '')+'"'
                              +' data-page="'+cpage+'" data-total-pages="'+ctp+'" data-perpage="'+cpp+'" data-total="'+ctot+'" data-loading="0">'+cards+'</div></div>';
                    }).join('');
                    initBoardDnD();   /* ผูก drag & drop ใหม่ทุกครั้งที่ re-render */
                }

                /* refresh บอร์ดในที่ (ไม่ reload หน้า, ไม่โชว์ skeleton/ว่างระหว่างรอ) — เรียกจาก onSuccess ของ
                   move_step_modal ตอนบันทึกย้ายขั้นตอนสำเร็จ: การ์ดที่ลากไปคอลัมน์ใหม่ (optimistic update ตอน drop)
                   ยังค้างโชว์อยู่ตามเดิมบนจอ ระหว่างที่ loadLeads() ยิง API เบื้องหลัง พอ API ตอบกลับ applyServerResult
                   จะ re-render ทับด้วยข้อมูลจริงเอง (เนียน ไม่มีช่วงว่าง/skeleton คั่น) */
                function refreshBoardAfterMove(){
                    loadLeads(true);   /* quiet — ไม่โชว์ skeleton ตามเจตนาเดิม (การ์ดที่ลากไปแล้วต้องค้างอยู่บนจอ) */
                }

                /* ย้ายการ์ดข้ามคอลัมน์บน kanban (API) — ลบจากคอลัมน์เดิม ใส่คอลัมน์ใหม่ แล้ว re-render */
                function moveLeadKanban(id, stepId){
                    if(!Array.isArray(SERVER_KANBAN)) return;
                    var fromCol = null, idx = -1;
                    for(var i=0;i<SERVER_KANBAN.length;i++){
                        var items = SERVER_KANBAN[i].items || [];
                        for(var j=0;j<items.length;j++){
                            if(String(items[j].id) === String(id)){ fromCol = SERVER_KANBAN[i]; idx = j; break; }
                        }
                        if(fromCol) break;
                    }
                    if(!fromCol) return;
                    /* ★ 26/08: เช็ค "เป็นเจ้าของ lead ใบนี้ไหม" ต่อการ์ด (ต่างจาก lead_detail.xhtml ที่มี lead
                       เดียว) — ต้องเช็คหลังหา item เจอแล้ว (ต้องรู้ employeeId ของ lead ใบนี้ก่อน) แต่ต้องเช็ค
                       ก่อน splice/mutate SERVER_KANBAN ด้านล่าง ไม่งั้นจะแก้ state ไปแล้วถึงจะรู้ว่าไม่มีสิทธิ์ */
                    if(!ldCanMoveLead(items[idx].employeeId)) return;   /* ไม่มีสิทธิ์ย้าย lead ใบนี้ → block */
                    if(String(fromCol.stepId) === String(stepId)) return;   /* คอลัมน์เดิม ไม่ต้องทำอะไร */
                    var toCol = null;
                    for(var k=0;k<SERVER_KANBAN.length;k++){
                        if(String(SERVER_KANBAN[k].stepId) === String(stepId)){ toCol = SERVER_KANBAN[k]; break; }
                    }
                    if(!toCol) return;
                    var item = fromCol.items.splice(idx, 1)[0];
                    (toCol.items = toCol.items || []).push(item);
                    renderBoardFromKanban(SERVER_KANBAN);
                    /* ยกเลิก modal → เอา item ออกจาก toCol แล้วใส่กลับ fromCol ตำแหน่งเดิม */
                    var revert = function(){
                        var ti = toCol.items.indexOf(item);
                        if (ti >= 0) toCol.items.splice(ti, 1);
                        fromCol.items.splice(idx, 0, item);
                        renderBoardFromKanban(SERVER_KANBAN);
                    };
                    /* ย้ายไป column ใหม่ → เด้ง modal ย้ายขั้นตอน (badge = group ปัจจุบัน + step ปลายทาง)
                       ปุ่มบันทึกใน modal เป็นคนยิง API (POST ../board/contact-activities + procedureId = step ใหม่) */
                    var grp = ldCurGroupInfo();
                    if (window.ldOpenMoveStep) window.ldOpenMoveStep({
                        leadId: id,
                        procedureId: stepId,
                        procedureGroupId: grp.id || null,   /* กลุ่มขั้นตอนปัจจุบันที่เลือกอยู่บนบอร์ด — ไม่มี (no-WF) → null = ไม่ส่ง field นี้ */
                        group: grp.name,
                        step: toCol.stepName || '',
                        color: grp.color,
                        isMoveGroupStep: false,   /* หน้า lead ย้ายเฉพาะ step → ซ่อน badge กลุ่มเสมอ */
                        onCancel: revert,
                        onSuccess: refreshBoardAfterMove,  /* บันทึกสำเร็จ → ไม่ reload หน้า, refresh บอร์ดในที่แทน (skeleton ระหว่างรอ) */
                        gateKey: 'CAN_CONTACT_ACTIVITY_CREATE'      /* กันซ้ำ — ไม่มีสิทธิ์ → disable tabs/textarea/save ใน modal ด้วย */
                    });
                }

                /* กลุ่มขั้นตอนที่เลือกอยู่บนบอร์ด (ชื่อ + สี hex จาก STEPPER_PALETTE + id ตัวเลข) — ใช้เป็น badge + procedureGroupId ใน modal ย้ายขั้นตอน
                   id มาจาก data-id ที่ applyWfStepDropdown()/buildGroupDd() ใส่ไว้ตอน build item ทุกตัวอยู่แล้ว (ตัวเดียวกับที่ reloadLeadsByActivityGroup ใช้) */
                function ldCurGroupInfo(){
                    var wrap = g('ldGroupWrap');
                    if(wrap && wrap.style.display === 'none') return { name:'', color:'', id:'' };   /* ไม่ใช้ workflow step → ไม่มี group badge/id */
                    var sel = document.querySelector('#ldGroupDd .ld-dd-item.selected');
                    if(sel) return { name: sel.getAttribute('data-val') || '', color: sel.getAttribute('data-color') || '', id: sel.getAttribute('data-id') || '' };
                    var lbl = g('ldGroupLabel');
                    return { name: lbl ? lbl.textContent.trim() : '', color: '', id: '' };
                }

                /* ── DRAG & DROP: ลากการ์ดย้ายคอลัมน์ (เปลี่ยนสถานะ lead) ── */
                function moveLead(id, status){
                    var p = productBlock(DATA, CUR_PRODUCT);
                    var leads = (p && p.leads) || [];
                    var moved = null, oldStatus = null;
                    for(var i=0;i<leads.length;i++){
                        if(leads[i].id === id){
                            /* ★ 26/08: เช็คสิทธิ์ต่อการ์ด (owner-check) ก่อน mutate status — เหมือน moveLeadKanban */
                            if(!ldCanMoveLead(leads[i].employeeId)) return;
                            if(leads[i].status === status) return; /* คอลัมน์เดิม ไม่ต้องทำอะไร */
                            moved = leads[i]; oldStatus = leads[i].status;
                            leads[i].status = status;
                            break;
                        }
                    }
                    if(!moved) return;
                    renderBoard(leads, p.columns);
                    renderList(leads);
                    /* ยกเลิก modal → คืน status เดิม */
                    var revert = function(){
                        moved.status = oldStatus;
                        renderBoard(leads, p.columns);
                        renderList(leads);
                    };
                    /* ย้ายไป column ใหม่ → เด้ง modal ย้ายขั้นตอน (mock ไม่มี stepId → procedureId=null, badge step = ชื่อคอลัมน์ปลายทาง) */
                    var defs = (p.columns && p.columns.length) ? p.columns : DEFAULT_COLS;
                    var destCol = null;
                    for(var d=0;d<defs.length;d++){ if(defs[d].key === status){ destCol = defs[d]; break; } }
                    if (window.ldOpenMoveStep) window.ldOpenMoveStep({
                        leadId: id,
                        procedureId: null,
                        group: '',
                        step: destCol ? destCol.label : '',
                        color: '',
                        isMoveGroupStep: false,
                        onCancel: revert,
                        gateKey: 'CAN_CONTACT_ACTIVITY_CREATE'
                    });
                }
                var BOARD_DRAG_ID = null;

                /* auto-scroll ซ้าย/ขวา ตอนลากการ์ดเข้าใกล้ขอบบอร์ด — คอลัมน์เยอะจน scroll ยาว
                   กันต้องขยับ-ปล่อย-ลากใหม่หลายรอบกว่าจะถึงคอลัมน์ปลายทาง */
                var BOARD_AS_DIR = 0, BOARD_AS_TIMER = null;
                __cleanups.push(function(){ if(BOARD_AS_TIMER){ clearInterval(BOARD_AS_TIMER); BOARD_AS_TIMER = null; } });
                function boardAutoScrollStart(board){
                    if(BOARD_AS_TIMER) return;
                    BOARD_AS_TIMER = setInterval(function(){
                        if(BOARD_AS_DIR) board.scrollLeft += BOARD_AS_DIR * 16;
                    }, 16);
                }
                function boardAutoScrollStop(){
                    if(BOARD_AS_TIMER){ clearInterval(BOARD_AS_TIMER); BOARD_AS_TIMER = null; }
                    BOARD_AS_DIR = 0;
                }

                /* ผูก dragstart/dragend ให้การ์ด 1 ใบ — ใช้ทั้งตอน render เต็มและตอน append หน้าใหม่ */
                function bindCardDrag(card){
                    card.addEventListener('dragstart', function(e){
                        BOARD_DRAG_ID = Number(card.getAttribute('data-id'));
                        e.dataTransfer.effectAllowed = 'move';
                        try{ e.dataTransfer.setData('text/plain', String(BOARD_DRAG_ID)); }catch(_){}
                        /* ghost แบบ custom: clone การ์ดโดดๆ (ตัดเงา) → ภาพที่ลากเป็นการ์ดล้วน ไม่มีกรอบ/พื้นขาวเกินรอบการ์ด */
                        try{
                            var r = card.getBoundingClientRect();
                            var gh = card.cloneNode(true);
                            gh.style.cssText = 'position:fixed;top:-9999px;left:-9999px;width:'+r.width+'px;margin:0;box-shadow:none;pointer-events:none;';
                            document.body.appendChild(gh);
                            e.dataTransfer.setDragImage(gh, e.clientX - r.left, e.clientY - r.top);
                            tmo(function(){ if(gh.parentNode) gh.parentNode.removeChild(gh); }, 0);
                        }catch(_){}
                        /* ใส่ class หลัง browser จับภาพ ghost แล้ว → highlight เฉพาะการ์ดที่ค้างในคอลัมน์ต้นทาง */
                        tmo(function(){ card.classList.add('ld-dragging'); }, 0);
                    });
                    card.addEventListener('dragend', function(){ card.classList.remove('ld-dragging'); boardAutoScrollStop(); });
                }
                function initBoardDnD(){
                    var board = g('ldBoardContent');
                    if(!board) return;
                    board.querySelectorAll('.ld-card').forEach(bindCardDrag);
                    board.addEventListener('dragover', function(e){
                        var rect = board.getBoundingClientRect();
                        var edge = 70;
                        if(e.clientX - rect.left < edge) BOARD_AS_DIR = -1;
                        else if(rect.right - e.clientX < edge) BOARD_AS_DIR = 1;
                        else BOARD_AS_DIR = 0;
                        boardAutoScrollStart(board);
                    });
                    board.addEventListener('dragleave', function(e){
                        if(e.target === board) BOARD_AS_DIR = 0;
                    });
                    board.addEventListener('drop', boardAutoScrollStop);
                    board.querySelectorAll('.ld-col-body').forEach(function(body){
                        body.addEventListener('dragover', function(e){
                            e.preventDefault(); e.dataTransfer.dropEffect = 'move';
                            body.classList.add('ld-col-over');
                            var col = body.parentNode;
                            if(col){
                                /* overlay เริ่มตรงขอบบนโซนการ์ดพอดี — วัดจากตำแหน่งจริงของ col-body */
                                col.style.setProperty('--ld-drop-top', body.offsetTop + 'px');
                                col.classList.add('ld-col-target');
                            }
                        });
                        body.addEventListener('dragleave', function(){
                            body.classList.remove('ld-col-over');
                            if(body.parentNode) body.parentNode.classList.remove('ld-col-target');
                        });
                        body.addEventListener('drop', function(e){
                            e.preventDefault(); body.classList.remove('ld-col-over');
                            if(body.parentNode) body.parentNode.classList.remove('ld-col-target');
                            var id = BOARD_DRAG_ID || Number(e.dataTransfer.getData('text/plain'));
                            var step = body.getAttribute('data-step');     /* board API (kanban) */
                            var status = body.getAttribute('data-status');  /* board mock เดิม */
                            if(id){
                                if(step) moveLeadKanban(id, step);
                                else if(status) moveLead(id, status);
                            }
                            BOARD_DRAG_ID = null;
                        });
                        /* infinite scroll: เลื่อนใกล้สุดคอลัมน์ → โหลดหน้าถัดไปของคอลัมน์นั้น */
                        body.addEventListener('scroll', function(){
                            if(body.scrollTop + body.clientHeight >= body.scrollHeight - 80){
                                loadMoreColumn(body);
                            }
                        });
                        maybeFillColumn(body);   /* การ์ดน้อยจน scroll ไม่ได้ แต่ยังมีหน้าเหลือ → โหลดต่อให้เต็ม */
                    });
                }
                /* ลาก scroll บอร์ดแนวนอนด้วยเมาส์ (เมาส์บางตัว scroll แนวนอนไม่ได้) — ผูกครั้งเดียวพอ
                   เพราะ #ldBoardContent ตัว element ไม่ถูกแทนที่ตอน re-render (แค่ innerHTML เปลี่ยน)
                   เริ่มลากเฉพาะตอนกดบนพื้นที่ว่าง ไม่ใช่บนการ์ด/ปุ่ม กันชนกับ drag การ์ด (native DnD) และ onclick เปิดรายละเอียด */
                function initBoardGrabScroll(){
                    var board = g('ldBoardContent');
                    if(!board) return;
                    var dragging = false, startX = 0, startScroll = 0;
                    board.addEventListener('mousedown', function(e){
                        if(e.button !== 0) return;
                        if(e.target.closest('.ld-card, button, a, input, textarea, select, [draggable="true"]')) return;
                        dragging = true;
                        startX = e.pageX; startScroll = board.scrollLeft;
                        board.classList.add('ld-board-grabbing');
                    });
                    listen(document, 'mousemove', function(e){
                        if(!dragging) return;
                        e.preventDefault();
                        board.scrollLeft = startScroll - (e.pageX - startX);
                    });
                    listen(document, 'mouseup', function(){
                        if(!dragging) return;
                        dragging = false;
                        board.classList.remove('ld-board-grabbing');
                    });
                }
                /* ลากเลื่อน tab list ด้วยเมาส์ (เหมือนบอร์ด — scrollbar ของตารางซ่อนอยู่ เมาส์บางตัวเลื่อนแนวนอนไม่ได้)
                   ต่างจากบอร์ดตรงที่ตารางไม่มีพื้นที่ว่างให้เริ่มลาก (ทั้งแถวคือปุ่ม คลิกแล้วเข้า lead_detail) จึงเริ่มลากได้ทุกจุด
                   ยกเว้น a/button/input/textarea/select แล้วแยก "คลิก" กับ "ลาก" ด้วยระยะขยับ ≥ 5px :
                   ขยับไม่ถึง = คลิกแถวตามปกติ ; ขยับเกิน = ลาก (เลื่อนทั้งแนวนอน/แนวตั้ง) แล้วกลืนคลิกที่ตามมาหลังปล่อยเมาส์
                   (ไม่งั้นลากจบแล้วเด้งเข้า lead_detail ของแถวที่ปล่อยเมาส์) — ผูกครั้งเดียว: .ld-list-wrap ไม่ถูกแทนที่ตอน re-render */
                function initListGrabScroll(){
                    var wrap = document.querySelector('#ldTabList .ld-list-wrap');
                    if(!wrap) return;
                    var LD_DRAG_THRESHOLD = 5;
                    var down = false, moved = false, suppressClick = false, sx = 0, sy = 0, sl = 0, st = 0;
                    function endDrag(){
                        if(!down) return;
                        down = false;
                        wrap.classList.remove('ld-list-grabbing');
                        if(moved){
                            suppressClick = true;   /* click ตามหลัง mouseup ทันที — เคลียร์แฟลกหลังจากนั้น */
                            tmo(function(){ suppressClick = false; }, 0);
                        }
                        moved = false;
                    }
                    wrap.addEventListener('mousedown', function(e){
                        if(e.button !== 0) return;
                        if(e.target.closest('a, button, input, textarea, select')) return;
                        down = true; moved = false;
                        sx = e.clientX; sy = e.clientY; sl = wrap.scrollLeft; st = wrap.scrollTop;
                    });
                    listen(document, 'mousemove', function(e){
                        if(!down) return;
                        if(e.buttons === 0){ endDrag(); return; }   /* ปล่อยเมาส์นอกหน้าต่าง → mouseup ไม่ถึง document */
                        var dx = e.clientX - sx, dy = e.clientY - sy;
                        if(!moved){
                            if(Math.abs(dx) < LD_DRAG_THRESHOLD && Math.abs(dy) < LD_DRAG_THRESHOLD) return;   /* ยังเป็นแค่คลิก */
                            moved = true;
                            wrap.classList.add('ld-list-grabbing');
                            var sel = window.getSelection ? window.getSelection() : null;
                            if(sel && sel.removeAllRanges) sel.removeAllRanges();   /* กันข้อความถูกไฮไลต์ตอนเริ่มลาก */
                        }
                        e.preventDefault();
                        wrap.scrollLeft = sl - dx;
                        wrap.scrollTop  = st - dy;
                    });
                    listen(document, 'mouseup', endDrag);
                    /* capture: ดักก่อน onclick ของ <tr> (inline) */
                    wrap.addEventListener('click', function(e){
                        if(suppressClick){ suppressClick = false; e.stopPropagation(); e.preventDefault(); }
                    }, true);
                }
                /* ★ 16/09/2026 (perf — ทีม backend แจ้งว่าหน้านี้ยิง /board/leads ~90 ครั้งเรียงกัน ~13 วิ
                     ตั้งแต่เปิดหน้าโดยที่ผู้ใช้ยังไม่ได้เลื่อนจอเลย)
                   ต้นเหตุ = ลูป auto-fill ด้านล่างนี้เอง: `maybeFillColumn` -> `loadMoreColumn` -> พอโหลดเสร็จ
                   เรียก `maybeFillColumn` ต่อทันที วนไปจนกว่าคอลัมน์จะ "ล้น" (มี scrollbar) หรือหมดหน้า —
                   แต่ `.ld-main-card` เป็น `min-height:990px` ไม่มีเพดานความสูง (ดู css/lead.css) การ์ดที่ต่อ
                   เข้าไปจึงดัน .ld-col-body / .ld-col / .ld-board / .ld-main-card ให้สูงขึ้นตามเนื้อหาเรื่อย ๆ
                   ⇒ `scrollHeight` กับ `clientHeight` เท่ากันตลอดกาล คอลัมน์ "ไม่มีวันล้น" ⇒ เงื่อนไขหยุดเป็นจริง
                   ไม่ได้เลย ลูปจึงไล่โหลด **ทุกหน้าของทุกคอลัมน์** ตั้งแต่เปิดหน้า (รวมกันได้เป็นสิบ ๆ เส้น)
                   แก้: ยอมให้ auto-fill ได้อย่างจำกัด และตรวจจับกล่องที่ "สูงตามเนื้อหา" แล้วหยุด —
                   ที่เหลือให้เป็นหน้าที่ของ event scroll จริงเหมือนเดิม (เคสที่ฟีเจอร์นี้ตั้งใจแก้ = การ์ดน้อย/เตี้ย
                   จน scroll ไม่ได้ ยังทำงานอยู่ เพราะ 1 หน้าที่ยอมให้เติมก็พอแล้ว) */
                var LD_AUTOFILL_MAX_PAGES = 1;   /* จำนวนหน้าที่ยอมให้โหลดเองต่อ 1 คอลัมน์/ตาราง ก่อน user เลื่อนจอ */
                /* el = กล่องที่ควรจะ scroll ได้, tried = จำนวนหน้าที่ auto-fill ไปแล้วของกล่องนี้ */
                function ldAutoFillOk(el, tried){
                    if(!el || el.clientHeight < 1) return false;            /* ยังไม่ถูก layout / ถูกซ่อนอยู่ = วัดไม่ได้ อย่าเดา */
                    if(tried >= LD_AUTOFILL_MAX_PAGES) return false;
                    if(el.scrollHeight > el.clientHeight + 4) return false; /* เลื่อนได้แล้ว → ปล่อยให้ event scroll ทำงาน */
                    if(tried >= 1) return false;                            /* เติมไปแล้วยังไม่เกิด scrollbar = กล่องสูงตามเนื้อหา ไม่มีวันล้น */
                    return true;
                }
                /* เนื้อหายังไม่ล้นคอลัมน์ (scroll ไม่ได้) แต่ยังมีหน้าถัดไป → โหลดต่อ
                   ป้องกันเคส perPage น้อย/การ์ดเตี้ย ที่ event scroll ไม่มีวันยิง */
                function maybeFillColumn(body){
                    if(!body || body.getAttribute('data-loading') === '1') return;
                    var page = parseInt(body.getAttribute('data-page')||'1', 10);
                    var tp = parseInt(body.getAttribute('data-total-pages')||'1', 10);
                    if(page >= tp){ colMoreBtn(body, false); return; }
                    var tried = parseInt(body.getAttribute('data-autofill')||'0', 10);
                    if(ldAutoFillOk(body, tried)){
                        body.setAttribute('data-autofill', String(tried + 1));
                        colMoreBtn(body, false);
                        loadMoreColumn(body);
                        return;
                    }
                    /* หยุด auto-fill แล้วแต่ยังมีหน้าเหลือ — ถ้าคอลัมน์นี้ "เลื่อนไม่ได้จริง" (สูงตามเนื้อหา)
                       event scroll จะไม่มีวันยิง ผู้ใช้จะไปต่อไม่ได้เลย → ขึ้นปุ่ม "โหลดเพิ่ม" ให้กดเอง
                       (คอลัมน์ที่เลื่อนได้ตามปกติไม่ต้องมีปุ่มนี้ — scroll handler ทำงานอยู่แล้ว) */
                    colMoreBtn(body, body.scrollHeight <= body.clientHeight + 4);
                }
                /* ปุ่ม "โหลดเพิ่ม" ท้ายคอลัมน์ — โผล่เฉพาะตอนคอลัมน์เลื่อนไม่ได้แต่ยังมีหน้าเหลือ (ดู maybeFillColumn) */
                function colMoreBtn(body, on){
                    var ex = body.querySelector('.ld-col-more');
                    if(!on){ if(ex) ex.parentNode.removeChild(ex); return; }
                    if(ex) return;
                    var b = document.createElement('button');
                    b.type = 'button';
                    b.className = 'ld-col-more';
                    b.textContent = '' + env.t("label.lead.load_more") + '';
                    b.style.cssText = 'display:block;width:100%;margin:8px 0 0;padding:8px 0;border:1px dashed #C8CEDA;'
                        + 'background:transparent;border-radius:8px;color:#5B6472;cursor:pointer;'
                        + 'font-size:calc(13px + var(--ts-fs-adj,0px));';
                    b.addEventListener('click', function(){ colMoreBtn(body, false); loadMoreColumn(body); });
                    body.appendChild(b);
                }

                /* ── INFINITE SCROLL ต่อคอลัมน์ (board API kanban) ──
                   meta ต่อคอลัมน์ = {page,perPage,total,totalPages} → เลื่อนสุด → ยิงหน้าถัดไป
                   ด้วย activityStepId = stepId ของคอลัมน์ แล้วเอา kanban[0].items มา append */
                function findKanbanCol(stepId){
                    if(!Array.isArray(SERVER_KANBAN)) return null;
                    for(var i=0;i<SERVER_KANBAN.length;i++){
                        if(String(SERVER_KANBAN[i].stepId) === String(stepId)) return SERVER_KANBAN[i];
                    }
                    return null;
                }
                /* URL โหลดหน้าถัดไปของ "คอลัมน์เดียว" — เส้น leads เดิม + activityStepId = id คอลัมน์ */
                function colLeadsUrl(stepId, page, perPage){
                    var u = '../board/leads?viewMode=board';
                    if(CUR_MID)  u += '&movementTypeId=' + encodeURIComponent(CUR_MID);
                    var agid = CUR_AGID || CUR_AGID_EFF;   /* เลือกจาก dropdown ไม่งั้นใช้ group ที่ server default มา */
                    if(agid) u += '&activityGroupId=' + encodeURIComponent(agid);
                    if(CUR_SEARCH) u += '&search=' + encodeURIComponent(CUR_SEARCH);   /* คงคำค้นตอนเลื่อนโหลดเพิ่ม */
                    u += '&showClosed=' + CUR_SHOWCLOSED;
                    u += dateRangeParams();   /* คงช่วงวันที่ตอนเลื่อนโหลดเพิ่ม */
                    u += extraFilterParams();   /* ★ 17/09/2026 — เดิมตก filter ชุดนี้ตอนเลื่อนโหลดหน้าถัดไปของคอลัมน์ */
                    if(CUR_TAGS && CUR_TAGS.length) u += '&tagIds=' + encodeURIComponent(CUR_TAGS.join(','));
                    u += '&sortBy=' + CUR_SORT;
                    u += '&activityStepId=' + encodeURIComponent(stepId);
                    u += '&page=' + page + '&perPage=' + (perPage || CUR_PERPAGE);
                    return u;
                }
                function colLoader(body, on){
                    var ex = body.querySelector('.ld-col-loader');
                    if(on){
                        if(!ex){
                            var d = document.createElement('div');
                            d.className = 'ld-col-loader';
                            d.style.cssText = 'text-align:center;padding:8px 0;font-size:calc(12px + var(--ts-fs-adj,0px));color:#7C848D;';
                            d.textContent = '' + env.t("label.lead.loading") + '';
                            body.appendChild(d);
                        }
                    } else if(ex){ ex.parentNode.removeChild(ex); }
                }
                function loadMoreColumn(body){
                    if(body.getAttribute('data-loading') === '1') return;
                    var page = parseInt(body.getAttribute('data-page')||'1', 10);
                    var totalPages = parseInt(body.getAttribute('data-total-pages')||'1', 10);
                    if(page >= totalPages) return;   /* โหลดครบทุกหน้าแล้ว → ไม่ยิง */
                    var stepId = body.getAttribute('data-step');
                    if(!stepId) return;
                    var perPage = parseInt(body.getAttribute('data-perpage')||String(CUR_PERPAGE), 10);
                    var nextPage = page + 1;
                    body.setAttribute('data-loading','1');
                    colLoader(body, true);
                    env.fetch(colLeadsUrl(stepId, nextPage, perPage), {credentials:'same-origin'})
                        .then(function(r){ return r.ok ? r.json() : null; })
                        .then(function(payload){
                            var result = (payload && payload.result && typeof payload.result==='object') ? payload.result : payload;
                            var col = (result && Array.isArray(result.kanban)) ? result.kanban[0] : null;
                            appendColumnItems(body, stepId, (col && col.items) || [], nextPage);
                        })
                        .catch(function(){})
                        .then(function(){ colLoader(body, false); body.setAttribute('data-loading','0'); maybeFillColumn(body); });
                }
                /* ต่อการ์ดหน้าใหม่เข้าคอลัมน์ + sync SERVER_KANBAN + อัปเดต count/amount */
                function appendColumnItems(body, stepId, newItems, newPage){
                    if(newItems && newItems.length){
                        var tmp = document.createElement('div');
                        tmp.innerHTML = newItems.map(apiCardHtml).join('');
                        while(tmp.firstChild){
                            var node = tmp.firstChild;
                            body.appendChild(node);
                            if(node.nodeType === 1 && node.classList && node.classList.contains('ld-card')) bindCardDrag(node);
                        }
                        var sk = findKanbanCol(stepId);
                        if(sk){
                            sk.items = (sk.items||[]).concat(newItems);
                            sk.meta = sk.meta || {};
                            sk.meta.page = newPage;     /* กัน re-render (เช่นหลัง DnD) แล้วโหลดหน้าเดิมซ้ำ */
                            updateColHeader(body, sk);
                        }
                    }
                    body.setAttribute('data-page', String(newPage));   /* ขยับ page แม้หน้าว่าง → ไม่ยิงซ้ำ */
                }
                /* อัปเดตจำนวน + ยอดรวมบนหัวคอลัมน์ตาม items ปัจจุบันใน SERVER_KANBAN */
                function updateColHeader(body, sk){
                    var colEl = body.parentNode;   /* .ld-col */
                    if(!colEl) return;
                    var items = (sk && sk.items) || [];
                    var cnt = colEl.querySelector('.ld-col-count');
                    /* ใช้ meta.total (จำนวนจริงทั้งหมดของคอลัมน์) ไม่ใช่ items.length (แค่จำนวนที่โหลดมาแล้วตอน infinite scroll) */
                    var mTotal = (sk && sk.meta && sk.meta.total != null) ? sk.meta.total : items.length;
                    if(cnt) cnt.textContent = mTotal;
                    var amt = colEl.querySelector('.ld-col-amount');
                    if(amt){
                        var total = ldColTotal(sk, items);
                        amt.textContent = fmt(total) + ' THB';
                    }
                }

                /* (เอา mock ออก 23/07: AGENT_AV รูป demo ตาม owner_code — ใช้ข้อมูลจริง/default_avatar แทน) */

                /* ── LIST จาก API (result.leads[] = items) ── render ตามลำดับที่ได้มา ── */
                /* row 1 แถวจาก item — แยกไว้ reuse ตอน append (infinite scroll) */
                function apiListRowHtml(l){
                    /* ★ 28/09: ผู้รับผิดชอบ = employeeName อย่างเดียว ไม่โชว์รหัสนำหน้า (concept เดียวกับ apiCardHtml) */
                    var owner = esc(l.employeeName || l.employeeCode || '') || '-';
                    var av = isLinkUrl(l.prospectAvatar)
                        ? '<div class="ld-cust-av"><img src="'+esc(proxyImg(l.prospectAvatar))+'" onerror="this.onerror=null;this.src=\'assets/images/default_avatar.svg\';"/></div>'
                        : '<div class="ld-cust-av"><img src="assets/images/default_avatar.svg" style="width:100%;height:100%;object-fit:cover;border-radius:50%;" alt=""/></div>';
                    var agSrc = (l.assigneeAvatars && l.assigneeAvatars[0]) || '';
                    var agAv = '<div class="ld-cust-av"><img src="'+(isLinkUrl(agSrc)?esc(proxyImg(agSrc)):'assets/images/default_avatar.svg')+'" style="width:100%;height:100%;object-fit:cover;border-radius:50%;" onerror="this.onerror=null;this.src=\'assets/images/default_avatar.svg\';"/></div>';
                    var interest = leadInterestValue(l);   /* leadStatus ไม่ใช่ ACTIVE → ใช้เลย ; ACTIVE → ใช้ activeStatus */
                    /* ★ 20/10/2026 — ใช้กลุ่มขั้นตอน "ของแถวนั้นเอง" (l.activityGroupId จาก /leads?viewMode=list) เท่านั้น
                       เดิมใช้ CUR_AGID || CUR_AGID_EFF ของ board → เข้าหน้าแล้วอยู่ tab list เลย (กลับจาก lead_detail = restore
                       tab list ไม่โหลด board) ค่าว่าง ⇒ ไม่ส่ง activityGroupId (log 20/10 11:11–11:13 /leads/{id} ไม่มีกลุ่ม)
                       และต่อให้มีค่า ก็เป็นกลุ่มที่ board กรองอยู่ ไม่ใช่กลุ่มของแถว (list = ทุกกลุ่ม activityGroupId=0)
                       ไม่มีกลุ่ม/เป็น 0 → '' ไม่แนบ ; ห่อ single-quote เอง (ดูเหตุผลเดียวกับ apiCardHtml) */
                    var curAgid = "'" + ldItemGroupId(l).replace(/'/g, "\\'") + "'";
                    return '<tr>'
                        +'<td>'+esc(or((l.lastUpdatedAt||'').split(' ')[0], '-'))+'</td>'
                        +'<td><div class="ld-lead-no">'+ldLeadNoHtml(l, curAgid)+'</div><div class="ld-contract-no">'+esc(l.movementTypeCode||'')+'</div></td>'
                        +'<td>'+esc(or(l.prospectCode,'-'))+'</td>'
                        +'<td><div class="ld-cust-wrap">'+av+'<span>'+esc(or(l.prospectName,'-'))+'</span></div></td>'
                        +'<td><div class="ld-phone"><span class="ld-phone-ic"><img src="assets/images/icon/fi_phone.svg" alt=""/></span>'+ldPhoneHtml(l)+'</div></td>'
                        +'<td>'+esc(ldAddrDisplay(l))+'</td>'
                        +'<td>'+fmt(l.amount || 0)+' THB</td>'
                        +'<td>'+esc(or(saleTeamLabel(l),'-'))+'</td>'
                        +'<td><div class="ld-cust-wrap">'+(owner==='-'?'':agAv)+'<span>'+owner+'</span></div></td>'
                        +'<td class="ld-col-wf">'+esc(ldListStepGroup(l))+'</td>'
                        +'<td>'+esc(ldListStep(l))+'</td>'
                        +'<td>'+interestBadge(interest)+'</td>'
                        +'<td>'+listTagsHtml(l.tags)+'</td>'
                        +'</tr>';
                }
                /* ที่อยู่แบบย่อของ lead — ตปท. ขึ้นชื่อประเทศ, ไทยขึ้น "จังหวัด, เขต" (concept เดียวกับ
                   ctAddrDisplay ใน contracts.xhtml) ★ ต่างจากหน้าลูกค้าเป้าหมาย: LeadListItemResDTO
                   (apidocs) ยืนยันแค่ currentCityName เท่านั้น ไม่มี currentDistrictName/
                   currentCountryName/currentCountryCode ระบุไว้ — อ่านเผื่อไว้แบบ optimistic
                   (ไม่มีก็แค่ได้ค่าว่าง ไม่พัง) เผื่อ backend ส่งมาจริงแม้เอกสารไม่ครบ (เคยเจอเคส
                   ProspectResDTO ไม่มี "id" ในเอกสารแต่ API ส่งมาจริงมาแล้ว) */
                function ldAddrDisplay(l){
                    var country = String((l && l.currentCountryName) || '').trim();
                    var isForeign = !!country && !/^(ไทย|thailand)$/i.test(country);
                    if (isForeign) return country;
                    var province = String((l && l.currentCityName) || '').trim();
                    var district = String((l && l.currentDistrictName) || '').trim();
                    var joined = [province, district].filter(function(s){ return s; }).join(', ');
                    return joined || '-';
                }
                /* forwardStatus ของ list item = "กลุ่ม - ขั้นตอน" (key เดียวกับที่ dashboard.js / work_modal.xhtml แกะ)
                   → แยกที่ " - " ตัวแรก : ก่อน = กลุ่มขั้นตอน, หลัง = ขั้นตอน ; ใช้ key นี้ก่อน key อื่นเสมอ
                   ไม่มี " - " : WF → ทั้งก้อนเป็นกลุ่ม (เหมือน dashboard.js) ; no-WF → ไม่มีกลุ่ม ทั้งก้อนเป็นขั้นตอน */
                function ldFwdSplit(l){
                    var fs = String((l && l.forwardStatus) || '').trim();
                    var i = fs.indexOf(' - ');
                    if(i >= 0) return { group: fs.slice(0, i).trim(), step: fs.slice(i + 3).trim() };
                    return LIST_USES_WF ? { group: fs, step: '' } : { group: '', step: fs };
                }
                /* คอลัมน์ ขั้นตอน — ส่วนหลัง " - " ของ forwardStatus ก่อน ไม่มีค่อยลอง key ชื่อขั้นตอนอื่น
                   ★ ห้าม fallback เป็นชื่อกลุ่ม (no-WF ไม่มีกลุ่ม / WF มีคอลัมน์กลุ่มแยกอยู่แล้ว) */
                function ldListStep(l){
                    var s = ldFwdSplit(l).step
                          || l.procedureName || l.stepName || l.currentStepName || l.activityStepName || l.wfsName || '';
                    return s ? String(s) : '-';
                }
                /* คอลัมน์ กลุ่มขั้นตอน (เฉพาะผลิตภัณฑ์แบบ WF Step — ซ่อนเมื่อ no-WF) — ส่วนก่อน " - " ของ forwardStatus ก่อน */
                function ldListStepGroup(l){
                    var s = ldFwdSplit(l).group || l.procedureGroupName || l.activityGroupName || '';
                    return s ? String(s) : '-';
                }
                /* cell แท็กใน tab list — pill เดียวกับ tag บนการ์ด (ไม่มีแท็ก → '-') */
                function listTagsHtml(tags){
                    var pills = (tags && tags.length) ? tags.map(tagPillHtml).join('') : '';
                    return pills ? '<div class="ld-tag-cell">'+pills+'</div>' : '-';
                }
                function renderListFromApi(items){
                    var rows = items || [];
                    g('ldListBody').innerHTML = rows.map(apiListRowHtml).join('');
                    /* ไม่มีรายการเลย → โชว์ข้อความว่าง (ย้ายมาจาก board tab เดิม) เป็น overlay กลาง .ld-list-wrap จริง
                       (ไม่ใส่ในตารางเหมือนก่อน เพราะ td/tr ไม่ยอม stretch เต็มพื้นที่ ทำให้ข้อความค้างอยู่บนไม่กลางจอ) */
                    var empty = g('ldListEmpty');
                    if(empty) empty.style.display = rows.length ? 'none' : 'flex';
                }

                /* ── INFINITE SCROLL ของ tab list ──
                   เลื่อนสุดตาราง → โหลดหน้าถัดไป แล้ว append แถว
                   ★ 17/09/2026 — load-more ต้องส่ง param ชุดเดียวกับหน้าแรก (movementTypeId, activityGroupId=0, filter ต่างๆ)
                   เดิมต่อ URL เองแล้วตก movementTypeId/activityGroupId ⇒ page 2+ ได้ข้อมูลคนละชุดกับหน้าแรก
                   → ใช้ leadsUrl('list') ตัวเดียวกัน แล้วแทนแค่ page/perPage */
                var LIST_PAGE = 1, LIST_TOTALPAGES = 1, LIST_PERPAGE = 20, LIST_LOADING = false, LIST_SCROLL_BOUND = false;
                var LIST_AUTOFILL = 0;   /* จำนวนหน้าที่ตาราง list โหลดเองไปแล้ว (ดู maybeFillList/ldAutoFillOk) */
                function listMoreUrl(page, perPage){
                    return leadsUrl('list')
                         .replace(/([?&])page=\d+/, '$1page=' + page)
                         .replace(/([?&])perPage=\d+/, '$1perPage=' + (perPage || CUR_PERPAGE));
                }
                function listLoader(on){
                    var tb = g('ldListBody'); if(!tb) return;
                    var ex = tb.querySelector('.ld-list-loader');
                    if(on){
                        if(!ex){
                            var tr = document.createElement('tr');
                            tr.className = 'ld-list-loader';
                            tr.innerHTML = '<td colspan="10" style="text-align:center;padding:10px;font-size:calc(12px + var(--ts-fs-adj,0px));color:#7C848D;">' + env.t("label.lead.loading") + '</td>';
                            tb.appendChild(tr);
                        }
                    } else if(ex){ ex.parentNode.removeChild(ex); }
                }
                /* sync paging state จาก result.leads.meta ทุกครั้งที่โหลดหน้าแรก (tab switch/เปลี่ยน product) */
                function setListMeta(leadsObj){
                    var m = (leadsObj && leadsObj.meta) || {};
                    LIST_PAGE = m.page || 1;
                    LIST_TOTALPAGES = m.totalPages || 1;
                    LIST_PERPAGE = m.perPage || CUR_PERPAGE;
                    LIST_LOADING = false;
                    LIST_AUTOFILL = 0;   /* โหลดหน้าแรกชุดใหม่ = เริ่มนับโควตา auto-fill ใหม่ */
                }
                function initListScroll(){
                    if(LIST_SCROLL_BOUND) return;
                    var wrap = document.querySelector('.ld-list-wrap');
                    if(!wrap) return;
                    LIST_SCROLL_BOUND = true;
                    wrap.addEventListener('scroll', function(){
                        if(wrap.scrollTop + wrap.clientHeight >= wrap.scrollHeight - 80) loadMoreList();
                    });
                }
                /* แถวยังไม่ล้นตาราง (scroll ไม่ได้) แต่ยังมีหน้าเหลือ → โหลดต่อให้เต็ม
                   ★ 16/09/2026 — จำกัดโควตาเหมือนฝั่งคอลัมน์บอร์ด (ดู ldAutoFillOk / maybeFillColumn)
                   ตารางนี้อยู่ใน .ld-main-card ที่ไม่มีเพดานความสูงเหมือนกัน ถ้าไม่จำกัดจะไล่โหลดทุกหน้ารวดเดียว */
                function maybeFillList(){
                    if(LIST_LOADING || LIST_PAGE >= LIST_TOTALPAGES) return;
                    var wrap = document.querySelector('.ld-list-wrap');
                    if(!ldAutoFillOk(wrap, LIST_AUTOFILL)) return;
                    LIST_AUTOFILL++;
                    loadMoreList();
                }
                function loadMoreList(){
                    if(LIST_LOADING || LIST_PAGE >= LIST_TOTALPAGES) return;
                    var next = LIST_PAGE + 1;
                    LIST_LOADING = true;
                    listLoader(true);
                    env.fetch(listMoreUrl(next, LIST_PERPAGE), {credentials:'same-origin'})
                        .then(function(r){ return r.ok ? r.json() : null; })
                        .then(function(payload){
                            var result = (payload && payload.result && typeof payload.result==='object') ? payload.result : payload;
                            var lo = result && result.leads;
                            var items = (lo && Array.isArray(lo.items)) ? lo.items : (Array.isArray(lo) ? lo : []);
                            if(items.length) g('ldListBody').insertAdjacentHTML('beforeend', items.map(apiListRowHtml).join(''));
                            LIST_PAGE = next;
                            var lm = (lo && lo.meta) || {};
                            if(lm.totalPages) LIST_TOTALPAGES = lm.totalPages;   /* อัปเดตเผื่อ total เปลี่ยน */
                        })
                        .catch(function(){})
                        .then(function(){ listLoader(false); LIST_LOADING = false; maybeFillList(); });
                }

                /* ── LIST ── */
                function renderList(leads){
                    g('ldListBody').innerHTML = leads.map(function(l){
                        var av = isLinkUrl(l.customer_avatar)
                            ? '<div class="ld-cust-av"><img src="'+esc(proxyImg(l.customer_avatar))+'" onerror="this.onerror=null;this.src=\'assets/images/default_avatar.svg\';"/></div>'
                            : '<div class="ld-cust-av"><img src="assets/images/default_avatar.svg" style="width:100%;height:100%;object-fit:cover;border-radius:50%;" alt=""/></div>';
                        var agSrc = (l.assigneeAvatars && l.assigneeAvatars[0]) || '';
                        var agAv = isLinkUrl(agSrc)
                            ? '<div class="ld-cust-av"><img src="'+esc(proxyImg(agSrc))+'" style="width:100%;height:100%;object-fit:cover;border-radius:50%;" onerror="this.onerror=null;this.src=\'assets/images/default_avatar.svg\';"/></div>'
                            : '<div class="ld-cust-av"><img src="assets/images/default_avatar.svg" style="width:100%;height:100%;object-fit:cover;border-radius:50%;" alt=""/></div>';
                        var url = 'lead_detail.face?pid=1&page_id=3&act=3&param_lead_id='+l.id;
                        return '<tr>'
                            +'<td>'+esc(l.date)+'</td>'
                            +'<td><div class="ld-lead-no">'+esc(l.lead_no)+'</div><div class="ld-contract-no">'+esc(l.contract_no)+'</div></td>'
                            +'<td><div class="ld-cust-wrap">'+av+'<span>'+esc(l.customer_name)+'</span></div></td>'
                            +'<td><div class="ld-phone"><span class="ld-phone-ic"><img src="assets/images/icon/fi_phone.svg" alt=""/></span>'+esc(l.phone)+'</div></td>'
                            +'<td>'+fmt(l.amount)+' THB</td>'
                            +'<td>'+esc(l.team)+'</td>'
                            +'<td><div class="ld-cust-wrap">'+agAv+'<span>'+esc(l.owner_name||l.owner_code||'-')+'</span></div></td>'
                            +'<td>'+esc(l.step || l.stepName || '-')+'</td>'
                            +'<td>'+interestBadge(l.interest)+'</td>'
                            +'<td>'+listTagsHtml(l.tags)+'</td>'
                            +'</tr>';
                    }).join('');
                }

                /* ── TABS ── */
                var CUR_TAB = 'board';     /* tab ปัจจุบัน — ใช้กำหนด viewMode ของทุก request */
                var CUR_MID = '';          /* movementTypeId ของผลิตภัณฑ์ที่เลือก */
                var CUR_AGID = '';         /* activityGroupId (wf step) ที่เลือกใน group dropdown ('' = ให้ server default) */
                var CUR_AGID_EFF = '';     /* activityGroupId ที่ server ตอบกลับจริง — fallback ตอน CUR_AGID ยังว่าง (default) */
                var CUR_SEARCH = '';         /* คำค้นจากช่อง search → แนบ &search= ; ตั้งค่าตอนกดค้นหา/Enter เท่านั้น */
                var CUR_SHOWCLOSED = false;  /* &showClosed → ผูกกับ toggle "ดูสถานะปิดโอกาสขายแล้ว" ; set ใหม่ตอนกดกรอง */
                var CUR_DATE_FROM = '';      /* ช่วงวันที่ field แรก → มีค่าทั้งคู่จึงแนบ dateRangeType=custom&dateFrom&dateTo */
                var CUR_DATE_TO = '';        /* ช่วงวันที่ field สอง */
                var CUR_PROVINCE = '';       /* provinceId จาก filter จังหวัด */
                var CUR_DISTRICT = '';       /* districtId จาก filter อำเภอ */
                var CUR_ACTIVE_STATUS = '';  /* activeStatus จาก dropdown สถานะการปิด */
                var CUR_SALE_GROUP = '';     /* saleGroupId จาก dropdown ทีมขาย */
                var CUR_OWNER = '';          /* employeeId จาก dropdown ผู้รับผิดชอบ (user สั่งให้ส่ง employeeId
                                                 อย่างเดียว ตัด salePersonId ออก — แม้ backend /leads เดิมจะ filter
                                                 salePersonId ได้ถูกต้องอยู่แล้วก็ตาม ดู LeadBoardView.java) */
                var CUR_FGROUP = '';         /* กลุ่มขั้นตอนจาก filter modal (เฉพาะ tab list + ผลิตภัณฑ์ WF Step) → ส่งเป็น activityGroupId เหมือน board */
                var CUR_FSTEP = '';          /* ขั้นตอนจาก filter modal (เฉพาะ tab list) → ส่งเป็น activityStepId เหมือน board (id คอลัมน์ kanban) */
                var CUR_SORT = 'txdate_desc'; /* sortBy ที่เลือกจาก sort dropdown */
                var CUR_TAGS = [];         /* tags ที่เลือกจาก filter (array of string) ; ว่าง = ไม่กรอง = ไม่ส่ง param */
                var CUR_PAGE = 1;          /* paging — reset = 1 ทุกครั้งที่โหลดครั้งแรก/dropdown/tab */
                var CUR_PERPAGE = 20;
                function resetPaging(){ CUR_PAGE = 1; CUR_PERPAGE = 20; }
                /* ต่อ URL เส้น leads + แนบ movementTypeId / activityGroupId เฉพาะเมื่อมีค่า */
                /* มีค่าทั้ง dateFrom + dateTo → แนบ dateRangeType=custom&dateFrom&dateTo ; ไม่ครบ → ไม่แนบ */
                function dateRangeParams(){
                    if(!CUR_DATE_FROM || !CUR_DATE_TO) return '';
                    return '&dateRangeType=custom'
                         + '&dateFrom=' + encodeURIComponent(CUR_DATE_FROM)
                         + '&dateTo=' + encodeURIComponent(CUR_DATE_TO);
                }
                /* filter จาก filter modal — ใช้ร่วมกันระหว่าง leadsUrl (หน้าแรก/list load-more) กับ colLeadsUrl (board load-more)
                   เพิ่ม filter ใหม่ที่นี่ที่เดียว ทุกเส้นจะส่งครบ */
                function extraFilterParams(){
                    var u = '';
                    if(CUR_PROVINCE)       u += '&provinceId='    + encodeURIComponent(CUR_PROVINCE);
                    if(CUR_DISTRICT)       u += '&districtId='    + encodeURIComponent(CUR_DISTRICT);
                    if(CUR_ACTIVE_STATUS)  u += '&activeStatus='  + encodeURIComponent(CUR_ACTIVE_STATUS);
                    if(CUR_SALE_GROUP)     u += '&saleGroupId='   + encodeURIComponent(CUR_SALE_GROUP);
                    if(CUR_OWNER)          u += '&employeeId=' + encodeURIComponent(CUR_OWNER);
                    return u;
                }
                function leadsUrl(mode){
                    var u = '../board/leads?viewMode=' + mode;
                    if(CUR_MID)  u += '&movementTypeId=' + encodeURIComponent(CUR_MID);
                    if(mode === 'list'){
                        /* tab list ไม่ยึด CUR_AGID ของ board (อาจค้าง) — กรองด้วย CUR_FGROUP/CUR_FSTEP จาก filter modal แทน
                           key เดียวกับ tab board: activityGroupId / activityStepId ; ไม่ได้เลือกอะไร → activityGroupId=0 เหมือนเดิม
                           no-WF เลือกแค่ขั้นตอน → ไม่ส่ง activityGroupId (เหมือน colLeadsUrl ของ board ที่ no-WF ไม่ส่งกลุ่ม) */
                        if(CUR_FGROUP)      u += '&activityGroupId=' + encodeURIComponent(CUR_FGROUP);
                        else if(!CUR_FSTEP) u += '&activityGroupId=0';
                        if(CUR_FSTEP)       u += '&activityStepId=' + encodeURIComponent(CUR_FSTEP);
                    } else if(CUR_AGID){
                        u += '&activityGroupId=' + encodeURIComponent(CUR_AGID);
                    }
                    if(CUR_SEARCH) u += '&search=' + encodeURIComponent(CUR_SEARCH);   /* คำค้น (ถ้ามี) */
                    u += '&showClosed=' + CUR_SHOWCLOSED;   /* toggle ดูสถานะปิดโอกาสขายแล้ว */
                    u += dateRangeParams();   /* ช่วงวันที่ (ถ้ามีค่าทั้งคู่) */
                    u += extraFilterParams();   /* จังหวัด/อำเภอ/activeStatus/saleGroup/ผู้รับผิดชอบ */
                    if(CUR_TAGS && CUR_TAGS.length) u += '&tagIds=' + encodeURIComponent(CUR_TAGS.join(','));
                    u += '&sortBy=' + CUR_SORT;
                    u += '&page=' + CUR_PAGE + '&perPage=' + CUR_PERPAGE;
                    return u;
                }
                function switchTab(name){
                    CUR_TAB = name;   /* จำ tab ปัจจุบัน → request ถัดไปส่ง viewMode ตาม tab นี้ */
                    pushFilterMode(); /* filter modal: tab list โชว์ dropdown กลุ่มขั้นตอน/ขั้นตอน, tab อื่นซ่อน */
                    resetPaging();    /* กด tab → กลับหน้า 1 */
                    document.querySelectorAll('.ld-tab').forEach(function(t){t.classList.toggle('active',t.getAttribute('data-tab')===name);});
                    g('ldTabBoard').style.display = name==='board' ? 'flex' : 'none';
                    g('ldTabList').style.display  = name==='list'  ? 'flex' : 'none';
                    if(name === 'list'){
                        var gw = g('ldGroupWrap');
                        if(gw) gw.style.display = 'none';   /* ซ่อนทันทีไม่ต้องรอ API ตอบ กัน dropdown กะพริบก่อนถูกซ่อน */
                    }
                    loadLeads();   /* กดสลับ tab → ยิง API ใหม่ด้วย viewMode ของ tab นั้น */
                }

                /* request counter — ทุก loadLeads() เพิ่ม 1, response ที่ไม่ใช่ตัวล่าสุดจะถูกทิ้ง (แก้ race condition) */
                var _leadsReqId = 0;

                /* ยิงเส้น leads ด้วย viewMode = tab ปัจจุบัน + CUR_MID + CUR_AGID
                   quiet = true → ไม่โชว์ skeleton (ใช้กับ refresh เบื้องหลังที่ไม่ควรมีจอขาวคั่น)
                   ปกติทุกทางที่ทำให้ยิง leads ใหม่ (ตัวกรอง, สลับ tab board/list, จัดเรียง, ค้นหา,
                   เปลี่ยนผลิตภัณฑ์, เปลี่ยนกลุ่มขั้นตอน, toggle ดูสถานะปิด) จะโชว์ skeleton รอทุกครั้ง
                   ★ paging อัตโนมัติ (infinite scroll ของคอลัมน์บอร์ด/ตาราง list) ไม่ผ่านฟังก์ชันนี้
                     มันยิง colLeadsUrl()/listMoreUrl() แยกต่างหาก จึงไม่โชว์ skeleton อยู่แล้วโดยธรรมชาติ */
                function loadLeads(quiet){
                    if(!window.fetch){ return; }
                    /* _leadsReqId ยังเป็น 0 = ยิงครั้งแรกของหน้า (ยังไม่มีอะไรบนจอ) → คลุมทั้งใบ
                       ครั้งถัดๆ ไป = อยู่หน้าเดิมอยู่แล้ว → คลุมเฉพาะ content ใน Board/List */
                    if(!quiet) showSkeleton(_leadsReqId > 0);
                    saveFilterState();   /* บันทึก state ก่อน call API ทุกครั้ง */
                    var mode = CUR_TAB;
                    var myId = ++_leadsReqId;   /* จำ id ของ request นี้ */
                    env.fetch(leadsUrl(mode),{credentials:'same-origin'})
                        .then(function(r){ return r.ok?r.json():null; })
                        .then(function(result){
                            if(myId !== _leadsReqId){ return; }
                            applyServerResult(result, mode);
                        })
                        /* ★ fetch/parse พัง (เน็ตหลุด, response ไม่ใช่ JSON ฯลฯ) — ต้องเรียก hideSkeleton() ด้วย
                           ไม่งั้น #ldSkeleton ค้างอยู่ตลอดไป (เดิม catch ว่างเปล่า กลืน error เงียบๆ ไม่เคยเรียก) */
                        .catch(function(err){
                            console.error('[lead] loadLeads fetch failed:', err);
                            hideSkeleton();
                        });
                }

                /* เลือกผลิตภัณฑ์ใหม่ → reset activityGroup (ให้ server default) แล้วโหลด leads ของ tab ปัจจุบัน */
                function reloadLeadsByMovementType(mid){
                    CUR_MID = mid || '';
                    CUR_AGID = '';         /* เปลี่ยน product → ล้าง activityGroupId, server จะคืน default มา */
                    CUR_FGROUP = ''; CUR_FSTEP = '';   /* กลุ่มขั้นตอน/ขั้นตอนใน filter modal เป็นของผลิตภัณฑ์เดิม → ล้าง */
                    resetPaging();         /* เปลี่ยน product → กลับหน้า 1 */
                    loadLeads();
                }

                /* เลือก workflow step ใน group dropdown → ยิง leads ใหม่พร้อม activityGroupId (tab ปัจจุบัน) */
                function reloadLeadsByActivityGroup(agid){
                    CUR_AGID = agid || '';
                    resetPaging();         /* เปลี่ยน group → กลับหน้า 1 */
                    loadLeads();
                }

                /* รับ payload จาก API (/leads) → map ส่วนที่ wire แล้วเข้า UI
                   - statusSummary → แถบบน (Lead Status)
                   - usesWorkflowStep + wfStepSummary → dropdown กลุ่มงานข้างๆ product
                   - kanban / leads → board/list (TODO: รอ map การ์ดเป็นโครงหน้า)
                   รองรับทั้ง payload เป็นก้อนเต็ม {status,message,result} และ result ตรงๆ */
                /* ★ skeleton โชว์/ซ่อนซ้ำได้ — เดิม hideSkeleton() ลบ node ทิ้งเลย (removeChild)
                   ใช้ได้ครั้งเดียวตอนเข้าหน้า พอจะโชว์ซ้ำตอนเปลี่ยน filter/tab ก็ไม่มี element เหลือแล้ว
                   เปลี่ยนเป็นซ่อนด้วย display:none แทน แล้วให้ showSkeleton() เอากลับมาได้ */
                var _skeletonHidden = false;
                /* contentOnly = true → คลุมเฉพาะพื้นที่ board/list ไม่คลุมหัว+toolbar
                   (ใช้ตอนอยู่หน้าเดิมแล้วเปลี่ยน filter/tab/จัดเรียง/ค้นหา — หัวไม่ควรกะพริบ)
                   false → คลุมทั้งใบ ใช้เฉพาะตอนเข้าหน้าครั้งแรกที่ยังไม่มีอะไรบนจอเลย */
                function showSkeleton(contentOnly){
                    var sk = document.getElementById('ldSkeleton');
                    if(!sk) return;
                    _skeletonHidden = false;   /* กัน setTimeout ของรอบก่อนหน้ามาซ่อนทับตัวที่เพิ่งโชว์ */
                    sk.classList.remove('fade-out');

                    /* sync skeleton ย่อยให้ตรง tab ปัจจุบัน (เข้าหน้าครั้งแรกใช้ SAVED_FILTER.tab
                       แต่พอสลับ tab เองต้องตามให้ทัน ไม่งั้นโชว์โครงบอร์ดตอนอยู่ tab ตาราง) */
                    var isList = (typeof CUR_TAB !== 'undefined') && CUR_TAB === 'list';
                    var skb = document.getElementById('ldSkelBoard');
                    var skl = document.getElementById('ldSkelList');
                    if(skb) skb.style.display = isList ? 'none' : 'flex';
                    if(skl) skl.style.display = isList ? 'flex' : 'none';

                    if(contentOnly){
                        /* วัดความสูงหัวจริงตอนนั้น — #ldTabBoard/#ldTabList เป็นลูกโดยตรงของ
                           .ld-main-card ที่ position:relative เหมือน overlay ตัวนี้ offsetTop จึงเทียบกันได้ตรงๆ
                           (วัดทุกครั้งที่โชว์ ไม่ hardcode เพราะแถบสรุปยอดสูงไม่เท่ากันตามโหมด emoji/wf-step) */
                        var host = document.getElementById(isList ? 'ldTabList' : 'ldTabBoard');
                        sk.style.top = host ? (host.offsetTop + 'px') : '';
                        sk.classList.add('ld-sk-content');
                    } else {
                        sk.style.top = '';
                        sk.classList.remove('ld-sk-content');
                    }
                    sk.style.display = '';
                }
                function hideSkeleton(){
                    if(_skeletonHidden) return;
                    _skeletonHidden = true;
                    var sk = document.getElementById('ldSkeleton');
                    if(!sk) return;
                    sk.classList.add('fade-out');
                    /* รอ animation จบค่อยซ่อน — เช็ค _skeletonHidden อีกรอบเผื่อมี loadLeads() ใหม่
                       เข้ามาโชว์ skeleton ระหว่าง 380ms นี้ (จะได้ไม่โดนซ่อนทับ) */
                    tmo(function(){ if(_skeletonHidden) sk.style.display = 'none'; }, 380);
                }

                function applyServerResult(payload, mode){
                    hideSkeleton();
                    if(!payload || typeof payload !== 'object' || Array.isArray(payload)){
                        console.warn('[lead] applyServerResult bail: payload ไม่ใช่ object (ได้ array/null?) =', payload,
                                     '→ servlet อาจคืน [] (bean build เก่า: getJSONArray บน result ที่เป็น object → throw)');
                        return;
                    }
                    var result = (payload.result && typeof payload.result === 'object') ? payload.result : payload;

                    /* tab list บังคับส่ง activityGroupId=0 เสมอ (ดู leadsUrl) — 0 ไม่ใช่ group จริง ห้ามเอามาทับ
                       CUR_AGID_EFF ไม่งั้นตอนกดแถวใน list จะพา activityGroupId=0 ไปที่ lead_detail (ผิด — ต้องเป็น
                       group จริงล่าสุดจาก board หรือไม่ส่งเลยถ้ายังไม่เคยมี ดู apiListRowHtml/apiCardHtml) */
                    if(mode !== 'list' && result.activityGroupId != null) CUR_AGID_EFF = String(result.activityGroupId);   /* group ที่ server ใช้จริง (เผื่อ CUR_AGID ยังว่าง=default) → ใช้ตอน column paging */
                    /* จำ movementTypeId ที่ server ใช้จริงไว้ — leads กับ movement-types ยิงขนานกัน
                       ถ้า leads กลับมาก่อน dropdown ยังว่าง sync ไม่ติด buildProductDd() จะเอาค่านี้ไป sync ซ้ำเอง */
                    if(result.id != null) LAST_SERVER_MID = String(result.id);
                    syncProductLabel(result.id);                /* เอา result.id ไป match movement-types/LD แล้วโชว์ชื่อ product ให้ตรง */
                    /* เก็บ wfStepSummary จาก API ไว้ให้แถบ WF Step (ใช้เมื่อ usesWorkflowStep=true เท่านั้น)
                       ไม่มีผลิตภัณฑ์ (PRODUCTS_EMPTY) → ถือว่าไม่มี wf step ด้วยเสมอ แม้ leads จะตอบมามีก็ตาม
                       (ทำให้ setTagTabEnabled ด้านล่าง disable ปุ่ม tag เหมือน case ไม่มี workflow step ปกติ) */
                    SERVER_WFSTEPS = (!PRODUCTS_EMPTY && result.usesWorkflowStep && Array.isArray(result.wfStepSummary) && result.wfStepSummary.length)
                                   ? result.wfStepSummary : null;
                    /* tab list: ผลิตภัณฑ์แบบ WF Step (usesWorkflowStep=true) → โชว์คอลัมน์ กลุ่มขั้นตอน ; no-WF → ซ่อน
                       (ตั้งก่อน renderListFromApi ด้านล่าง เพราะ ldListStep ดู LIST_USES_WF ตอน render แถว) */
                    LIST_USES_WF = !PRODUCTS_EMPTY && !!result.usesWorkflowStep;
                    var ldTbl = g('ldTable'); if(ldTbl) ldTbl.classList.toggle('ld-no-wf', !LIST_USES_WF);
                    if(result.statusSummary) SERVER_STATUS = result.statusSummary;   /* {total,new,success,lost,inactive,active:{...}} */
                    renderSummaryView();                        /* re-render แถบบนด้วยค่าจริง (ทั้ง Lead Status + WF Step) */
                    applyWfStepDropdown(result, mode);          /* usesWorkflowStep=true + wfStepSummary มี → แสดง dropdown */
                    setTagTabEnabled(!!SERVER_WFSTEPS); /* มี wf step จริง (flag=true + มี wfStepSummary) เท่านั้นถึง enable tag ; ไม่งั้น disable + เด้งกลับ emoji */
                    pushFilterMode();                   /* filter modal: dropdown กลุ่มขั้นตอน/ขั้นตอน (tab list) ตาม usesWorkflowStep + กลุ่มจาก wfStepSummary */
                    if(mode === 'list'){
                        /* list data อยู่ที่ result.leads.items (leads เป็น object มี items[]) */
                        var leadsObj = result.leads;
                        var rows = (leadsObj && Array.isArray(leadsObj.items)) ? leadsObj.items
                                 : (Array.isArray(leadsObj) ? leadsObj : []);
                        renderListFromApi(rows);
                        setListMeta(leadsObj);   /* paging ของ list จาก result.leads.meta */
                        initListScroll();        /* ผูก scroll ครั้งเดียว (container .ld-list-wrap คงอยู่) */
                        maybeFillList();         /* แถวน้อยจน scroll ไม่ได้ แต่มีหน้าเหลือ → โหลดต่อ */
                    } else if(Array.isArray(result.kanban)){
                        /* ไม่มีผลิตภัณฑ์ (CUR_MID ว่าง) → เส้น leads ไม่มี movementTypeId ให้ยึด server จะ
                           default เอาเอง ซึ่งไม่ตรงกับ dropdown ผลิตภัณฑ์/กลุ่มขั้นตอนที่ซ่อนไปแล้ว → บังคับว่าง
                           (list tab ไม่ผูกกับผลิตภัณฑ์แบบนี้ — ตั้งใจไม่กรอง movementTypeId อยู่แล้ว จึงไม่ต้องบังคับ) */
                        renderBoardFromKanban(PRODUCTS_EMPTY ? [] : result.kanban);     /* board → kanban */
                    }
                }

                /* เอา result.id (= movementTypeId ที่ server ตอบกลับ) ไป match กับ PRODUCT_TYPES (movement-types/LD)
                   แล้วโชว์ชื่อ product ตัวนั้นบน label + ติ๊กถูกใน dropdown ให้ตรง */
                function syncProductLabel(id){
                    if(!id || !Array.isArray(PRODUCT_TYPES)) return;
                    var match = null;
                    for(var i=0;i<PRODUCT_TYPES.length;i++){
                        if(String(PRODUCT_TYPES[i].id) === String(id)){ match = PRODUCT_TYPES[i]; break; }
                    }
                    if(!match) return;
                    var name = match.name || match.code || '';
                    if(g('ldProductLabel')) g('ldProductLabel').textContent = name;
                    CUR_PRODUCT = name;
                    CUR_MID = String(id);
                    var dd = g('ldProductDd');
                    if(dd){
                        dd.querySelectorAll('.ld-dd-item').forEach(function(item){
                            var on = String(item.getAttribute('data-id')) === String(id);
                            item.classList.toggle('selected', on);
                            var c = item.querySelector('.ld-dd-check');
                            if(on && !c){ var ic=document.createElement('i'); ic.className='fas fa-check ld-dd-check'; item.appendChild(ic); }
                            else if(!on && c){ c.remove(); }
                        });
                    }
                }

                /* บอก filter modal (components/lead/filter_modal.xhtml — คนละ closure) ว่าตอนนี้อยู่ tab ไหน / ผลิตภัณฑ์แบบ WF Step ไหม
                   เพื่อโชว์ dropdown กลุ่มขั้นตอน (เฉพาะ WF) + ขั้นตอน เฉพาะ tab list ; groups = wfStepSummary (ชุดเดียวกับ dropdown กลุ่มบน board)
                   ไม่มีผลิตภัณฑ์ (PRODUCTS_EMPTY) → list ไม่ผูกกับผลิตภัณฑ์ ไม่มีขั้นตอนให้เลือก → ไม่โชว์ */
                function pushFilterMode(){
                    if(typeof window.ldSetFilterMode !== 'function') return;
                    window.ldSetFilterMode({
                        list: CUR_TAB === 'list' && !PRODUCTS_EMPTY,
                        wf: !!LIST_USES_WF,
                        mid: CUR_MID,
                        groups: Array.isArray(SERVER_WFSTEPS) ? SERVER_WFSTEPS.map(function(st){ return { id: st.id, name: st.name || st.code || '' }; }) : [],
                        curGroup: CUR_FGROUP, curStep: CUR_FSTEP
                    });
                }

                /* เปิด/ปิดปุ่ม tag (มุมมอง WF Step) ตาม usesWorkflowStep
                   - false → disable ปุ่ม tag ; ถ้ากำลังอยู่มุมมอง tag ให้เด้งกลับ Lead Status (emoji) */
                function setTagTabEnabled(enabled){
                    var tag   = document.querySelector('.ld-seg-toggle .ld-seg[data-seg="tag"]');
                    var emoji = document.querySelector('.ld-seg-toggle .ld-seg[data-seg="emoji"]');
                    if(!tag) return;
                    tag.classList.toggle('disabled', !enabled);
                    if(!enabled && CUR_VIEW === 'tag'){
                        CUR_VIEW = 'emoji';
                        tag.classList.remove('active');
                        if(emoji) emoji.classList.add('active');
                        renderSummaryView();
                    }
                }

                /* dropdown กลุ่มงาน (workflow step) คุมจาก API:
                   - usesWorkflowStep=true และ wfStepSummary มีรายการ → แสดง dropdown สร้างจาก wfStepSummary
                   - นอกนั้น → ซ่อน (no-workflow-step) */
                function applyWfStepDropdown(result, mode){
                    var wrap = g('ldGroupWrap'), dd = g('ldGroupDd');
                    if(mode === 'list'){ if(wrap) wrap.style.display = 'none'; return; }   /* tab list บังคับ activityGroupId=0 เสมอ → ไม่ใช้ dropdown นี้ ซ่อนไปเลย */
                    if(PRODUCTS_EMPTY){ if(wrap) wrap.style.display = 'none'; return; }   /* ไม่มีผลิตภัณฑ์ → ไม่แสดง ไม่ว่า leads จะตอบ usesWorkflowStep มาว่าอะไร */
                    var steps = (result.usesWorkflowStep && Array.isArray(result.wfStepSummary)) ? result.wfStepSummary : [];
                    if(!steps.length){
                        if(wrap) wrap.style.display = 'none';
                        return;
                    }
                    if(wrap) wrap.style.display = '';
                    if(!dd) return;
                    /* หา step ที่ตรงกับ activityGroupId → ตัวที่ถูกเลือก/ติ๊กถูก ; ไม่มี/ไม่ตรง → default ตัวแรก */
                    var selIdx = 0;
                    if(result.activityGroupId != null){
                        for(var k=0;k<steps.length;k++){
                            if(String(steps[k].id) === String(result.activityGroupId)){ selIdx = k; break; }
                        }
                    }
                    dd.innerHTML = steps.map(function(s, i){
                        var name  = s.name || s.code || '';
                        var color = stepperColor(steps.length, i);
                        var sel   = i===selIdx ? ' selected' : '';
                        var chk   = i===selIdx ? '<i class="fas fa-check ld-dd-check"></i>' : '';
                        return '<div class="ld-dd-item'+sel+'" data-val="'+esc(name)+'" data-color="'+color+'" '
                             + 'data-id="'+esc(s.id||'')+'" data-code="'+esc(s.code||'')+'">'
                             + '<span style="display:flex;align-items:center;gap:8px;"><span class="ld-dd-dot" style="background:'+color+';"></span>'+esc(name)+'</span>'+chk+'</div>';
                    }).join('');
                    var first = steps[selIdx];           /* step ที่ match activityGroupId (หรือตัวแรก) */
                    g('ldGroupLabel').textContent = first.name || first.code || '';
                    if(g('ldGroupDot')) g('ldGroupDot').style.background = stepperColor(steps.length, selIdx);
                    /* มีตัวเลือกไม่ถึง 2 → ไม่มีอะไรให้เลือก → disable pill (เปิด dropdown ไม่ได้) */
                    var pill = g('ldGroupBtn');
                    if(pill) pill.classList.toggle('disabled', steps.length <= 1);
                    if(steps.length <= 1) dd.classList.remove('show');
                    dd.querySelectorAll('.ld-dd-item').forEach(function(item){
                        item.addEventListener('click', function(e){
                            e.stopPropagation();
                            dd.querySelectorAll('.ld-dd-item').forEach(function(i){
                                i.classList.remove('selected');
                                var c=i.querySelector('.ld-dd-check'); if(c) c.remove();
                            });
                            item.classList.add('selected');
                            var c=document.createElement('i'); c.className='fas fa-check ld-dd-check'; item.appendChild(c);
                            g('ldGroupLabel').textContent = item.getAttribute('data-val');
                            if(g('ldGroupDot')) g('ldGroupDot').style.background = item.getAttribute('data-color') || stepperColor(steps.length, 0);
                            dd.classList.remove('show');
                            reloadLeadsByActivityGroup(item.getAttribute('data-id'));   /* ส่ง activityGroupId = id ของ step ที่เลือก */
                        });
                    });
                }

                /* ── RENDER ── */
                var CUR_PRODUCT = 'ผลิตภัณฑ์ A';

                /* คืน block ข้อมูลของผลิตภัณฑ์ (รองรับทั้ง products{} ใหม่ และ flat เดิม) */
                function productBlock(data, label){
                    if(data && data.products){
                        return data.products[label] || data.products[CUR_PRODUCT]
                            || data.products['ผลิตภัณฑ์ A'] || data;
                    }
                    return data; /* backward-compat: flat = ผลิตภัณฑ์ A */
                }

                /* เรนเดอร์ stats + board + list ตามผลิตภัณฑ์ที่เลือก */
                /* ── summary view (toggle smiley=Lead Status / tag=WF Step) ── */
                var CUR_VIEW = 'emoji';
                var LAST_P = null;
                var SERVER_STATUS = null;     /* statusSummary จาก API (ใช้แทน summary mock บนแถบ Lead Status) */
                var SERVER_WFSTEPS = null;    /* wfStepSummary จาก API (ใช้แทน wf_summary mock บนแถบ WF Step) */
                var LIST_USES_WF = false;     /* ผลิตภัณฑ์ปัจจุบันเป็นแบบ WF Step (usesWorkflowStep) → tab list แสดงคอลัมน์ กลุ่มขั้นตอน */
                var SERVER_KANBAN = null;     /* kanban[] จาก API (board) — ใช้ตอนลากการ์ดย้ายคอลัมน์ */
                function renderWfStats(wf){
                    var row = g('ldStatsRow');
                    if(!wf){ row.innerHTML = ''; return; }
                    /* Total = ปักนิ่งนอก track ; เฉพาะ step อยู่ใน track ที่ scroll แกน X */
                    var total = '<div class="ld-stat-item"><div class="ld-stat-lbl">Total</div><div class="ld-stat-val">'+wf.total+'</div></div>';
                    var steps = (wf.groups||[]).map(function(grp){
                        return '<div class="ld-stat-item ld-stat-wf">'
                            +'<div class="ld-stat-lbl"><span class="ld-dot" style="background:'+grp.color+'"></span><span class="ld-wf-name">'+esc(grp.label)+'</span></div>'
                            +'<div class="ld-stat-val">'+grp.value+'</div></div>';
                    }).join('');
                    row.innerHTML = total + '<div class="ld-wf-track" id="ldWfTrack">'+steps+'</div>';
                }
                /* แปลง wfStepSummary (API) → โครงที่ renderWfStats ใช้ {total, groups:[{color,label,value}]} */
                function serverWfSummary(){
                    if(!SERVER_WFSTEPS || !SERVER_WFSTEPS.length) return null;
                    var total = SERVER_STATUS ? SERVER_STATUS.total : 0;
                    var n = SERVER_WFSTEPS.length;
                    return { total: total, groups: SERVER_WFSTEPS.map(function(s, i){
                        return { color: stepperColor(n, i),
                                 label: s.name || s.code || '', value: s.count || 0 };
                    }) };
                }
                function renderSummaryView(p){
                    LAST_P = p || LAST_P;
                    var wf = g('ldWfPrev'), wn = g('ldWfNext'), row = g('ldStatsRow');
                    if(CUR_VIEW === 'tag'){
                        if(row) row.classList.add('ld-wf-scroll');
                        renderWfStats(serverWfSummary());   /* ใช้ wfStepSummary จาก API เท่านั้น */
                        if(wf) wf.style.display = ''; if(wn) wn.style.display = '';
                    } else {
                        if(row) row.classList.remove('ld-wf-scroll');
                        renderStats(SERVER_STATUS);   /* ใช้ statusSummary จาก API เท่านั้น */
                        if(wf) wf.style.display = 'none'; if(wn) wn.style.display = 'none';
                    }
                }

                function renderProduct(label){
                    if(!DATA) return;
                    CUR_PRODUCT = label || CUR_PRODUCT;
                    var p = productBlock(DATA, CUR_PRODUCT);
                    window._ldDATA = p; /* expose for ldSelectLead */
                    renderSummaryView(p);
                    /* board/list ขับเคลื่อนด้วย API (applyServerResult) แล้ว — ไม่ render mock ทับ */
                }
                /* เรียกจาก dropdown ผลิตภัณฑ์ */
                window.ldSetProduct = function(label){ renderProduct(label); };

                function render(data){
                    DATA = data;
                    renderProduct(CUR_PRODUCT);
                }

                /* ── FALLBACK (โครงเปล่า — ไม่มี mock; init render ว่างก่อน แล้วข้อมูลจริงทับ) ── */
                var FALLBACK = {
                    "summary":{"total":0,"new":0,"success":0,"lost":0,"inactive":0,"active":0,"active_high":0,"active_medium":0,"active_low":0},
                    "leads":[]
                };

                var FALLBACK_KANBAN = [];

                function init(){
                    try{ render(FALLBACK); }catch(e){}
                    try{ renderBoardFromKanban(FALLBACK_KANBAN); }catch(e){}
                    document.querySelectorAll('.ld-tab').forEach(function(t){
                        t.addEventListener('click',function(){switchTab(t.getAttribute('data-tab'));});
                    });
                    /* segmented toggle (หน้ายิ้ม = Lead Status / ป้าย = WF Step) */
                    document.querySelectorAll('.ld-seg-toggle .ld-seg').forEach(function(seg){
                        seg.addEventListener('click',function(){
                            if(seg.classList.contains('disabled')) return;   /* ปุ่มถูก disable → ไม่ทำงาน */
                            seg.parentNode.querySelectorAll('.ld-seg').forEach(function(s){ s.classList.remove('active'); });
                            seg.classList.add('active');
                            CUR_VIEW = seg.getAttribute('data-seg');
                            renderSummaryView();
                        });
                    });
                    /* ลูกศรเลื่อนแถบ WF Step — เลื่อนเฉพาะ track ของ step (Total ปักนิ่ง) */
                    var sp = g('ldWfPrev'), sn = g('ldWfNext');
                    if(sp) sp.addEventListener('click', function(){ var t=g('ldWfTrack'); if(t) t.scrollLeft -= 140; });
                    if(sn) sn.addEventListener('click', function(){ var t=g('ldWfTrack'); if(t) t.scrollLeft += 140; });
                }

                /* ★ 18/09: การ์ดแนะนำลูกค้าใต้ช่องค้นหา (component กลาง odsProspectSuggest, open_down_select.js)
                   เหมือนหน้าลูกค้าเป้าหมาย (contracts.xhtml) — เลือกแล้วใส่ชื่อลงช่อง + ยิงค้นหาทันที */
                function initSearchSuggest() {
                    if (!window.odsProspectSuggest) return;
                    var input = g('ldSearchInput');
                    if (!input) return;
                    odsProspectSuggest(input, {
                        contextPath: env.ctx,
                        fetch: env.fetch,
                        onPick: function (item) {
                            input.value = item && item.value ? item.value : input.value;
                            CUR_SEARCH = input.value.trim();
                            resetPaging();
                            loadLeads();
                        }
                    });
                }

                /* ── SEARCH (แว่นขยาย → ขยาย input + ปุ่ม x) ── */
                function initSearch() {
                    var wrap = g('ldSearch'); if(!wrap) return;
                    var input = g('ldSearchInput'), clr = g('ldSearchClear'), go = g('ldSearchGo');
                    var ic = wrap.querySelector('.ld-search-ic');
                    function openSearch(){ wrap.classList.add('open'); if(input) input.focus(); }
                    function closeSearch(){
                        wrap.classList.remove('open');
                        if(input) input.value = '';
                        CUR_SEARCH = '';      /* เคลียร์ filter และ save session ว่างเสมอตอนหุบ */
                        resetPaging();
                        loadLeads();
                    }
                    function doSearch(){
                        CUR_SEARCH = input ? input.value.trim() : '';   /* มี text → แนบ &search= ; ว่าง → เคลียร์ filter */
                        resetPaging();   /* ค้นหาใหม่ → กลับหน้า 1 */
                        loadLeads();     /* ยิง API ด้วย name + param อื่นตามปกติ (ยิงเฉพาะตอนกดค้นหา/Enter) */
                    }
                    if(ic) ic.addEventListener('click', function(e){
                        e.stopPropagation();
                        if(wrap.classList.contains('open')){ if(input) input.focus(); } else { openSearch(); }
                    });
                    if(go) go.addEventListener('click', function(e){ e.stopPropagation(); doSearch(); });
                    if(clr) clr.addEventListener('click', function(e){ e.stopPropagation(); closeSearch(); });
                    if(input) input.addEventListener('keydown', function(e){
                        if(e.key === 'Enter'){ e.preventDefault(); doSearch(); }
                        else if(e.key === 'Escape'){ closeSearch(); }
                    });
                }








                /* ── DROPDOWN LOGIC ── */
                function initDropdowns() {
                    // generic toggle helper
                    function bindDropdown(btnId, ddId, labelId, onSelect) {
                        var btn = g(btnId), dd = g(ddId);
                        if (!btn || !dd) return;
                        btn.addEventListener('click', function(e) {
                            e.stopPropagation();
                            document.querySelectorAll('.ld-dropdown').forEach(function(d){ if(d!==dd) d.classList.remove('show'); });
                            dd.classList.toggle('show');
                        });
                        bindDropdownItems(ddId, labelId, onSelect);
                    }

                    /* ★ แยกส่วนผูก listener ราย item ออกมา เพราะ listener ผูกกับ element ตอน bind
                       (ไม่ใช่ event delegation) ถ้า innerHTML ของ dropdown ถูกเขียนทับทีหลัง
                       item ใหม่จะไม่มี listener เลย = กดแล้วไม่เกิดอะไรขึ้น
                       dropdown ผลิตภัณฑ์เจอเคสนี้เพราะ buildProductDd() รันหลัง bindDropdown()
                       (รอ fetch movement-types) → ต้องเรียกตัวนี้ซ้ำทุกครั้งที่ rebuild รายการ */
                    function bindDropdownItems(ddId, labelId, onSelect) {
                        var dd = g(ddId);
                        if (!dd) return;
                        dd.querySelectorAll('.ld-dd-item').forEach(function(item) {
                            item.addEventListener('click', function(e) {
                                e.stopPropagation();
                                dd.querySelectorAll('.ld-dd-item').forEach(function(i){
                                    i.classList.remove('selected');
                                    var chk = i.querySelector('.ld-dd-check');
                                    if(chk) chk.remove();
                                });
                                item.classList.add('selected');
                                var chk = document.createElement('i');
                                chk.className = 'fas fa-check ld-dd-check';
                                item.appendChild(chk);
                                if(labelId) g(labelId).textContent = item.getAttribute('data-val');
                                if(onSelect) onSelect(item);
                                dd.classList.remove('show');
                            });
                        });
                    }

                    /* Group (กลุ่มงาน) — สร้างจาก activity-groups ของ product ที่เลือก
                       ถ้า list ว่าง = no workflow step → ซ่อน dropdown */
                    function buildGroupDd(productId){
                        var wrap = g('ldGroupWrap'), dd = g('ldGroupDd');
                        var groups = (ACTIVITY_GROUPS && ACTIVITY_GROUPS[String(productId)]) || [];
                        if(!groups.length){
                            if(wrap) wrap.style.display = 'none';  /* no wf step → ไม่แสดง */
                            return;
                        }
                        if(wrap) wrap.style.display = '';
                        if(!dd) return;
                        dd.innerHTML = groups.map(function(grp, i){
                            var name  = grp.nameTh || grp.name || grp.code || '';
                            var color = stepperColor(groups.length, i);
                            var sel   = i===0 ? ' selected' : '';
                            var chk   = i===0 ? '<i class="fas fa-check ld-dd-check"></i>' : '';
                            return '<div class="ld-dd-item'+sel+'" data-val="'+esc(name)+'" data-color="'+color+'" '
                                 + 'data-id="'+esc(grp.id||'')+'" data-code="'+esc(grp.code||'')+'">'
                                 + '<span style="display:flex;align-items:center;gap:8px;"><span class="ld-dd-dot" style="background:'+color+';"></span>'+esc(name)+'</span>'+chk+'</div>';
                        }).join('');
                        var first = groups[0];
                        g('ldGroupLabel').textContent = first.nameTh || first.name || first.code || '';
                        if(g('ldGroupDot')) g('ldGroupDot').style.background = stepperColor(groups.length, 0);
                        /* ผูก click ให้ item ใหม่ (สร้าง dynamic ทุกครั้งที่เปลี่ยน product) */
                        dd.querySelectorAll('.ld-dd-item').forEach(function(item){
                            item.addEventListener('click', function(e){
                                e.stopPropagation();
                                dd.querySelectorAll('.ld-dd-item').forEach(function(i){
                                    i.classList.remove('selected');
                                    var c=i.querySelector('.ld-dd-check'); if(c) c.remove();
                                });
                                item.classList.add('selected');
                                var c=document.createElement('i'); c.className='fas fa-check ld-dd-check'; item.appendChild(c);
                                g('ldGroupLabel').textContent = item.getAttribute('data-val');
                                if(g('ldGroupDot')) g('ldGroupDot').style.background = item.getAttribute('data-color') || stepperColor(groups.length, 0);
                                dd.classList.remove('show');
                            });
                        });
                    }

                    // Product — สร้างรายการจาก API (master-data) แล้วเลือกตัวแรกเสมอ
                    /* ★ ไม่ใช่ IIFE แล้ว — PRODUCT_TYPES ไม่ได้ inject จาก bean ตอน render อีกต่อไป
                       (bean ยิง API ตอน @PostConstruct = ทั้งหน้ารวมเมนูข้าง/บนจาก template.xhtml
                        ต้องรอ API ก่อนถึงจะได้ HTML สักไบต์ เมนูเลยหายไปทั้งแถบระหว่างโหลด)
                       ตอนนี้ loadProductTypes() ฝั่ง browser ยิง ../board/master/movement-types
                       แล้วค่อยเรียกฟังก์ชันนี้เมื่อข้อมูลมาถึง */
                    function buildProductDd(){
                        if(!Array.isArray(PRODUCT_TYPES) || !PRODUCT_TYPES.length) return; /* API ว่าง = คง fallback hardcode เดิม */
                        var dd = g('ldProductDd');
                        if(!dd) return;
                        dd.innerHTML = PRODUCT_TYPES.map(function(p, i){
                            var name = p.name || p.code || '';
                            var sel  = i===0 ? ' selected' : '';
                            var chk  = i===0 ? '<i class="fas fa-check ld-dd-check"></i>' : '';
                            return '<div class="ld-dd-item'+sel+'" data-val="'+esc(name)+'" '
                                 + 'data-code="'+esc(p.code||'')+'" data-id="'+esc(p.id||'')+'">'+esc(name)+chk+'</div>';
                        }).join('');
                        /* TODO(backend): movement-types/LD ยังไม่ส่ง id มา → ใช้อันแรกแสดงไปก่อน
                           เมื่อ backend ใส่ id ใน result แล้ว ตรงนี้ (data-id ด้านบน + buildGroupDd) จะทำงานครบเอง */
                        var first = PRODUCT_TYPES[0];
                        var firstName = first.name || first.code || '';
                        g('ldProductLabel').textContent = firstName;
                        CUR_PRODUCT = firstName;        /* แสดงอันแรกเสมอ */
                        renderProduct(firstName);       /* sync board ให้ตรง product แรก */
                        buildGroupDd(first.id);
                        /* ★ innerHTML ถูกเขียนทับไปด้านบน = listener ที่ bindDropdown() ผูกไว้ตอน init
                           หายไปกับ item ชุดเก่าหมด ต้องผูกใหม่ ไม่งั้นกดเลือกผลิตภัณฑ์แล้วไม่ยิง API */
                        bindDropdownItems('ldProductDd', 'ldProductLabel', onProductSelect);
                        if(!CUR_MID) CUR_MID = String(first.id || '');
                        /* ★ ไม่ยิง loadLeads() ที่นี่แล้ว — leads ถูกยิงไปตั้งแต่ตอนหน้าโหลด (ขนานกับ
                           การ fetch movement-types) ถ้ายิงซ้ำตรงนี้จะได้ 2 request เหมือนบั๊ก [19:05]
                           ผลิตภัณฑ์ที่ server เลือกให้จริงถูก sync กลับด้วย syncProductLabel(LAST_SERVER_MID)
                           ซึ่งอาจถูกเรียกไปก่อนหน้าตอน dropdown ยังว่าง จึงต้องเรียกซ้ำตรงนี้ */
                        if(LAST_SERVER_MID) syncProductLabel(LAST_SERVER_MID);
                    }

                    /* โหลดรายการผลิตภัณฑ์จาก servlet (เส้นเดียวกับที่ schedule.face ใช้ — รันบน request
                       thread จึงมี token ปกติ) รองรับ result ทั้งแบบ {items:[...]} และ array ตรงๆ */
                    function loadProductTypes(){
                        if(!window.fetch) return;
                        env.fetch('../board/master/movement-types?type=LD', {credentials:'same-origin'})
                            .then(function(r){ return r.ok ? r.json() : null; })
                            .then(function(resp){
                                var items = (resp && resp.result && Array.isArray(resp.result.items)) ? resp.result.items
                                          : (resp && Array.isArray(resp.result)) ? resp.result
                                          : (Array.isArray(resp) ? resp : []);
                                if(!items.length){
                                    PRODUCTS_EMPTY = true;
                                    if(g('ldProductWrap')) g('ldProductWrap').style.display = 'none';
                                    if(g('ldGroupWrap')) g('ldGroupWrap').style.display = 'none';   /* ไม่มีผลิตภัณฑ์ = ไม่มีกลุ่มขั้นตอน */
                                    /* leads (ยิงขนานกัน) อาจตอบมาถึงก่อน movement-types แล้ว enable ปุ่ม tag ไว้ก่อนหน้านี้
                                       (ตอนนั้น PRODUCTS_EMPTY ยังเป็น false) → บังคับ disable ซ้ำอีกทีตรงนี้กันหลุด */
                                    SERVER_WFSTEPS = null;
                                    setTagTabEnabled(false);
                                    return;
                                }
                                PRODUCT_TYPES = items;
                                buildProductDd();
                            })
                            .catch(function(err){ console.warn('[lead] movement-types fetch failed', err); });
                    }
                    loadProductTypes();

                    // Product — สลับข้อมูล board/stats/list + โหลดกลุ่มงานตามผลิตภัณฑ์
                    /* named ไว้เพราะ buildProductDd() ต้องเอาไปผูกซ้ำหลัง rebuild รายการ */
                    function onProductSelect(item) {
                        var mid = item.getAttribute('data-id');
                        buildGroupDd(mid);
                        if(window.ldSetProduct) window.ldSetProduct(item.getAttribute('data-val'));
                        reloadLeadsByMovementType(mid);   /* แนบ movementTypeId = id ที่เลือก */
                    }
                    bindDropdown('ldProductBtn', 'ldProductDd', 'ldProductLabel', onProductSelect);

                    // Group — toggle เปิด/ปิด (รายการ item สร้าง dynamic ใน buildGroupDd)
                    (function(){
                        var gBtn = g('ldGroupBtn');
                        if(!gBtn) return;
                        gBtn.addEventListener('click', function(e){
                            e.stopPropagation();
                            if(gBtn.classList.contains('disabled')) return;   /* ไม่มีตัวเลือก → ไม่เปิด */
                            var dd = g('ldGroupDd');
                            document.querySelectorAll('.ld-dropdown').forEach(function(d){ if(d!==dd) d.classList.remove('show'); });
                            if(dd) dd.classList.toggle('show');
                        });
                    })();

                    // Sort
                    bindDropdown('ldSortBtn', 'ldSortDd', 'ldSortLabel', function(item){
                        var api = item.getAttribute('data-api') || 'txdate_desc';
                        CUR_SORT = api;
                        resetPaging();
                        saveFilterState();
                        loadLeads();
                    });

                    // close all on outside click
                    listen(document, 'click', function() {
                        document.querySelectorAll('.ld-dropdown').forEach(function(d){ d.classList.remove('show'); });
                    });
                }

                /* บันทึก filter state ลง Java HttpSession ผ่าน POST /board/filter-state */
                function saveFilterState(){
                    var state = JSON.stringify({
                        mid: CUR_MID, product: CUR_PRODUCT,
                        agid: CUR_AGID,
                        search: CUR_SEARCH, showClosed: CUR_SHOWCLOSED,
                        dateFrom: CUR_DATE_FROM, dateTo: CUR_DATE_TO,
                        tagIds: CUR_TAGS,
                        province: CUR_PROVINCE, district: CUR_DISTRICT,
                        activeStatus: CUR_ACTIVE_STATUS,
                        saleGroup: CUR_SALE_GROUP, owner: CUR_OWNER,
                        fGroup: CUR_FGROUP, fStep: CUR_FSTEP,
                        sort: CUR_SORT,
                        tab: CUR_TAB
                    });
                    try{
                        /* sendBeacon — รับประกันส่งถึงแม้จะ navigate ออกจากหน้าทันที */
                        if(env.beacon){
                            env.beacon('../board/filter-state', state);
                        } else {
                            env.fetch('../board/filter-state', {method:'POST',headers:{'Content-Type':'application/json'},body:state,credentials:'same-origin'});
                        }
                    }catch(e){}
                }
                window.ldSaveFilterState = saveFilterState;   /* expose สำหรับ ldSelectLead (outside IIFE) */

                /* คืน filter state ทั้งหมดจาก Java HttpSession (inject ผ่าน SAVED_FILTER ตอน render) */
                function restoreFilterState(){
                    var saved = (typeof SAVED_FILTER !== 'undefined') ? SAVED_FILTER : null;

                    /* ★★ guard นี้ห้ามหาย — ทุกบรรทัดใต้ลงไปอ่าน saved.xxx ตรงๆ ถ้า saved เป็น null
                       (ยังไม่เคยกด filter ในเซสชันนั้น = เข้าครั้งแรก/session ใหม่ ซึ่งเป็นเคสปกติที่สุด)
                       จะโยน TypeError ตายตั้งแต่บรรทัดแรก แล้ว loadLeads() บรรทัดท้ายฟังก์ชันไม่ถูกเรียกเลย
                       = ไม่มี fetch เกิดขึ้นทั้งหน้า บอร์ดว่างเปล่าและ skeleton ค้าง (บั๊กเดียวกับที่แก้ 17:16)
                       เช็ค _leadsReqId === 0 ด้วยเพื่อไม่ให้ยิงซ้ำกับที่ทางอื่นยิงไปแล้ว (บั๊ก 19:05) */
                    if(!saved){ if(_leadsReqId === 0){ loadLeads(); } return; }

                    /* ★ คืน CUR_MID จาก saved.mid ตรงๆ ก่อนเสมอ — ห้ามพึ่ง dropdown เหมือนเดิม
                       เพราะ movement-types ย้ายไปยิงฝั่ง browser แล้ว ตอน restore ทำงาน .ld-dd-item
                       ยังไม่ถูกสร้าง (loop ข้างล่างจะไม่เจออะไรเลย) ถ้าไม่ set ตรงนี้ leads นัดแรกจะ
                       ยิงแบบไม่มี movementTypeId → server คืนผลิตภัณฑ์ default ไม่ใช่อันที่ user ค้างไว้ */
                    if(saved.mid) CUR_MID = String(saved.mid);
                    if(saved.product){
                        CUR_PRODUCT = saved.product;
                        if(g('ldProductLabel')) g('ldProductLabel').textContent = saved.product;
                        renderProduct(saved.product);
                    }

                    /* คืน product บน dropdown — อัพเดท UI ตรงๆ โดยไม่ .click() (ป้องกัน reloadLeadsByMovementType ยิง loadLeads ซ้ำ)
                       ส่วนนี้จะไม่เจอ item ตอนเข้าหน้า (dropdown ยังว่าง) แต่ปล่อยไว้ได้ — buildProductDd()
                       จะติ๊กถูกให้เองผ่าน syncProductLabel(LAST_SERVER_MID) ตอน movement-types มาถึง */
                    if(saved.product){
                        var _prodDd = g('ldProductDd');
                        if(_prodDd){
                            var _items = _prodDd.querySelectorAll('.ld-dd-item');
                            for(var _i=0;_i<_items.length;_i++){
                                var _item = _items[_i];
                                var _isSel = _item.getAttribute('data-val') === saved.product;
                                _item.classList.toggle('selected', _isSel);
                                var _chk = _item.querySelector('.ld-dd-check');
                                if(_chk) _chk.remove();
                                if(_isSel){
                                    var _c = document.createElement('i');
                                    _c.className = 'fas fa-check ld-dd-check';
                                    _item.appendChild(_c);
                                    CUR_MID     = String(_item.getAttribute('data-id') || '');
                                    CUR_PRODUCT = saved.product;
                                    if(g('ldProductLabel')) g('ldProductLabel').textContent = saved.product;
                                    renderProduct(saved.product);
                                    /* buildGroupDd อยู่ใน scope ของ initDropdowns — เรียกตรงไม่ได้
                                       group dd จะถูก rebuild โดย applyWfStepDropdown() หลัง API ตอบกลับ */
                                }
                            }
                        }
                    }

                    /* คืน CUR_* variables (filter overlay) */
                    CUR_SEARCH        = saved.search       || '';
                    CUR_SHOWCLOSED    = !!saved.showClosed;
                    CUR_DATE_FROM     = saved.dateFrom     || '';
                    CUR_DATE_TO       = saved.dateTo       || '';
                    CUR_PROVINCE      = saved.province     || '';
                    CUR_DISTRICT      = saved.district     || '';
                    CUR_ACTIVE_STATUS = saved.activeStatus || '';
                    CUR_SALE_GROUP    = saved.saleGroup    || '';
                    CUR_OWNER         = saved.owner        || '';
                    CUR_FGROUP        = saved.fGroup       || '';
                    CUR_FSTEP         = saved.fStep        || '';
                    CUR_TAGS          = (Array.isArray(saved.tagIds) && saved.tagIds.length) ? saved.tagIds : [];
                    /* คืน agid — set หลัง product click (product click reset CUR_AGID='') เพื่อให้ final loadLeads() ส่ง activityGroupId ถูก
                       applyWfStepDropdown จะ highlight item ที่ตรงกับ result.activityGroupId ที่ server ตอบกลับเอง */
                    CUR_AGID          = saved.agid         || '';
                    var _validSorts = {txdate_desc:1,txdate_asc:1,id_asc:1,id_desc:1,status:1};
                    CUR_SORT = (saved.sort && _validSorts[saved.sort]) ? saved.sort : 'txdate_desc';
                    /* sync sort dropdown UI */
                    (function(){
                        var dd = g('ldSortDd'); if(!dd) return;
                        dd.querySelectorAll('.ld-dd-item').forEach(function(it){
                            var isMatch = it.getAttribute('data-api') === CUR_SORT;
                            it.classList.toggle('selected', isMatch);
                            var chk = it.querySelector('.ld-dd-check'); if(chk) chk.remove();
                            if(isMatch){
                                var c = document.createElement('i'); c.className = 'fas fa-check ld-dd-check';
                                it.appendChild(c);
                                if(g('ldSortLabel')) g('ldSortLabel').textContent = it.getAttribute('data-val');
                            }
                        });
                    })();
                    if(saved.tab)          CUR_TAB           = saved.tab;

                    /* คืน tab (board/list) */
                    if(saved.tab){
                        document.querySelectorAll('.ld-tab').forEach(function(t){
                            t.classList.toggle('active', t.getAttribute('data-tab') === saved.tab);
                        });
                        var tb = g('ldTabBoard'), tl = g('ldTabList');
                        if(tb) tb.style.display = saved.tab === 'board' ? 'flex' : 'none';
                        if(tl) tl.style.display  = saved.tab === 'list'  ? 'flex' : 'none';
                    }

                    /* คืน search bar */
                    if(saved.search){
                        var si = g('ldSearchInput'), sw = g('ldSearch');
                        if(si){ si.value = saved.search; if(sw) sw.classList.add('open'); }
                    }

                    /* คืน filter form รวมทั้งอำเภอ — ldApplyFilterToForm (components/lead/filter_modal.xhtml)
                       จัดการ loadDistricts ภายใน (async) callback รันหลัง district options โหลดเสร็จ
                       เพื่อ re-capture badge ให้ตรง
                       ★ เก็บ snapshot ไว้ผ่าน ldSetRestoredSnap ด้วย เพราะตอนนี้ sale-group/owner/province
                         ยังไม่มี <option> (loadFilterMasters ยังยิงไม่เสร็จ) การ set .value จึงยังไม่ติด
                         loadFilterMasters() ในไฟล์นั้นจะเอาก้อนนี้มา apply ซ้ำให้เองตอนข้อมูลมาถึง
                       ★ applyFilterToForm/captureFilter/updateFilterBadge ย้ายไปอยู่
                         components/lead/filter_modal.xhtml แล้ว (คนละ closure) เรียกผ่าน window.ldXxx เท่านั้น */
                    var restoredSnap = {
                        showClosed: !!saved.showClosed,
                        dateFrom:   saved.dateFrom || '',
                        dateTo:     saved.dateTo   || '',
                        tagIds: (Array.isArray(saved.tagIds) && saved.tagIds.length) ? saved.tagIds : [],
                        selects: [
                            { id: 'ldCloseStatusSel', val: saved.activeStatus || '' + env.t("label.contracts.filter_all") + '' },
                            { id: 'ldSaleGroupSel',   val: saved.saleGroup    || '' + env.t("label.contracts.filter_all") + '' },
                            { id: 'ldOwnerSel',       val: saved.owner        || '' + env.t("label.contracts.filter_all") + '' },
                            { id: 'ldProvinceSel',    val: saved.province     || '' + env.t("label.contracts.filter_all") + '' },
                            { id: 'ldDistrictSel',    val: saved.district     || '' + env.t("label.contracts.filter_all") + '' }
                        ]
                    };
                    window.ldSetRestoredSnap(restoredSnap);
                    window.ldApplyFilterToForm(restoredSnap, function(){
                        window.ldRecaptureAppliedFilter();
                    });

                    window.ldRecaptureAppliedFilter();
                    loadLeads();   /* โหลด leads ใหม่ด้วย filter ที่คืนกลับมา */
                }

                if(readyState==='loading'){onReady(function(){init();initSearch();initSearchSuggest();window.ldInitFilter();initDropdowns();restoreFilterState();initBoardGrabScroll();initListGrabScroll();});}
                else{init();initSearch();initSearchSuggest();window.ldInitFilter();initDropdowns();restoreFilterState();initBoardGrabScroll();initListGrabScroll();}

                /* bridge: เผยแพร่ของที่ modal ไฟล์แยก (components/lead/filter_modal.xhtml) ต้องใช้
                   ★ 2026-08-24 — modal ที่แยกไฟล์ออกไปเป็น <ui:include> คนละ <script> tag = คนละ
                   closure กับ IIFE นี้ อ่านตัวแปร/เรียกฟังก์ชันตรงๆ ไม่ได้ (ตามรูปแบบเดียวกับที่
                   lead_detail.xhtml ทำไว้ตอนแยก modal — ดู comment ~2026-08-21 ในไฟล์นั้น)
                   CUR_* (province/district/activeStatus/saleGroup/owner/fGroup/fStep/dateFrom/dateTo/tags/
                   showClosed) เป็นของ leadsUrl()/loadLeads() โดยตรง — filter_modal.xhtml ไม่ถือ
                   สำเนาของตัวเอง ส่งค่าที่ apply แล้วมาตั้งผ่าน bridge นี้เท่านั้น กัน state หลุด sync */
                /* master แท็ก (name → colorCode) จาก filter modal (ที่ยิง /board/tags อยู่แล้ว — ไม่ยิงซ้ำ) → ทาสี pill แท็กบนการ์ด/ตาราง */
                window.ldSetTagColors = function (list) {
                    TAG_COLORS = {};
                    (Array.isArray(list) ? list : []).forEach(function (t) {
                        if (t && t.name != null && t.colorCode) { TAG_COLORS[t.name] = t.colorCode; }
                    });
                    recolorTagPills();
                };
                window.ldApplyFilterValues = function (v) {
                    CUR_SHOWCLOSED = v.showClosed; CUR_DATE_FROM = v.dateFrom; CUR_DATE_TO = v.dateTo; CUR_TAGS = v.tags;
                    CUR_PROVINCE = v.province; CUR_DISTRICT = v.district; CUR_ACTIVE_STATUS = v.activeStatus;
                    CUR_SALE_GROUP = v.saleGroup; CUR_OWNER = v.owner;
                    CUR_FGROUP = v.fGroup || ''; CUR_FSTEP = v.fStep || '';
                    resetPaging();   /* กรองใหม่ → กลับหน้า 1 */
                    loadLeads();     /* ยิง API lead ด้วยค่าที่กรองใหม่ (เรียก saveFilterState() ในตัวอยู่แล้ว) */
                };
                window.ldClearFilterValues = function () {
                    CUR_PROVINCE = ''; CUR_DISTRICT = ''; CUR_ACTIVE_STATUS = ''; CUR_SALE_GROUP = ''; CUR_OWNER = '';
                    CUR_FGROUP = ''; CUR_FSTEP = '';
                    CUR_SEARCH = ''; CUR_SHOWCLOSED = false; CUR_DATE_FROM = ''; CUR_DATE_TO = ''; CUR_TAGS = [];
                };
            })();

  /* ════════════════ components/access_pop.xhtml · "ผู้มีสิทธิ์เข้าถึง" popover ════════════════ */
(function () {
            function esc(s){ return (s==null?'':String(s)).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
            function proxyImg(u){
                if(!u) return '';
                u = ('' + u).trim();
                if(!u) return '';
                var l = u.toLowerCase();
                return (l.indexOf('http://') === 0 || l.indexOf('https://') === 0)
                    ? env.docProxy(u) : u;
            }
            var pop = null;
            var closeTimer = null;
            function getPop() {
                if (!pop) {
                    pop = document.getElementById('ldAccessPop');
                    if (pop) {
                        pop.addEventListener('wheel', function(e) { e.stopPropagation(); }, {passive:true});
                        pop.addEventListener('touchmove', function(e) { e.stopPropagation(); }, {passive:true});
                        pop.addEventListener('mouseenter', function() { if (closeTimer) { clearTimeout(closeTimer); closeTimer = null; } });
                        pop.addEventListener('mouseleave', function() { window.ldStartCloseAccessPop(); });
                    }
                }
                return pop;
            }

            window.ldShowAccessPop = function (el, assignees, myEmployeeId) {
                var p = getPop();
                if (!p) return;
                assignees = assignees || [];
                /* หาแถวที่เป็นผู้ login ปัจจุบันจริง (เทียบ id ไม่ใช่เดาจาก index) แล้วขยับขึ้นบนสุด — ไม่พบ/
                   ไม่มี myEmployeeId ส่งมา → ปล่อยลำดับเดิมทั้งหมด ไม่ติด badge "(ฉัน)" กับใครเลย */
                var meIdx = -1;
                if (myEmployeeId) {
                    for (var i = 0; i < assignees.length; i++) {
                        if (String(assignees[i].id) === String(myEmployeeId)) { meIdx = i; break; }
                    }
                }
                if (meIdx > 0) {
                    assignees = assignees.slice();
                    var me = assignees.splice(meIdx, 1)[0];
                    assignees.unshift(me);
                    meIdx = 0;
                }
                var list = document.getElementById('ldAccessPopList');
                var title = document.getElementById('ldAccessPopTitle');
                if (title) title.textContent = (window.LD_ACCESS_TITLE || '') + ' (' + assignees.length + ')';
                if (list) {
                    list.innerHTML = assignees.map(function (a, i) {
                        var av = a.avatar
                            ? '<div class="ld-access-av"><img src="' + esc(proxyImg(a.avatar)) + '" onerror="this.onerror=null;this.src=\'assets/images/default_avatar.svg\';"/></div>'
                            : '<div class="ld-access-av"><img src="assets/images/default_avatar.svg" style="width:100%;height:100%;object-fit:cover;border-radius:50%;" alt=""/></div>';
                        var isMe = (i === meIdx);
                        var me = isMe ? '<span class="ld-access-me">' + env.t("label.lead.me_suffix") + '</span>' : '';
                        return '<div class="ld-access-pop-item' + (isMe ? ' is-me' : '') + '">' + av
                            + '<span class="ld-access-name">' + esc(a.name || '') + me + '</span>'
                            + '</div>';
                    }).join('');
                }

                var colBody = el.closest('.ld-col-body');
                var elRect = el.getBoundingClientRect();
                var pw = 230, maxPopH = 300;
                if (colBody) {
                    /* board view (lead.xhtml) — position:absolute ใน colBody, scroll ตาม column */
                    if (getComputedStyle(colBody).position === 'static') colBody.style.position = 'relative';
                    if (p.parentNode !== colBody) colBody.appendChild(p);
                    p.style.position = 'absolute';
                    var colRect = colBody.getBoundingClientRect();
                    var spaceBelow = colRect.bottom - elRect.bottom - 8;
                    var spaceAbove = elRect.top - colRect.top - 8;
                    var top, allowedH;
                    if (spaceBelow >= maxPopH || spaceBelow >= spaceAbove) {
                        allowedH = Math.min(maxPopH, spaceBelow);
                        top = elRect.bottom - colRect.top + colBody.scrollTop + 6;
                    } else {
                        allowedH = Math.min(maxPopH, spaceAbove);
                        top = elRect.top - colRect.top + colBody.scrollTop - allowedH - 6;
                    }
                    p.style.maxHeight = allowedH + 'px';
                    var listEl = document.getElementById('ldAccessPopList');
                    if (listEl) listEl.style.maxHeight = Math.max(80, allowedH - 48) + 'px';
                    var left = elRect.right - pw - colRect.left;
                    if (left < 4) left = 4;
                    if (left + pw > colBody.clientWidth - 4) left = colBody.clientWidth - pw - 4;
                    p.style.top  = top  + 'px';
                    p.style.left = left + 'px';
                } else {
                    /* list view (lead.xhtml) / lead_detail.xhtml (ไม่มี .ld-col-body เลย) —
                       position:fixed ตาม viewport */
                    if (p.parentNode !== document.body) document.body.appendChild(p);
                    p.style.position = 'fixed';
                    var spaceBelow = window.innerHeight - elRect.bottom - 8;
                    var spaceAbove = elRect.top - 8;
                    var top, allowedH;
                    if (spaceBelow >= maxPopH || spaceBelow >= spaceAbove) {
                        allowedH = Math.min(maxPopH, spaceBelow);
                        top = elRect.bottom + 6;
                    } else {
                        allowedH = Math.min(maxPopH, spaceAbove);
                        top = elRect.top - allowedH - 6;
                    }
                    p.style.maxHeight = allowedH + 'px';
                    var listEl = document.getElementById('ldAccessPopList');
                    if (listEl) listEl.style.maxHeight = Math.max(80, allowedH - 48) + 'px';
                    var left = elRect.right - pw;
                    if (left < 8) left = 8;
                    if (left + pw > window.innerWidth - 8) left = window.innerWidth - pw - 8;
                    p.style.top  = top  + 'px';
                    p.style.left = left + 'px';
                }

                p.style.display = 'flex';
                p.classList.add('show');
            };

            window.ldCloseAccessPop = function () {
                closeTimer = null;
                var p = getPop();
                if (!p) return;
                p.classList.remove('show');
                p.style.display = 'none';
                if (p.parentNode !== document.body) document.body.appendChild(p);
            };

            window.ldStartCloseAccessPop = function () {
                if (closeTimer) clearTimeout(closeTimer);
                closeTimer = tmo(window.ldCloseAccessPop, 150);
            };
        })();

  /* ════════════════ components/lead/filter_modal.xhtml · filter dialog ════════════════ */
(function () {
            /* ★ ไฟล์นี้ include แยกจาก lead.xhtml (main) = คนละ closure กัน เรียก g()/esc() ของ
               main ตรงๆ ไม่ได้ (ReferenceError) — มีสำเนา local ของตัวเอง เหมือนกันทุกตัวอักษรกับต้นฉบับ
               (ตามรูปแบบเดียวกับ script block ที่ 2 ใน lead.xhtml ที่ทำกับ esc()/proxyImg() ของ popup) */
            function g(id){ return document.getElementById(id); }
            function esc(s){ return (s==null?'':String(s)).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

                /* master-data ของ modal ตัวกรอง — ไม่ inject จาก bean แล้ว (ไม่ต้อง block การ render หน้า)
                   loadFilterMasters() ยิงเองผ่าน servlet หลังหน้าโหลด แล้วเติม dropdown ให้ทีหลัง */
                var TAGS = [];
                var SALE_GROUPS = [];
                var PROVINCES   = [];
                var EMPLOYEES   = [];
                /* dropdown "สถานะการปิด" เปลี่ยน options + label ตาม toggle "ดูสถานะปิดโอกาสขายแล้ว"
                   เปิด (active) → ทั้งหมด/SUCCESS/LOST, label "สถานะการปิด" ; ปิด (inactive) → ทั้งหมด/NEW/INACTIVE/HOT/WARM/COLD, label "สถานะ" */
                function syncCloseStatusOptions(){
                    var sel = g('ldCloseStatusSel'); if(!sel) return;
                    var on = g('ldToggleStatus') && g('ldToggleStatus').checked;
                    var opts = on ? ['' + env.t("label.contracts.filter_all") + '','SUCCESS','LOST']
                                  : ['' + env.t("label.contracts.filter_all") + '','NEW','INACTIVE','HOT','WARM','COLD'];
                    sel.innerHTML = opts.map(function(o){ return '<option>'+o+'</option>'; }).join('');
                    var lbl = g('ldCloseStatusLbl');
                    if(lbl) lbl.textContent = on ? '' + env.t("label.lead.col_close_status") + '' : '' + env.t("label.template.status") + '';
                }
                /* ── MASTER DROPDOWNS (ทีมขาย/จังหวัด/อำเภอ) ── */
                /* เติม <option> จาก master-data ต่อท้าย "ทั้งหมด" : value=id, label=name */
                function fillSelect(sel, items){
                    if(!sel || !Array.isArray(items)) return;
                    sel.insertAdjacentHTML('beforeend', items.map(function(it){
                        var val = (it.id != null) ? it.id : (it.code != null ? it.code : (it.name||''));
                        var nm  = it.name || it.code || '';
                        return '<option value="'+esc(String(val))+'">'+esc(nm)+'</option>';
                    }).join(''));
                }
                /* อำเภอกลับเป็น "ทั้งหมด" + disable (ตอนจังหวัด=ทั้งหมด หรือก่อนเลือกจังหวัด) */
                function resetDistrict(){
                    var d = g('ldDistrictSel'); if(!d) return;
                    d.innerHTML = '<option>' + env.t("label.contracts.filter_all") + '</option>';
                    d.value = '' + env.t("label.contracts.filter_all") + '';
                    d.disabled = true;
                }
                /* โหลดอำเภอของจังหวัด provinceId → enable + เลือก selectVal (ถ้ามี) ไม่งั้นทั้งหมด */
                function loadDistricts(provinceId, selectVal, onDone){
                    var d = g('ldDistrictSel'); if(!d || !provinceId) return;
                    d.disabled = true;   /* ระหว่างโหลด */
                    env.fetch('../board/districts?provinceId=' + encodeURIComponent(provinceId), {credentials:'same-origin'})
                        .then(function(r){ return r.ok ? r.json() : []; })
                        .then(function(list){
                            d.innerHTML = '<option>' + env.t("label.contracts.filter_all") + '</option>';
                            fillSelect(d, Array.isArray(list) ? list : []);
                            d.disabled = false;
                            d.value = (selectVal != null && selectVal !== '') ? selectVal : '' + env.t("label.contracts.filter_all") + '';
                            if(!d.value) d.value = '' + env.t("label.contracts.filter_all") + '';
                            if(onDone) onDone();
                        })
                        .catch(function(){ d.disabled = false; if(onDone) onDone(); });
                }
                function initMasterDropdowns(){
                    fillSelect(g('ldSaleGroupSel'), (typeof SALE_GROUPS !== 'undefined' && Array.isArray(SALE_GROUPS)) ? SALE_GROUPS : []);
                    fillSelect(g('ldProvinceSel'),  (typeof PROVINCES   !== 'undefined' && Array.isArray(PROVINCES))   ? PROVINCES   : []);
                    /* employees: ★ 28/09 แสดงแค่ name ไม่โชว์รหัสนำหน้า (concept ผู้รับผิดชอบ = ชื่อล้วน) ; value ยังเป็น id */
                    var empSel = g('ldOwnerSel');
                    if(empSel && typeof EMPLOYEES !== 'undefined' && Array.isArray(EMPLOYEES)){
                        empSel.insertAdjacentHTML('beforeend', EMPLOYEES.map(function(it){
                            var val = (it.id != null) ? it.id : (it.code || '');
                            var lbl = it.name || it.code || '';
                            return '<option value="'+esc(String(val))+'">'+esc(lbl)+'</option>';
                        }).join(''));
                    }
                    var prov = g('ldProvinceSel');
                    if(prov) prov.addEventListener('change', function(){
                        if(APPLYING_FORM) return;   /* change ที่ applyFilterToForm ยิงเองเพื่อซิงก์ป้าย dropdown — อำเภอจัดการต่อใน applyFilterToForm เอง */
                        /* จังหวัดเปลี่ยน → อำเภอ reset เป็นทั้งหมดเสมอ */
                        if(prov.selectedIndex === 0) resetDistrict();   /* ทั้งหมด */
                        else loadDistricts(prov.value, null);
                    });
                }
                /* tag multi-select: ติ๊ก checkbox → chip ด้านล่าง ; ติ๊กครบทุกอัน (ทั้งหมด) = ไม่โชว์ chip (=ไม่กรอง)
                   value = id (ส่งหาหลังบ้าน), data-name = ชื่อแสดงผล */
                function initTagDropdown(){
                    var dd = g('ldTagDd'); if(!dd) return;
                    var btn = g('ldTagBtn'), panel = g('ldTagPanel'), chips = g('ldTagChips'), all = g('ldTagAll');
                    var scroller = g('ldTagScroll') || panel;
                    var tagList = (typeof TAGS !== 'undefined' && Array.isArray(TAGS)) ? TAGS : [];
                    scroller.insertAdjacentHTML('beforeend', tagList.map(function(t){
                        var nm  = t.name || t.code || '';
                        var val = String(t.id != null ? t.id : nm);   /* ส่ง id หาหลังบ้าน */
                        return '<label class="ld-tagdd-opt"><input type="checkbox" class="ld-tag-cb" value="'+esc(val)+'" data-name="'+esc(nm)+'"/><span>'+esc(nm)+'</span></label>';
                    }).join(''));
                    var cbs = panel.querySelectorAll('.ld-tag-cb');
                    function selectedCbs(){ return Array.prototype.filter.call(cbs, function(c){ return c.checked; }); }
                    function selected(){ return selectedCbs().map(function(c){ return c.value; }); }
                    function render(){
                        var selCbs = selectedCbs();
                        var allChecked = selCbs.length === cbs.length && cbs.length > 0;
                        if(all) all.classList.toggle('active', allChecked);
                        /* โชว์ chip เฉพาะตอนเลือก "บางอัน" (ไม่ใช่ทั้งหมด/ไม่มี) ; chip แสดง name, data-tag เก็บ id */
                        chips.innerHTML = (allChecked || selCbs.length === 0) ? '' : selCbs.map(function(c){
                            var nm = c.getAttribute('data-name') || c.value;
                            return '<span class="ld-f-chip" data-tag="'+esc(c.value)+'">'+esc(nm)+' <i class="fas fa-xmark"></i></span>';
                        }).join('');
                        chips.style.marginTop = chips.firstChild ? '12px' : '0';   /* มี chip → ห่าง 12px ; ว่าง → ไม่เว้น */
                        var firstNm = selCbs.length ? (selCbs[0].getAttribute('data-name') || selCbs[0].value) : '';
                        btn.textContent = selCbs.length === 0 ? '' + env.t("label.dashboard.select") + '' : allChecked ? '' + env.t("label.contracts.filter_all") + ''
                                        : selCbs.length === 1 ? firstNm : (selCbs.length + ' ' + env.t("label.lead.items_unit") + '');
                    }
                    /* ค้นหาแท็กใน dropdown — กรอง option ตามชื่อ (data-name) */
                    var search = g('ldTagSearch');
                    function tagFilter(){
                        var q = (search && search.value ? search.value : '').trim().toLowerCase();
                        Array.prototype.forEach.call(cbs, function(c){
                            var opt = c.closest('.ld-tagdd-opt'); if(!opt) return;
                            var nm = (c.getAttribute('data-name') || '').toLowerCase();
                            opt.classList.toggle('ld-hide', !!q && nm.indexOf(q) < 0);
                        });
                    }
                    if(search){ search.addEventListener('input', tagFilter); }
                    btn.addEventListener('click', function(){
                        /* ไม่ stopPropagation แล้ว — ให้คลิกนี้ bubble ถึง document เพื่อให้ open_down_select.js (closeAll) ปิดลิสต์ของ dropdown
                           อื่น (สถานะ/ทีมขาย/จังหวัด/...) ที่เปิดค้างอยู่ ; ตัวปิด panel แท็กตอนคลิกนอกอยู่ที่ capture listener ท้ายฟังก์ชัน
                           (เดิมสั่ง stopPropagation ทั้ง 2 ฝั่งจึงเปิดซ้อนกัน 2 อันได้) */
                        dd.classList.toggle('open');
                        if(dd.classList.contains('open') && search){ tmo(function(){ search.focus(); }, 0); }
                    });
                    panel.addEventListener('click', function(e){ e.stopPropagation(); });
                    if(all) all.addEventListener('click', function(e){
                        e.stopPropagation();
                        Array.prototype.forEach.call(cbs, function(c){ c.checked = false; });   /* ทั้งหมด = ไม่กรอง → เคลียร์ติ๊กทุกอัน */
                        render();
                        dd.classList.remove('open');   /* กดทั้งหมด → ปิด dropdown เลย */
                    });
                    Array.prototype.forEach.call(cbs, function(c){ c.addEventListener('change', render); });
                    chips.addEventListener('click', function(e){   /* ปุ่ม ✕ บน chip → uncheck tag นั้น (data-tag = id) */
                        var ic = e.target.closest('.ld-f-chip i'); if(!ic) return;
                        var tagId = ic.closest('.ld-f-chip').getAttribute('data-tag');
                        Array.prototype.forEach.call(cbs, function(c){ if(c.value === tagId) c.checked = false; });
                        render();
                    });
                    /* คลิกนอก dropdown แท็ก → ปิด panel — ต้องเป็น capture phase : dropdown กลาง (open_down_select.js) สั่ง
                       stopPropagation ตอนกดปุ่มของมัน ถ้าฟังแบบ bubble จะไม่ได้ยินคลิกนั้นเลย → panel แท็กค้างเปิดซ้อนกับลิสต์ของมัน */
                    listen(document, 'click', function(e){ if(!dd.contains(e.target)) dd.classList.remove('open'); }, true);
                    dd._reset = function(){ Array.prototype.forEach.call(cbs, function(c){ c.checked = false; }); render(); };
                    dd._render = render;   /* ให้ภายนอก (restore snapshot) สั่ง re-render chips/ปุ่มได้ */
                    render();
                }
                /* ── กลุ่มขั้นตอน + ขั้นตอน (เฉพาะ tab list) ──
                   main (lead.xhtml) เป็นเจ้าของค่าที่กรองอยู่จริง (CUR_FGROUP/CUR_FSTEP) แล้วส่งมาให้ผ่าน setFilterMode
                   → LS_APPLIED ; ฟอร์มของไฟล์นี้ sync จาก LS_APPLIED เสมอ (ตอนเปิด modal / ตอน response กลับมา)
                   ไม่ผ่าน snapshot (APPLIED_FILTER) เพราะ option ของ 2 ช่องนี้โหลดทีหลังแบบ async
                   - WF: กลุ่มขั้นตอนมาจาก wfStepSummary (ชุดเดียวกับ dropdown กลุ่มบน board) ; ขั้นตอนต้องอยู่ในกลุ่มที่เลือก
                     → ยังไม่เลือกกลุ่ม = ขั้นตอน disabled ; เปลี่ยนกลุ่ม = โหลดขั้นตอนของกลุ่มนั้นใหม่ (เหมือนจังหวัด→อำเภอ)
                   - no-WF: ไม่มีกลุ่ม → ขั้นตอนโหลดของผลิตภัณฑ์ทั้งก้อน
                   รายการขั้นตอน = คอลัมน์ kanban ของ /board/leads?viewMode=board (stepId/stepName) ที่ board ใช้อยู่แล้ว
                   (ไม่มี master ขั้นตอนที่ไม่ผูก lead) ; ค่าที่ส่งกลับ main = id → ยิง activityGroupId / activityStepId เหมือน tab board */
                var LS_ALL = '' + env.t("label.contracts.filter_all") + '';
                var LS_MODE = { list:false, wf:false, mid:'' };
                var LS_GROUPS = [];                       // [{id,name}]
                var LS_APPLIED = { group:'', step:'' };   // ค่าที่กรองอยู่จริง (เจ้าของคือ main)
                var LS_STEP_CACHE = {};                   // 'mid|group' → Promise<[{id,name}]>
                var LS_SEQ = 0;                           // กัน race: เปลี่ยนกลุ่มเร็วๆ ให้ response เก่าถูกทิ้ง
                function lsLoadSteps(groupId){
                    var key = LS_MODE.mid + '|' + (groupId || '');
                    if(LS_STEP_CACHE[key]) return LS_STEP_CACHE[key];
                    var u = '../board/leads?viewMode=board&page=1&perPage=1';
                    if(LS_MODE.mid) u += '&movementTypeId=' + encodeURIComponent(LS_MODE.mid);
                    if(groupId)     u += '&activityGroupId=' + encodeURIComponent(groupId);
                    var p = env.fetch(u, {credentials:'same-origin'})
                        .then(function(r){ return r.ok ? r.json() : null; })
                        .then(function(payload){
                            var result = (payload && payload.result && typeof payload.result === 'object') ? payload.result : payload;
                            var kb = (result && Array.isArray(result.kanban)) ? result.kanban : [];
                            return kb.map(function(c){
                                var id = (c.stepId != null ? c.stepId : c.id != null ? c.id : c.procedureId != null ? c.procedureId : c.activityStepId);
                                return { id: id, name: c.stepName || c.name || '' };
                            }).filter(function(c){ return c.id != null; });
                        })
                        .catch(function(){ return []; })
                        .then(function(list){ if(!list.length) delete LS_STEP_CACHE[key]; return list; });   // ว่าง/พัง = ไม่ cache ให้ลองใหม่ได้
                    LS_STEP_CACHE[key] = p;
                    return p;
                }
                /* เติมขั้นตอนของ groupId ('' = ทั้งผลิตภัณฑ์) แล้วเลือก selectVal (ถ้ามี) */
                function lsSetSteps(groupId, selectVal){
                    var st = g('ldFStepSel'); if(!st) return;
                    var mySeq = ++LS_SEQ;
                    st.disabled = true;   // ระหว่างโหลด
                    lsLoadSteps(groupId).then(function(list){
                        if(mySeq !== LS_SEQ) return;
                        st.innerHTML = '<option>' + LS_ALL + '</option>';
                        fillSelect(st, list);
                        st.disabled = false;
                        st.value = (selectVal != null && selectVal !== '') ? String(selectVal) : LS_ALL;
                        if(!st.value) st.value = LS_ALL;   // ขั้นตอนที่เคยเลือกไม่อยู่ในรายการแล้ว → ทั้งหมด
                        updateFilterBadge();
                    });
                }
                /* WF ที่ยังไม่เลือกกลุ่ม → ขั้นตอนกลับเป็นทั้งหมด + disabled */
                function lsResetStep(){
                    var st = g('ldFStepSel'); if(!st) return;
                    LS_SEQ++;
                    st.innerHTML = '<option>' + LS_ALL + '</option>';
                    st.value = LS_ALL;
                    st.disabled = true;
                }
                /* sync ฟอร์ม 2 ช่องนี้จาก LS_APPLIED (เฉพาะตอนอยู่ tab list — tab อื่นไม่โชว์ ไม่ต้องยิง API) */
                function lsSync(){
                    if(!LS_MODE.list) return;
                    var gs = g('ldFGroupSel'); if(!gs) return;
                    if(LS_MODE.wf){
                        gs.innerHTML = '<option>' + LS_ALL + '</option>';
                        fillSelect(gs, LS_GROUPS);
                        gs.value = LS_APPLIED.group || LS_ALL;
                        if(!gs.value) gs.value = LS_ALL;
                        if(gs.selectedIndex > 0) lsSetSteps(gs.value, LS_APPLIED.step); else lsResetStep();
                    } else {
                        gs.innerHTML = '<option>' + LS_ALL + '</option>';
                        gs.value = LS_ALL;
                        lsSetSteps('', LS_APPLIED.step);
                    }
                }
                /* นับจำนวน filter ที่ active บน badge — นับตาม "หัวข้อ" (ทั้งหมด=ไม่นับ, ช่วงวันที่ 2 field=1, switch=1) */
                function countActiveFilters(){
                    var n = 0;
                    if(g('ldToggleStatus')) n++;   /* switch นับ 1 เสมอ (showClosed ส่งทุกครั้ง true/false ก็คือเลือกแล้ว) */
                    var df = g('ldDateFrom'), dt = g('ldDateTo');
                    if(df && dt && df.value && dt.value) n++;                                        /* ช่วงวันที่ (2 field นับ 1) */
                    if(document.querySelectorAll('#ldFilterOverlay .ld-f-chips .ld-f-chip').length) n++;  /* แท็ก (มี chip = 1) */
                    document.querySelectorAll('#ldFilterOverlay select.ld-f-sel').forEach(function(s){    /* เฉพาะ <select> ; tag เป็น button นับจาก chip แล้ว */
                        if(s.id === 'ldFGroupSel' || s.id === 'ldFStepSel') return;   /* นับแยกข้างล่าง — โชว์เฉพาะ tab list (+ กลุ่มเฉพาะ WF) */
                        var v = (s.value || '').trim();
                        if(v && v !== '' + env.t("label.contracts.filter_all") + '') n++;
                    });
                    if(LS_MODE.list){
                        var _fg = g('ldFGroupSel') ? (g('ldFGroupSel').value || '').trim() : '';
                        var _fs = g('ldFStepSel')  ? (g('ldFStepSel').value  || '').trim() : '';
                        if(LS_MODE.wf && _fg && _fg !== LS_ALL) n++;
                        if(_fs && _fs !== LS_ALL) n++;
                    }
                    return n;
                }
                function updateFilterBadge(){
                    var b = g('ldFilterBadge'); if(!b) return;
                    var n = countActiveFilters();
                    if(n > 0){ b.textContent = n; b.style.display = ''; }
                    else { b.style.display = 'none'; }
                }
                /* snapshot ค่าฟอร์ม filter ที่ "กรองอยู่จริง" — เก็บตอนกดกรอง, restore ตอนเปิด modal
                   เพื่อให้แก้แล้วปิดโดยไม่กดกรอง = ทิ้งค่าที่แก้ (กลับเป็นค่าที่ apply ล่าสุด) */
                var APPLIED_FILTER = null;
                function captureFilter(){
                    return {
                        showClosed: !!(g('ldToggleStatus') && g('ldToggleStatus').checked),
                        dateFrom: g('ldDateFrom') ? g('ldDateFrom').value : '',
                        dateTo:   g('ldDateTo')   ? g('ldDateTo').value   : '',
                        tagIds: Array.prototype.map.call(document.querySelectorAll('#ldTagPanel .ld-tag-cb:checked'), function(c){ return c.value; }),
                        selects: Array.prototype.map.call(document.querySelectorAll('#ldFilterOverlay select.ld-f-sel'), function(s){ return {id:s.id, val:s.value}; })
                    };
                }
                /* true ระหว่าง applyFilterToForm ตั้งค่า select — ให้ listener 'change' ของจังหวัดข้าม (ดูด้านบน) */
                var APPLYING_FORM = false;
                function applyFilterToForm(snap, onDistrictDone){
                    if(!snap) return;
                    if(g('ldToggleStatus')) g('ldToggleStatus').checked = snap.showClosed;
                    syncCloseStatusOptions();   /* rebuild options ตาม toggle ก่อน set ค่า select */
                    if(g('ldDateFrom')) g('ldDateFrom').value = snap.dateFrom || '';
                    if(g('ldDateTo'))   g('ldDateTo').value   = snap.dateTo || '';
                    document.querySelectorAll('#ldTagPanel .ld-tag-cb').forEach(function(c){ c.checked = (snap.tagIds||[]).indexOf(c.value) >= 0; });
                    var tagdd = g('ldTagDd'); if(tagdd && tagdd._render) tagdd._render();
                    /* select ทั่วไป set ตาม id ; อำเภอจัดการแยก (ขึ้นกับจังหวัด) */
                    var distSnap = null;
                    (snap.selects||[]).forEach(function(o){
                        if(o.id === 'ldDistrictSel'){ distSnap = o; return; }
                        if(o.id === 'ldFGroupSel' || o.id === 'ldFStepSel') return;   /* sync จาก LS_APPLIED ด้านล่าง (option โหลด async) */
                        var s = g(o.id);
                        if(s){
                            s.value = o.val;
                            /* ★ dispatch 'change' ต่อท้าย: open_down_select.js (dropdown กลางที่ครอบ <select> ทุกช่อง) ซิงก์ป้ายบนปุ่มตอนมี change
                               หรือ option ถูกแทนที่เท่านั้น — set .value ตรงๆ แล้วเปิด modal ซ้ำ ป้ายจะค้างเป็นค่าที่แก้ไว้แต่ยังไม่กด "กรอง"
                               (ค่าจริงถูกคืนแล้วแต่ป้ายโชว์ค่าอื่น → เข้าใจผิดว่ากรองด้วยค่านั้น) ; APPLYING_FORM กัน listener จังหวัดทำงานซ้ำ */
                            APPLYING_FORM = true;
                            try { s.dispatchEvent(new Event('change')); } finally { APPLYING_FORM = false; }
                        }
                    });
                    lsSync();
                    var prov = g('ldProvinceSel');
                    if(prov && prov.selectedIndex > 0) loadDistricts(prov.value, distSnap ? distSnap.val : null, onDistrictDone);
                    else { resetDistrict(); if(onDistrictDone) onDistrictDone(); }
                }
                /* master-data ของ modal ตัวกรอง (tags/sale-groups/provinces/employees) —
                   เดิม bean ยิง 4 เส้นนี้ตอนเข้าเพจแล้ว inject ลง JS ทำให้หน้า render ช้าโดยไม่จำเป็น
                   (ทั้ง 4 ใช้แค่ตอนเปิด modal ตัวกรอง ไม่มีผลกับบอร์ด/dropdown ผลิตภัณฑ์เลย)
                   ย้ายมาให้ browser ยิงเองผ่าน servlet ที่มีอยู่แล้ว ยิงขนานกันหลังหน้าโหลด
                   ★ ยิงเสร็จแล้วต้อง re-apply ค่า filter ที่ restoreFilterState() คืนไว้ซ้ำอีกรอบ
                     เพราะ restore ทำงานไปตั้งแต่ตอน <option> ยังว่าง (set .value ไม่ติด) —
                     RESTORED_SNAP เก็บ snapshot ก้อนเดิมไว้ให้ apply ซ้ำได้ */
                var RESTORED_SNAP = null;
                function loadFilterMasters(){
                    var pending = 4;
                    function done(){
                        if(--pending > 0) return;
                        initMasterDropdowns();
                        initTagDropdown();
                        if(!RESTORED_SNAP) return;
                        applyFilterToForm(RESTORED_SNAP, function(){
                            APPLIED_FILTER = captureFilter();   /* badge/สถานะ filter ให้ตรงกับที่ restore มา */
                            updateFilterBadge();
                        });
                    }
                    function grab(url, assign){
                        env.fetch(url, {credentials:'same-origin'})
                            .then(function(r){ return r.ok ? r.json() : null; })
                            .then(function(list){ if(Array.isArray(list)) assign(list); })
                            .catch(function(err){ console.warn('[lead] master-data fetch failed: ' + url, err); })
                            .then(done);   /* สำเร็จหรือพังก็นับ pending ลงเสมอ ไม่งั้น dropdown ไม่ถูกเติมเลย */
                    }
                    grab('../board/tags',        function(v){ TAGS        = v; if(window.ldSetTagColors) window.ldSetTagColors(v); });   /* สี pill แท็กบนการ์ด/ตาราง (colorCode) ใช้ master ชุดเดียวกัน ไม่ยิงซ้ำ */
                    grab('../board/sale-groups', function(v){ SALE_GROUPS = v; });
                    grab('../board/provinces',   function(v){ PROVINCES   = v; });
                    grab('../board/employees',   function(v){ EMPLOYEES   = v; });
                }
                /* ── FILTER DIALOG ── */
                function initFilter() {
                    /* initMasterDropdowns()/initTagDropdown() ย้ายไปเรียกใน loadFilterMasters()
                       ตอน master-data มาถึงแล้ว — ที่นี่ผูกเฉพาะ event ของ modal ซึ่งไม่ต้องรอข้อมูล */
                    loadFilterMasters();
                    var ov = g('ldFilterOverlay');
                    if(g('ldFilterBtn')) g('ldFilterBtn').addEventListener('click', function(e){
                        e.stopPropagation();
                        applyFilterToForm(APPLIED_FILTER);   /* เปิด modal → คืนค่าตาม filter ที่กรองอยู่จริง (ทิ้งค่าที่แก้ค้างไว้) */
                        ov.classList.add('show');
                    });
                    g('ldFilterClose').addEventListener('click', function(){ ov.classList.remove('show'); });
                    /* กลุ่มขั้นตอนเปลี่ยน → ขั้นตอนต้องอยู่ในกลุ่มนั้น : โหลดของกลุ่มใหม่ (ทั้งหมด = ล้าง + disabled) */
                    var _fgSelEl = g('ldFGroupSel');
                    if(_fgSelEl) _fgSelEl.addEventListener('change', function(){
                        if(_fgSelEl.selectedIndex === 0) lsResetStep(); else lsSetSteps(_fgSelEl.value, '');
                    });
                    if(g('ldFilterApply')) g('ldFilterApply').addEventListener('click', function(){
                        var showClosed = !!(g('ldToggleStatus') && g('ldToggleStatus').checked);   /* อ่าน switch → set showClosed ใหม่ */
                        var dateFrom = g('ldDateFrom') ? g('ldDateFrom').value : '';   /* ช่วงวันที่ field แรก */
                        var dateTo   = g('ldDateTo')   ? g('ldDateTo').value   : '';   /* ช่วงวันที่ field สอง */
                        /* อ่าน tags ที่ติ๊กไว้ — เลือกทั้งหมด (ทุกอัน) หรือไม่มีอัน → ไม่ส่ง param */
                        var _selTags = Array.prototype.map.call(document.querySelectorAll('#ldTagPanel .ld-tag-cb:checked'), function(c){ return c.value; });
                        var _totalTags = document.querySelectorAll('#ldTagPanel .ld-tag-cb').length;
                        var tags = (_selTags.length === 0 || _selTags.length === _totalTags) ? [] : _selTags;
                        var _pvSel = g('ldProvinceSel');
                        var _diSel = g('ldDistrictSel');
                        var province      = (_pvSel && _pvSel.value && _pvSel.value !== '' + env.t("label.contracts.filter_all") + '') ? _pvSel.value : '';
                        var district      = (_diSel && _diSel.value && _diSel.value !== '' + env.t("label.contracts.filter_all") + '') ? _diSel.value : '';
                        var _csSel         = g('ldCloseStatusSel');
                        var activeStatus   = (_csSel && _csSel.value !== '' + env.t("label.contracts.filter_all") + '') ? _csSel.value : '';
                        var _sgSel         = g('ldSaleGroupSel');
                        var saleGroup      = (_sgSel && _sgSel.value && _sgSel.value !== '' + env.t("label.contracts.filter_all") + '') ? _sgSel.value : '';
                        var _owSel         = g('ldOwnerSel');
                        var owner          = (_owSel && _owSel.value && _owSel.value !== '' + env.t("label.contracts.filter_all") + '') ? _owSel.value : '';
                        /* กลุ่มขั้นตอน/ขั้นตอน (เฉพาะ tab list) — tab อื่นฟอร์มสองช่องนี้ไม่ได้ sync → ส่งค่าที่กรองอยู่เดิมกลับไป ไม่ให้ถูกล้าง */
                        var fGroup = LS_APPLIED.group, fStep = LS_APPLIED.step;
                        if(LS_MODE.list){
                            var _fgSel = g('ldFGroupSel'), _fsSel = g('ldFStepSel');
                            fGroup = (LS_MODE.wf && _fgSel && _fgSel.value && _fgSel.value !== LS_ALL) ? _fgSel.value : '';
                            fStep  = (_fsSel && !_fsSel.disabled && _fsSel.value && _fsSel.value !== LS_ALL) ? _fsSel.value : '';
                        }
                        LS_APPLIED = { group: fGroup, step: fStep };
                        /* ★ CUR_* (filter จริงที่ยิง API leads) เป็นของ lead.xhtml (main) — ไฟล์นี้แยก closure
                           แก้ CUR_* ตรงๆ ไม่ได้ ส่งผ่าน window.ldApplyFilterValues ให้ main ตั้งค่า +
                           resetPaging()+loadLeads() ให้แทน (ดู bridge ท้าย IIFE หลักใน lead.xhtml) */
                        window.ldApplyFilterValues({
                            showClosed: showClosed, dateFrom: dateFrom, dateTo: dateTo, tags: tags,
                            province: province, district: district, activeStatus: activeStatus,
                            saleGroup: saleGroup, owner: owner,
                            fGroup: fGroup, fStep: fStep
                        });
                        updateFilterBadge();   /* อัปเดตเลขบน badge ตาม filter ที่กดกรอง */
                        APPLIED_FILTER = captureFilter();   /* บันทึกค่าที่กรองอยู่จริง */
                        ov.classList.remove('show');
                    });
                    if(g('ldFilterClear')) g('ldFilterClear').addEventListener('click', function(){
                        /* dispatch 'change' ต่อท้าย: open_down_select.js (dropdown กลางที่ครอบ <select> ทุกช่อง) ซิงก์ป้ายบนปุ่มตอนมี change
                           หรือ option ถูกแทนที่เท่านั้น — แค่ selectedIndex=0 ป้ายจะค้างเป็นค่าที่เลือกไว้ (ทีมขาย/จังหวัด/ผู้รับผิดชอบ) */
                        document.querySelectorAll('#ldFilterOverlay select.ld-f-sel').forEach(function(s){ s.selectedIndex=0; s.dispatchEvent(new Event('change')); });
                        document.querySelectorAll('#ldFilterOverlay .ld-f-input').forEach(function(i){ i.value=''; });
                        /* CUR_* เป็นของ main — เคลียร์ผ่าน bridge (ไม่ reload ตามพฤติกรรมเดิม) */
                        window.ldClearFilterValues();
                        resetDistrict();   /* จังหวัดกลับเป็นทั้งหมด → อำเภอ disable + ทั้งหมด */
                        LS_APPLIED = { group:'', step:'' };
                        /* ตั้งค่า 2 ช่องนี้ใหม่ด้วยการสร้าง option ใหม่ (ไม่ใช้ selectedIndex=0 ที่ด้านบนอย่างเดียว) — open_down_select.js
                           ซิงก์ป้ายบนปุ่ม dropdown ตอน option ถูกแทนที่/มี change เท่านั้น ถ้าแค่ selectedIndex=0 ป้ายจะค้างเป็นค่าเก่า
                           WF: กลุ่มเป็นทั้งหมด + ขั้นตอน disabled ; no-WF: ขั้นตอนเป็นทั้งหมด */
                        lsSync();
                        var tdd = g('ldTagDd'); if(tdd && tdd._reset) tdd._reset();   /* เคลียร์ tag (uncheck + ลบ chip) */
                        g('ldToggleStatus').checked = false;
                        syncCloseStatusOptions();   /* toggle reset → ตั้ง options กลับเป็นชุด (ปิด=open statuses) */
                    });
                    /* toggle เปลี่ยน → อัปเดต options ของ dropdown สถานะการปิด */
                    g('ldToggleStatus').addEventListener('change', syncCloseStatusOptions);
                    syncCloseStatusOptions();   /* ตั้ง options ครั้งแรกตาม state เริ่มต้นของ toggle */
                    updateFilterBadge();        /* badge เริ่มต้นตาม state default (ไม่มี filter = ซ่อน) */
                    APPLIED_FILTER = captureFilter();   /* snapshot ค่า default ไว้เป็น filter ที่กรองอยู่ตอนเข้าหน้า */
                    ov.addEventListener('click', function(e){ if(e.target===ov) ov.classList.remove('show'); });
                    /* กดช่องวันที่ (หรือไอคอนปฏิทิน) → เปิด native date picker */
                    document.querySelectorAll('#ldFilterOverlay .ld-f-date-input').forEach(function(inp){
                        inp.addEventListener('click', function(){ if(inp.showPicker){ try{ inp.showPicker(); }catch(e){} } });
                    });
                }

                /* bridge: เผยแพร่ให้ lead.xhtml (main) เรียกใช้ตอน page-init/restore filter จาก session
                   (main เรียก window.ldApplyFilterValues/ldClearFilterValues กลับมาให้ไฟล์นี้ด้วย — ดู
                   comment หัวไฟล์ + bridge ท้าย IIFE หลักใน lead.xhtml) */
                window.ldInitFilter = initFilter;
                window.ldSetRestoredSnap = function (v) { RESTORED_SNAP = v; };
                window.ldApplyFilterToForm = applyFilterToForm;
                window.ldRecaptureAppliedFilter = function () { APPLIED_FILTER = captureFilter(); updateFilterBadge(); };
                /* main เรียกทุกครั้งที่ response ของ leads กลับมา + ตอนสลับ tab — ตั้งโหมดของ 2 ช่อง กลุ่มขั้นตอน/ขั้นตอน
                   (โชว์/ซ่อนด้วย class บน overlay ; ตอน modal เปิดอยู่ไม่ sync ทับสิ่งที่ผู้ใช้กำลังแก้) */
                window.ldSetFilterMode = function (m) {
                    var ov = g('ldFilterOverlay'); if(!ov) return;
                    m = m || {};
                    LS_MODE = { list: !!m.list, wf: !!m.wf, mid: String(m.mid || '') };
                    LS_GROUPS = Array.isArray(m.groups) ? m.groups : [];
                    LS_APPLIED = { group: m.curGroup ? String(m.curGroup) : '', step: m.curStep ? String(m.curStep) : '' };
                    ov.classList.toggle('ld-fo-list', LS_MODE.list);
                    ov.classList.toggle('ld-fo-wf', LS_MODE.wf);
                    /* Angular: ไม่ยิงขั้นตอนของ popup ตอนสลับ tab — ยิงตอนเปิด popup (applyFilterToForm → lsSync) */
                    if(ov.classList.contains('show')) lsSync();
                    updateFilterBadge();
                };
        })();

  /* ════════════════ components/move_step_modal.xhtml · move-step modal ════════════════ */
/* context — เซ็ตตอนเปิด (leadId + procedureId = step ปลายทาง + onCancel = revert)
           gateKey (optional) = ชื่อตัวแปร global bool ที่หน้าเรียกประกาศไว้ (เช่น LD2_CAN_CONTACT_ACTIVITY_CREATE /
           LD2_CAN_CLOSE_WFSTEP ของ lead_detail.xhtml) — ใช้เฉพาะตอนเปิดจาก ldAddContactForStep/ldEndStepMove
           แต่ละอันประกาศ key ของตัวเอง — drag-drop ของ lead.xhtml ไม่ส่ง gateKey มา ไม่ถูกกระทบ
           gateAlsoCancel (optional) = true → disable ปุ่ม "ยกเลิก" ด้วย (เหลือแค่กากบาทที่ปิด modal ได้) */
        window._ldMsCtx = { leadId: '', procedureId: null, procedureGroupId: null, showRefTime: false, onCancel: null, onSuccess: null, gateKey: null, gateAlsoCancel: false };

        /* ★ 26/08: defense-in-depth — เช็ค owner-check ซ้ำตรงนี้เองด้วย ไม่พึ่ง window[gateKey] (ค่าที่
           lead_detail.xhtml recompute มาให้แล้ว) เพียงอย่างเดียว เผื่อกรณีเรียกก่อน recompute ทัน
           (เช่น เปิด modal นี้ก่อน lead data โหลดเสร็จ) — ★ ห้าม AND ทับ window[gateKey] ตรงๆ เพราะค่านั้น
           รวม _Sup (หัวหน้า ข้าม owner-check ได้) ไว้แล้ว ถ้า AND ซ้ำจะไปเบรค _Sup bypass โดยไม่ตั้งใจ
           แทนที่จะทำแบบนั้น คำนวณสูตรเดียวกันเอง (_Sup || (role หลัก && เป็นเจ้าของ lead)) จาก global
           LD2_SUP_<X>/LD2_ROLE_<X> ที่ lead_detail.xhtml ประกาศคู่กับ LD2_CAN_<X> เสมอ (ดู ld2RecomputeOwnerGatedRoles())
           gateKey อื่นที่ไม่ใช่จาก lead_detail.xhtml (ไม่มี LD2_SUP_.../ldOwnerIdMatchesMe ประกาศ) → fallback
           ไปใช้ window[gateKey] ตรงๆ เหมือนเดิม ไม่กระทบ */
        function ldMsGateAllowed(gateKey) {
            if (!gateKey) return true;
            var canVal = window[gateKey];
            if (canVal === undefined) return true;
            var supKey = gateKey.replace('LD2_CAN_', 'LD2_SUP_');
            var roleKey = gateKey.replace('LD2_CAN_', 'LD2_ROLE_');
            if (window[supKey] === undefined || window[roleKey] === undefined || typeof window.ldOwnerIdMatchesMe !== 'function')
                return canVal !== false;
            return !!(window[supKey] || (window[roleKey] && window.ldOwnerIdMatchesMe()));
        }

        /* เปิด/ปิดการใช้งาน tabs ช่องทาง + textarea + ปุ่มบันทึก (+ ปุ่มยกเลิก ถ้า alsoCancel) ตาม gateKey
           (undefined/true = ใช้งานได้ตามปกติ) */
        function ldMsApplyGate(gateKey, alsoCancel) {
            var allowed = ldMsGateAllowed(gateKey);
            document.querySelectorAll('#ld2MsTabs .ld2-ms-tab').forEach(function (t) { t.disabled = !allowed; });
            var ta = ldMsG('ld2MsText');
            if (ta) ta.disabled = !allowed;
            var dt = ldMsG('ld2MsDateTime');
            if (dt) dt.disabled = !allowed;
            var btn = ldMsG('ld2MsSubmitBtn');
            if (btn) btn.disabled = !allowed;
            var cancelBtn = ldMsG('ld2MsCancelBtn');
            if (cancelBtn) cancelBtn.disabled = alsoCancel ? !allowed : false;
        }

        function ldMsG(id) { return document.getElementById(id); }
        /* ทาสี badge กลุ่มขั้นตอน — แบบเดียวกับ wmApplyBadgeColor ของ work_modal */
        function ldMsApplyBadgeColor(el, color) {
            if (!el) return;
            var c = color || '#8A92A6';
            el.style.color = c;
            el.style.borderColor = c;
            el.style.background = c + '1A';
        }

        window.ldOpenMoveStep = function (opts) {
            opts = opts || {};
            var ov = ldMsG('ld2MoveStepOverlay');
            if (!ov) return;
            window._ldMsCtx = {
                leadId: (opts.leadId != null ? opts.leadId : ''),
                procedureId: (opts.procedureId != null && opts.procedureId !== '' ? opts.procedureId : null),
                procedureGroupId: (opts.procedureGroupId != null && opts.procedureGroupId !== '' ? Number(opts.procedureGroupId) : null),
                showRefTime: (opts.showRefTime === true),
                onCancel: (typeof opts.onCancel === 'function' ? opts.onCancel : null),
                onSuccess: (typeof opts.onSuccess === 'function' ? opts.onSuccess : null),
                gateKey: (opts.gateKey || null),
                gateAlsoCancel: !!opts.gateAlsoCancel
            };
            /* title — default "ย้ายขั้นตอน"; ส่ง opts.title = "เพิ่มการติดต่อ" เพื่อ reuse modal เดียวกัน (ยิง API เดียวกัน) */
            ldMsG('ld2MsTitle').textContent = opts.title || '' + env.t("label.ld2.move_step") + '';
            /* badge กลุ่มขั้นตอน + ขั้นตอน ข้าง title — ไม่มีค่าก็ซ่อนตัวนั้น
               badge กลุ่มแสดงเฉพาะ isMoveGroupStep === true (default false = ซ่อน)
               case "เพิ่มการติดต่อ" ไม่ส่ง group/step → ไม่แสดง tag */
            var showGroup = (opts.isMoveGroupStep === true) && !!opts.group;
            var grpEl = ldMsG('ld2MsGroup');
            grpEl.textContent = opts.group || '-';
            ldMsApplyBadgeColor(grpEl, opts.color);
            grpEl.style.display = showGroup ? '' : 'none';
            var stepEl = ldMsG('ld2MsStep');
            stepEl.textContent = opts.step || '-';
            stepEl.style.display = opts.step ? '' : 'none';
            ldMsG('ld2MsBadges').style.display = (showGroup || opts.step) ? '' : 'none';
            /* reset tab เป็น Note + เคลียร์ textarea */
            document.querySelectorAll('#ld2MsTabs .ld2-ms-tab').forEach(function (t) { t.classList.remove('active'); });
            var noteTab = document.querySelector('#ld2MsTabs .ld2-ms-tab[data-channel="manual"]');
            if (noteTab) noteTab.classList.add('active');
            ldMsG('ld2MsText').value = '';
            /* ช่อง "เวลาอ้างอิง" — แสดงเฉพาะ showRefTime, default = วัน/เวลาปัจจุบัน ณ ตอนเปิด (ไม่ใช่ตอนโหลดหน้า)
               format .value ของ datetime-local = "YYYY-MM-DDTHH:mm" เหมือน ld2CaDateTime ของ lead_detail */
            ldMsG('ld2MsDtWrap').style.display = window._ldMsCtx.showRefTime ? '' : 'none';
            if (window._ldMsCtx.showRefTime) {
                var now = new Date();
                ldMsG('ld2MsDateTime').value = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0') + '-' + String(now.getDate()).padStart(2, '0')
                        + 'T' + String(now.getHours()).padStart(2, '0') + ':' + String(now.getMinutes()).padStart(2, '0');
            }
            ldMsApplyGate(window._ldMsCtx.gateKey, window._ldMsCtx.gateAlsoCancel);
            ov.classList.add('show');
            /* tab กลับเป็น Note (ซ้ายสุด) — เลื่อนแถวกลับซ้ายด้วย เผื่อรอบก่อนลากค้างไว้ทางขวา
               ต้องตั้งหลัง show: ตอน overlay ยัง display:none ค่า scrollLeft ไม่ถูกเก็บ */
            ldMsG('ld2MsTabs').scrollLeft = 0;
        };
        /* ปิดเฉยๆ (ใช้หลังบันทึกสำเร็จ) — ไม่ revert */
        window.ldCloseMoveStep = function () {
            var ov = ldMsG('ld2MoveStepOverlay');
            if (ov) ov.classList.remove('show');
            window._ldMsCtx = { leadId: '', procedureId: null, procedureGroupId: null, onCancel: null, onSuccess: null };
        };
        /* ยกเลิก (กด X / คลิกนอก) → ปิด + เรียก onCancel (เช่น เด้งการ์ดกลับ column เดิม) */
        window.ldDismissMoveStep = function () {
            var cb = window._ldMsCtx ? window._ldMsCtx.onCancel : null;
            window.ldCloseMoveStep();
            if (cb) cb();
        };
        window.ldMsTab = function (btn) {
            document.querySelectorAll('#ld2MsTabs .ld2-ms-tab').forEach(function (t) { t.classList.remove('active'); });
            btn.classList.add('active');
        };

        /* success modal (checkmark) → auto-hide แล้วเรียก cb */
        function ldMsShowSuccess(message, cb) {
            var ov = document.createElement('div');
            ov.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;z-index:10001;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.45);opacity:0;transition:opacity .2s;';
            ov.innerHTML = '<div style="background:#fff;border-radius:16px;box-shadow:0 8px 32px rgba(0,0,0,.18);width:280px;padding:40px 24px;display:flex;flex-direction:column;align-items:center;gap:16px;">'
                + '<div style="width:56px;height:56px;border-radius:50%;border:2.5px solid #00C08B;display:flex;align-items:center;justify-content:center;"><i class="fas fa-check" style="color:#00C08B;font-size:24px;"></i></div>'
                + '<div style="font-size:16px;font-weight:700;color:#383838;text-align:center;">' + message + '</div>'
                + '</div>';
            document.body.appendChild(ov);
            __cleanups.push(function () { if (ov.parentNode) ov.parentNode.removeChild(ov); });
            requestAnimationFrame(function () {
                requestAnimationFrame(function () {
                    ov.style.opacity = '1';
                    tmo(function () {
                        ov.style.opacity = '0';
                        tmo(function () {
                            if (ov.parentNode) document.body.removeChild(ov);
                            if (typeof cb === 'function') cb();
                        }, 200);
                    }, 1500);
                });
            });
        }

        /* บันทึก → POST ../board/contact-activities (channel ตาม tab ที่เลือก) */
        window.ldSubmitMoveStep = function () {
            var ctx = window._ldMsCtx || {};
            if (!ldMsGateAllowed(ctx.gateKey)) return;   /* กันซ้ำเผื่อ submit ถูกเรียกตรงๆ ข้าม UI ที่ disabled ไว้ */
            var leadId = ctx.leadId;
            if (!leadId) { crmShowError('' + env.t("label.ld2.save_failed") + '!', '' + env.t("label.ld2.lead_id_not_found") + ''); return; }
            var activeTab = document.querySelector('#ld2MsTabs .ld2-ms-tab.active');
            var channel = activeTab ? (activeTab.getAttribute('data-channel') || 'manual') : 'manual';
            var ta = ldMsG('ld2MsText');
            var content = ta ? ta.value.trim() : '';

            var btn = ldMsG('ld2MsSubmitBtn');
            if (btn) { btn.disabled = true; btn.textContent = '' + env.t("label.ld2.saving") + ''; }
            var restore = function () { if (btn) { btn.disabled = false; btn.textContent = '' + env.t("chat.save") + ''; } };

            var _msBody = {
                leadId: leadId,
                channel: channel,
                content: content,
                procedureId: (ctx.procedureId != null ? ctx.procedureId : null)
            };
            /* procedureGroupId = กลุ่มขั้นตอนปัจจุบันของ lead — ไม่ส่งเลยถ้าไม่มี (lead ไม่ใช้ workflow step) ตาม spec contact-activities */
            if (ctx.procedureGroupId != null) _msBody.procedureGroupId = ctx.procedureGroupId;
            /* workRecordDate = เวลาอ้างอิง (เฉพาะ showRefTime) — เติม ":00" ให้เป็น "YYYY-MM-DDTHH:mm:ss" เหมือน ldSaveContactActivity
               ของ lead_detail; ช่องว่าง → null (เหมือนต้นฉบับ) / ไม่ได้เปิด showRefTime → ไม่ส่ง field นี้เลย */
            if (ctx.showRefTime) {
                var dtEl = ldMsG('ld2MsDateTime');
                var dtVal = dtEl ? (dtEl.value || '') : '';
                _msBody.workRecordDate = dtVal ? (dtVal + ':00') : null;
            }

            env.fetch('../board/contact-activities', {
                method: 'POST',
                credentials: 'same-origin',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(_msBody)
            }).then(function (res) {
                if (res.ok) {
                    var onSuccess = ctx.onSuccess;
                    window.ldCloseMoveStep();
                    /* มี onSuccess (เช่น lead.xhtml board) → ปิด modal เฉยๆ แล้วให้ผู้เรียก refresh เอง
                       ไม่ต้องมี success modal / reload หน้า — ไม่งั้นใช้พฤติกรรมเดิม */
                    if (onSuccess) {
                        onSuccess();
                    } else {
                        ldMsShowSuccess('' + env.t("label.ld2.save_success") + '', function () { env.reload(); });
                    }
                } else {
                    res.text().then(function (t) { crmShowError('' + env.t("label.ld2.save_failed") + '!', crmErrText(t)); });
                }
            }).catch(function (err) {
                crmShowError('' + env.t("label.ld2.save_failed") + '!', '' + env.t("label.ld2.error_occurred") + ': ' + (err && err.message ? err.message : err));
            }).finally(restore);
        };

        /* ★ 19/10 ลากเลื่อนแถวช่องทาง (ld2MsTabs) ด้วยเมาส์ — scrollbar ของแถวนี้ซ่อนอยู่ เมาส์ทั่วไปเลื่อนแนวนอนไม่ได้
           (ปุ่ม Facebook/LINE/WhatsApp ล้นขวาเกิน modal) — แนวเดียวกับ initListGrabScroll ของ lead.xhtml แต่ต่างจากตัวนั้น
           และ drag_scroll.js กลางตรงที่ "เริ่มลากบนปุ่มได้" เพราะทั้งแถวคือปุ่ม (ไม่มีพื้นที่ว่างให้จับ) แยกคลิก/ลากด้วยระยะ:
           ขยับไม่ถึง 5px = คลิกเลือกช่องทางตามปกติ ; เกิน = ลาก แล้วกลืน click ที่ตามหลังปล่อยเมาส์ (ไม่งั้นปล่อยแล้ว tab เปลี่ยน)
           จอสัมผัสเลื่อนเองได้อยู่แล้ว (overflow-x:auto) ไม่ต้องทำเพิ่ม */
        (function ldMsInitTabsDrag() {
            var wrap = document.getElementById('ld2MsTabs');
            if (!wrap) return;
            var TH = 5, down = false, moved = false, suppressClick = false, sx = 0, sl = 0;
            function endDrag() {
                if (!down) return;
                down = false;
                wrap.classList.remove('grabbing');
                if (moved) {
                    suppressClick = true;   /* click ตามหลัง mouseup ทันที — เคลียร์แฟลกหลังจากนั้น */
                    tmo(function () { suppressClick = false; }, 0);
                }
                moved = false;
            }
            wrap.addEventListener('mousedown', function (e) {
                if (e.button !== 0) return;
                if (wrap.scrollWidth <= wrap.clientWidth + 1) return;   /* ไม่ล้น (จอกว้างพอ) → คลิกปกติอย่างเดียว */
                down = true; moved = false;
                sx = e.clientX; sl = wrap.scrollLeft;
            });
            listen(document, 'mousemove', function (e) {
                if (!down) return;
                if (e.buttons === 0) { endDrag(); return; }   /* ปล่อยเมาส์นอกหน้าต่าง → mouseup ไม่ถึง document */
                var dx = e.clientX - sx;
                if (!moved) {
                    if (Math.abs(dx) < TH) return;   /* ยังเป็นแค่คลิก */
                    moved = true;
                    wrap.classList.add('grabbing');
                }
                e.preventDefault();
                wrap.scrollLeft = sl - dx;
            });
            listen(document, 'mouseup', endDrag);
            /* ไอคอนในปุ่มเป็น <img> — กัน browser ลากรูปออกมาเป็นภาพผี (แย่ง mousemove ทำให้ลากแถวไม่ไป) */
            wrap.addEventListener('dragstart', function (e) { e.preventDefault(); });
            /* capture ที่ document (ไม่ใช่ wrap): ดักก่อน onclick ของปุ่ม (inline window.ldMsTab) — และกันกรณีลากแล้วปล่อยเมาส์
               นอก dialog: click จะไปตกที่ overlay (บรรพบุรุษร่วมของจุดกด/จุดปล่อย) ซึ่งสั่งปิด modal ถ้าดักแค่ใน wrap จะหลุด */
            listen(document, 'click', function (e) {
                if (suppressClick) { suppressClick = false; e.stopPropagation(); e.preventDefault(); }
            }, true);
        })();

        (function () {
            var ov = document.getElementById('ld2MoveStepOverlay');
            if (ov) ov.addEventListener('click', function (e) {
                if (e.target === this) window.ldDismissMoveStep();
            });
        })();

  /* the entry points of the inline handlers and of the window.* functions */
  window.CAN_VIEW_LEAD_DETAIL = CAN_VIEW_LEAD_DETAIL;
  window.CAN_ROLE_CONTACT_ACTIVITY_CREATE = CAN_ROLE_CONTACT_ACTIVITY_CREATE;
  window.CAN_SUP_CONTACT_ACTIVITY_CREATE = CAN_SUP_CONTACT_ACTIVITY_CREATE;
  window.CAN_CONTACT_ACTIVITY_CREATE = CAN_CONTACT_ACTIVITY_CREATE;
  window.LEAD_MY_EMPLOYEE_ID = LEAD_MY_EMPLOYEE_ID;
  window.ldBoardOwnerMatches = ldBoardOwnerMatches;
  window.ldCanMoveLead = ldCanMoveLead;
  var EXPORTED = ["CAN_VIEW_LEAD_DETAIL","CAN_ROLE_CONTACT_ACTIVITY_CREATE","CAN_SUP_CONTACT_ACTIVITY_CREATE","CAN_CONTACT_ACTIVITY_CREATE","LEAD_MY_EMPLOYEE_ID","ldBoardOwnerMatches","ldCanMoveLead","ldSelectLead","LD_ASSIGNEES_MAP","LD_ACCESS_TITLE","ldCardToggle","_ldDATA","ldSetProduct","ldSaveFilterState","ldSetTagColors","ldApplyFilterValues","ldClearFilterValues","ldShowAccessPop","ldCloseAccessPop","ldStartCloseAccessPop","ldInitFilter","ldSetRestoredSnap","ldApplyFilterToForm","ldRecaptureAppliedFilter","ldSetFilterMode","_ldMsCtx","ldOpenMoveStep","ldCloseMoveStep","ldDismissMoveStep","ldMsTab","ldSubmitMoveStep"];

  /* "the document has been parsed": DOMContentLoaded handlers in the order they were registered, then "load" */
  readyState = 'interactive';
  runQueue(readyQueue, 'DOMContentLoaded');
  readyState = 'complete';
  tmo(function () { runQueue(loadQueue, 'load'); }, 0);

  return function destroy() {
    destroyed = true;
    disposers.splice(0).forEach(function (d) { d(); });
    timers.splice(0).forEach(function (h) { clearTimeout(h); });
    observers.splice(0).forEach(function (o) { o.disconnect(); });
    __cleanups.splice(0).forEach(function (f) { try { f(); } catch (e) {} });
    EXPORTED.forEach(function (n) { try { delete window[n]; } catch (e) { window[n] = undefined; } });
    document.documentElement.style.removeProperty('--ld-drop-hint-text');
    // what the page moved out of its own DOM: the popover (to .ld-col-body / <body>), the drag ghost (<body>)
    if (__pop && __pop.parentNode) __pop.parentNode.removeChild(__pop);
    Array.prototype.forEach.call(document.querySelectorAll('body > .ld-card'), function (n) { n.parentNode.removeChild(n); });
  };
}
